-- stage-lbar: перенос на прод (шаг 65): чанки редизайна и шаблоны как в git, адреса lbar.ro, чистка базы
-- Накатывать на базу ПРОДА сразу после импорта в неё дампа базы стейджа (со всеми патчами по 64-й). Затем очистить core/cache/.
SET NAMES utf8mb4;
-- все статичные чанки редизайна (содержимое — файлы core/elements/redesign/chunks/*.tpl из git)
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (266,1,0,'lb-head','Редизайн: подключения в head (шрифты, CSS)',0,128,0,'{* Подключения редизайна в <head>. Версию ?v= поднимаем при изменениях. *}\n<link rel=\"preload\" href=\"/assets/templates/redesign/fonts/playfair-display-latin-wght-normal.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n<link rel=\"preload\" href=\"/assets/templates/redesign/fonts/montserrat-latin-wght-normal.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n<link rel=\"stylesheet\" href=\"/assets/templates/redesign/css/redesign.css?v=1.45.0\">\n',0,NULL,1,'core/elements/redesign/chunks/lb-head.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (267,1,0,'lb-scripts','Редизайн: скрипты перед </body>',0,128,0,'{* Скрипты редизайна (перед </body>). *}\n<script src=\"/assets/templates/redesign/js/vendor/gsap.min.js\" defer></script>\n<script src=\"/assets/templates/redesign/js/vendor/ScrollTrigger.min.js\" defer></script>\n<script src=\"/assets/templates/redesign/js/redesign.js?v=1.45.0\" defer></script>\n{if $_modx->config.cultureKey == \'en\'}\n{* EN: после отправки формы — своя страница «Thank you» (1040). Старый обработчик af_complete в чанке script и в шаблоне «Обучение» (15) ведёт на RO 40 / RU 269 (RU для всех,\n   кроме RO); этот обработчик зарегистрирован после него и переназначает адрес (последнее присваивание location выигрывает). *}\n<script>\njQuery(document).on(\'af_complete\', function (e, r) {\n    if (r && r.success && r.form && [\'form-bl4\', \'form-bl8\', \'form-study-banner\', \'form-study-bl2\', \'form-study-bl6\', \'form-study-bl8\', \'form-study-bl11\', \'form-study-bl12\', \'form-study-bl14\', \'form-study-bl18\'].indexOf(r.form.attr(\'id\')) > -1) {\n        window.location.href = \'[[~1040]]\';\n    }\n});\n</script>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-scripts.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (292,1,0,'lb.navMega','Редизайн: мега-меню «Servicii / Услуги»',0,128,0,'{* Мега-меню пункта «Servicii / Услуги / Services» (шапка, вызывается из lb.navParent). Ссылки — дочерние ресурсы раздела, как и в прежнем\n   выпадающем списке (pdoMenu: опубликованные, не скрытые из меню; текст ссылки — menutitle, иначе pagetitle) — набор ссылок раздела не меняется.\n   Раскладка по колонкам (как в макете):\n     «Micropigmentare» — брови, глаза, губы, коррекция, удаление (id ниже, RO / RU / EN), «Sprâncene» — подразделы бровей (дети id 2 / 303 / 1002),\n     «Alte servicii» — все остальные дети раздела (новые услуги попадут сюда автоматически), «Acces rapid» — Gift Voucher (177 / 323 / 1177) +\n     «Despre mine» → страница «О нас» (102 / 298 / 1102; до шага 63 — блок «Мастер» главной, #lb-master), портфолио (100 / 198 / 1100),\n     цены (44 / 270 / 1044). EN-id = RO-id + 1000 (удаление тату EN 1625 — в «Micropigmentare» с шага 63, как RO 625 / RU 321).\n   Карточки «Рекомендуем» слева больше нет (убрана по просьбе пользователя). Подписи колонок — лексикон lbar.rd.mega.*.\n   Десктоп — панель под шапкой (наведение / фокус), мобильный — раскрывается кнопкой +, как прежние подменю. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $L = ($id == 302) ? \'ru\' : (($id == 1080) ? \'en\' : \'ro\')}\n{set $cfgs = [\n    \'ro\' => [\'brows\' => 2, \'micro\' => [2, 162, 167, 119, 625], \'quick\' => [177], \'about\' => 102, \'pages\' => [100, 44]],\n    \'ru\' => [\'brows\' => 303, \'micro\' => [303, 317, 319, 316, 321], \'quick\' => [323], \'about\' => 298, \'pages\' => [198, 270]],\n    \'en\' => [\'brows\' => 1002, \'micro\' => [1002, 1162, 1167, 1119, 1625], \'quick\' => [1177], \'about\' => 1102, \'pages\' => [1100, 1044]]\n]}\n{set $cfg = $cfgs[$L]}\n{set $opts = [\'sortby\' => [\'menuindex\' => \'ASC\', \'id\' => \'ASC\'], \'select\' => \'id,pagetitle,menutitle\', \'limit\' => 0]}\n{set $items = $_modx->getResources([\'parent\' => $id, \'published\' => 1, \'deleted\' => 0, \'hidemenu\' => 0], $opts)}\n{set $browsId = $cfg.brows}\n{set $brows = $_modx->getResources([\'parent\' => $browsId, \'published\' => 1, \'deleted\' => 0, \'hidemenu\' => 0], $opts)}\n{set $microIds = $cfg.micro}\n{set $quickIds = $cfg.quick}\n{set $byId = []}\n{foreach $items as $r}{set $byId[$r.id] = $r}{/foreach}\n{set $icons = [\n    163 => \'eye\', 318 => \'eye\', 627 => \'laser\', 628 => \'laser\', 168 => \'dots\', 320 => \'dots\',\n    1163 => \'eye\', 1627 => \'laser\', 1168 => \'dots\'\n]}\n{set $svg = [\n    \'lash\'  => \'<path d=\"M3 13c3.5-3 14.5-3 18 0\"/><path d=\"M6 11.2 5 8.5M9.5 10.3 9 7.3M14.5 10.3l.5-3M18 11.2l1-2.7\"/>\',\n    \'eye\'   => \'<path d=\"M2.5 12S6 6.5 12 6.5 21.5 12 21.5 12 18 17.5 12 17.5 2.5 12 2.5 12z\"/><circle cx=\"12\" cy=\"12\" r=\"2.8\"/>\',\n    \'laser\' => \'<path d=\"M13 2.5 5 13.5h6l-1 8 8-11h-6z\"/>\',\n    \'nail\'  => \'<path d=\"M9.5 9.5h5l1 11h-7z\"/><path d=\"M10.5 9.5V6a1.5 1.5 0 0 1 3 0v3.5M8.5 13.5h7\"/>\',\n    \'foot\'  => \'<path d=\"M8 21c-2.5 0-3.5-3-3-6.5S7 8 9.5 8.5 11 13 10.5 16 10 21 8 21zM15.5 17c-2 0-2.5-2.5-2.2-5s1.5-4.5 3.4-4.2 1.3 3.5.9 5.5-.4 3.7-2.1 3.7z\"/><circle cx=\"8.6\" cy=\"4.6\" r=\"1.2\"/><circle cx=\"16.4\" cy=\"4.4\" r=\"1\"/>\',\n    \'dots\'  => \'<circle cx=\"8\" cy=\"9\" r=\"1.3\"/><circle cx=\"15.5\" cy=\"7\" r=\".9\"/><circle cx=\"13\" cy=\"14.5\" r=\"1.6\"/><circle cx=\"6.5\" cy=\"16\" r=\".8\"/><circle cx=\"18\" cy=\"15\" r=\".8\"/>\',\n    \'spark\' => \'<path d=\"M12 3v4M12 17v4M3 12h4M17 12h4M6 6l2.5 2.5M15.5 15.5 18 18M18 6l-2.5 2.5M8.5 15.5 6 18\"/>\'\n]}\n{set $chev = \'<svg class=\"lb-mega__chev\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m9.5 6.5 5.5 5.5-5.5 5.5\"/></svg>\'}\n{set $pages = $_modx->getResources([\'id:IN\' => $cfg.pages, \'published\' => 1, \'deleted\' => 0], $opts)}\n{set $qicons = [100 => \'photo\', 198 => \'photo\', 1100 => \'photo\', 44 => \'coins\', 270 => \'coins\', 1044 => \'coins\']}\n{set $qsvg = [\n    \'gift\'  => \'<rect x=\"3.5\" y=\"8.5\" width=\"17\" height=\"4\" rx=\"1\"/><path d=\"M5 12.5v8h14v-8M12 8.5v12M12 8.5S10.5 4 8 4.5 7 8.5 12 8.5zM12 8.5S13.5 4 16 4.5 17 8.5 12 8.5z\"/>\',\n    \'user\'  => \'<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4.5 20.5c.8-4 3.8-6.5 7.5-6.5s6.7 2.5 7.5 6.5\"/>\',\n    \'cal\'   => \'<rect x=\"3.5\" y=\"5\" width=\"17\" height=\"15.5\" rx=\"2.5\"/><path d=\"M3.5 10h17M8 3v4M16 3v4M8 14h2M14 14h2M8 17h2\"/>\',\n    \'photo\' => \'<rect x=\"3\" y=\"4.5\" width=\"18\" height=\"15\" rx=\"2.5\"/><circle cx=\"8.5\" cy=\"9.5\" r=\"1.8\"/><path d=\"m3.5 17.5 5-4.5 3.5 3 3-2.5 5.5 4.5\"/>\',\n    \'coins\' => \'<ellipse cx=\"9\" cy=\"6.5\" rx=\"5.5\" ry=\"2.5\"/><path d=\"M3.5 6.5v4c0 1.4 2.5 2.5 5.5 2.5s5.5-1.1 5.5-2.5v-4\"/><path d=\"M9.5 15.5c.6 1.2 2.9 2 5.5 2 3 0 5.5-1.1 5.5-2.5v-4c0-1.2-1.8-2.2-4.3-2.4\"/><path d=\"M20.5 15v4c0 1.4-2.5 2.5-5.5 2.5s-5.5-1.1-5.5-2.5v-3.5\"/>\'\n]}\n<li{$classes | replace : \'class=\"\' : \'class=\"lb-nav__item--mega \'}><a class=\"lb-nav__link\" href=\"{$link}\" {$attributes}>{$menutitle}</a><button class=\"lb-nav__toggle\" type=\"button\" aria-label=\"{$menutitle}\" aria-expanded=\"false\"></button>\n    <div class=\"lb-mega\">\n        <div class=\"lb-mega__panel\">\n            <div class=\"lb-mega__col\">\n                <div class=\"lb-mega__h\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M2.5 14c4-5 11-6.5 19-2.5\"/><path d=\"M3.5 15.5c4-3.5 10-4.5 16-2\"/></svg>{\'lbar.rd.mega.micro\' | lexicon}</div>\n                <ul class=\"lb-mega__list\">\n                    {foreach $microIds as $mid}\n                    {if $byId[$mid]?}\n                    <li><a class=\"lb-mega__link\" href=\"{$_modx->makeUrl($mid)}\"><span>{$byId[$mid].menutitle ?: $byId[$mid].pagetitle}</span>{$chev}</a></li>\n                    {/if}\n                    {/foreach}\n                </ul>\n            </div>\n\n            {if $brows}\n            <div class=\"lb-mega__col\">\n                <div class=\"lb-mega__h\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 13.5C6.5 8 14 7 21 10\"/><path d=\"M5 12.5c.4-1 .9-1.8 1.5-2.5M8.5 10.3c.3-.9.7-1.6 1.2-2.2M12.3 9.4c.2-.8.5-1.5.9-2.1M16 9.4c.1-.7.3-1.4.6-2\"/></svg>{\'lbar.rd.mega.brows\' | lexicon}</div>\n                <ul class=\"lb-mega__list\">\n                    {foreach $brows as $r}\n                    <li><a class=\"lb-mega__link\" href=\"{$_modx->makeUrl($r.id)}\"><span>{$r.menutitle ?: $r.pagetitle}</span>{$chev}</a></li>\n                    {/foreach}\n                </ul>\n            </div>\n            {/if}\n\n            <div class=\"lb-mega__col\">\n                <div class=\"lb-mega__h\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 19.5c-3-2.5-4.5-5.5-4.5-8.5S9.5 5.5 12 4c2.5 1.5 4.5 4 4.5 7s-1.5 6-4.5 8.5z\"/><path d=\"M12 19.5c-4 .2-8-2.4-9-7 2.6-.5 4.7 0 6.3 1.2M12 19.5c4 .2 8-2.4 9-7-2.6-.5-4.7 0-6.3 1.2\"/></svg>{\'lbar.rd.mega.other\' | lexicon}</div>\n                <ul class=\"lb-mega__list lb-mega__list--ic\">\n                    {foreach $items as $r}\n                    {if !($r.id in $microIds) && !($r.id in $quickIds)}\n                    <li><a class=\"lb-mega__link\" href=\"{$_modx->makeUrl($r.id)}\"><svg class=\"lb-mega__ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">{$svg[$icons[$r.id] ?: \'spark\']}</svg><span>{$r.menutitle ?: $r.pagetitle}</span></a></li>\n                    {/if}\n                    {/foreach}\n                </ul>\n            </div>\n\n            <div class=\"lb-mega__col lb-mega__col--quick\">\n                <div class=\"lb-mega__h\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M10 14a4.5 4.5 0 0 0 6.4 0l3-3a4.5 4.5 0 0 0-6.4-6.4l-1.2 1.2\"/><path d=\"M14 10a4.5 4.5 0 0 0-6.4 0l-3 3a4.5 4.5 0 0 0 6.4 6.4l1.2-1.2\"/></svg>{\'lbar.rd.mega.quick\' | lexicon}</div>\n                <ul class=\"lb-mega__quick\">\n                    {foreach $quickIds as $qid}\n                    {if $byId[$qid]?}\n                    <li><a class=\"lb-mega__pill\" href=\"{$_modx->makeUrl($qid)}\"><svg class=\"lb-mega__ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">{$qsvg[\'gift\']}</svg><span>{$byId[$qid].menutitle ?: $byId[$qid].pagetitle}</span>{$chev}</a></li>\n                    {/if}\n                    {/foreach}\n                    {* «Despre mine» — страница «О нас» (Despre noi / О нас / About us) *}\n                    <li><a class=\"lb-mega__pill\" href=\"{$_modx->makeUrl($cfg.about)}\"><svg class=\"lb-mega__ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">{$qsvg[\'user\']}</svg><span>{\'lbar.rd.mega.aboutme\' | lexicon}</span>{$chev}</a></li>\n                    {foreach $pages as $r}\n                    <li><a class=\"lb-mega__pill\" href=\"{$_modx->makeUrl($r.id)}\"><svg class=\"lb-mega__ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">{$qsvg[$qicons[$r.id]]}</svg><span>{$r.menutitle ?: $r.pagetitle}</span>{$chev}</a></li>\n                    {/foreach}\n                </ul>\n            </div>\n        </div>\n    </div>\n</li>\n',0,NULL,1,'core/elements/redesign/chunks/lb.navMega.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (270,1,0,'lb.babelLink','Редизайн: tpl переключателя языка',0,128,0,'<li class=\"[[+active]]\"><a href=\"[[+url]]\" hreflang=\"[[+cultureKey]]\">[[+cultureKey]]</a></li>\n',0,NULL,1,'core/elements/redesign/chunks/lb.babelLink.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (268,1,0,'lb-header','Редизайн: шапка + мобильное меню',0,128,0,'{* Шапка (редизайн). Меню строится из дерева ресурсов. Без пунктов «Главная» (site_start контекста) и «Вакансии» (RO 105 / RU 299 / EN 1105 —\n   остаются в подвале). «Curs» (RO 182) и «Recenzii» (171 / 300 / 1171) — в корне дерева, «Instruire» (60) — веб-ссылка-редирект на курс, скрыта.\n   Родительские пункты — чанк lb.navParent; «Servicii / Услуги» — мега-меню lb.navMega.\n   Выбор языка — в правом блоке: десктоп — перед телефоном, мобильный — между телефоном и бургером (выпадающий список). *}\n{set $menu = $_modx->runSnippet(\'!pdoMenu\', [\n    \'level\' => 3,\n    \'parents\' => 0,\n    \'resources\' => \'-\' ~ $_modx->config.site_start ~ \',-105,-299,-1105\',\n    \'outerClass\' => \'lb-nav__list\',\n    \'rowClass\' => \'lb-nav__item\',\n    \'parentClass\' => \'lb-nav__item--parent\',\n    \'hereClass\' => \'lb-nav__item--active\',\n    \'selfClass\' => \'lb-nav__item--self\',\n    \'firstClass\' => \'\',\n    \'lastClass\' => \'\',\n    \'levelClass\' => \'\',\n    \'tpl\' => \'@INLINE <li[[+classes]]><a class=\"lb-nav__link\" href=\"[[+link]]\" [[+attributes]]>[[+menutitle]]</a>[[+wrapper]]</li>\',\n    \'tplParentRow\' => \'lb.navParent\',\n    \'tplInner\' => \'@INLINE <ul class=\"lb-nav__sub\">[[+wrapper]]</ul>\',\n    \'tplCategoryFolder\' => \'@INLINE <li[[+classes]]><span class=\"lb-nav__link\">[[+menutitle]]</span>[[+wrapper]]</li>\',\n])}\n<header class=\"lb-header\" id=\"lb-header\">\n    <div class=\"lb-header__bar\"></div>\n    <div class=\"lb-header__inner\">\n        <a class=\"lb-header__logo\" href=\"[[++site_url]]\" aria-label=\"[[++site_name]]\"><img src=\"/assets/templates/redesign/img/logo.svg?v=3\" width=\"242\" height=\"119\" alt=\"LBar\" loading=\"eager\"></a>\n\n        <div class=\"lb-mnav\" id=\"lb-mnav\">\n            <nav class=\"lb-nav\" aria-label=\"{\'lbar.rd.aria.nav\' | lexicon}\">\n                {$menu}\n            </nav>\n            <div class=\"lb-mnav__foot\">\n                <a class=\"lb-mnav__phone\" href=\"tel:[[++phone-1:replace=` ==`]]\">[[++phone-1]]</a>\n                <p class=\"lb-mnav__addr\">\n                    <a href=\"{\'lbar.rd.contacts.mapurl\' | lexicon}\" target=\"_blank\" rel=\"nofollow noopener\">{\'lbar.rd.contacts.city\' | lexicon}<br>\n                    {\'lbar.rd.contacts.street\' | lexicon}</a><br>\n                    {\'lbar.rd.header.days\' | lexicon}: [[++schedule]]\n                </p>\n                <a class=\"lb-btn lb-btn--solid lb-mnav__cta js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n            </div>\n        </div>\n\n        <div class=\"lb-header__right\">\n            <div class=\"lb-lang\">\n                <button class=\"lb-lang__btn\" type=\"button\" aria-haspopup=\"true\" aria-expanded=\"false\" aria-controls=\"lb-lang-list\"><span>{$_modx->config.cultureKey}</span><span class=\"lb-sr\"> – {\'lbar.rd.aria.lang\' | lexicon}</span><svg class=\"lb-lang__chev\" viewBox=\"0 0 10 6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 1l4 4 4-4\"/></svg></button>\n                <ul class=\"lb-lang__list\" id=\"lb-lang-list\">\n                    [[!BabelLinks? &showCurrent=`1` &tpl=`lb.babelLink`]]\n                </ul>\n            </div>\n            <a class=\"lb-header__phone\" href=\"tel:[[++phone-1:replace=` ==`]]\">\n                <span class=\"lb-header__phone-ic\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 16.4v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 1.1 3.7 2 2 0 0 1 3.1 1.5h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L7.1 9.3a16 16 0 0 0 6 6l1.2-1.2a2 2 0 0 1 2.1-.5c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.8 2.1z\"/></svg></span>\n                <span>[[++phone-1]]</span>\n            </a>\n            <a class=\"lb-btn lb-btn--solid lb-header__cta js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n            <button class=\"lb-header__burger\" type=\"button\" aria-label=\"{\'lbar.rd.aria.burger\' | lexicon}\" aria-controls=\"lb-mnav\" aria-expanded=\"false\"><span></span><span></span></button>\n        </div>\n    </div>\n</header>\n{* основное содержимое страницы — landmark <main> (PageSpeed: «Document has a main landmark»); закрывается в начале lb-footer *}\n<main class=\"lb-main\" id=\"lb-main\">\n',0,NULL,1,'core/elements/redesign/chunks/lb-header.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (269,1,0,'lb-banner-main','Редизайн: главный баннер',0,128,0,'{* Главный баннер (редизайн).\n   H1 — TV title-banner, исходный текст сайта («Micropigmentare Bucuresti Studio Lbar» / «Перманентный макияж в Бухаресте от LBar»).\n   Разбивка на три строки композиции макета (обычная / крупный курсив / мелкая) — лексикон lbar.rd.hero.title («|» — граница строк);\n   применяется, только если без «|» он совпадает с TV, иначе H1 — одной строкой. «|» прямо в TV тоже работает. Подзаголовок — TV suptitle-banner.\n   Длинная 2-я строка (больше 9 знаков, RU «в Бухаресте») — мельче (lb-hero__title--t2l), чтобы строка помещалась.\n   Кнопки — как на исходном сайте: «Fă o programare» (скролл к форме #bl8-form) и «Primește o consultație» (скролл к «Контактам» #conract). *}\n{set $tb = $_modx->resource[\'title-banner\'] | trim}\n{set $lay = \'lbar.rd.hero.title\' | lexicon}\n{if !($tb | ematch : \'~[|]~\') && ($lay | replace : \'|\' : \' \') == $tb}{set $tb = $lay}{/if}\n{set $parts = $tb | split : \'|\'}\n{set $img = \'/assets/templates/redesign/img/\'}\n<section class=\"lb-hero\" id=\"lb-hero\">\n    {* Сцена (десктоп): фон без декора + буквы «BAR», линия и арки (SVG, чёткие на любом экране) + мастер (вырезка, отдельный слой).\n       На мобильном — одна картинка hero-mobile-v2.webp (фон + мастер, _dev/hero2/make_hero.py), слои скрыты; мастер на мобильном не скачивается (пустой source). *}\n    {set $px = \'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7\'}\n    <div class=\"lb-hero__bg\">\n        <div class=\"lb-hero__scene\">\n            <picture class=\"lb-hero__pic\">\n                <source media=\"(max-width: 1024px)\" srcset=\"{$img}hero-mobile-v2.webp\" width=\"1060\" height=\"1107\">\n                <img src=\"{$img}hero-bg.webp\" srcset=\"{$img}hero-bg-1440.webp 1440w, {$img}hero-bg.webp 2166w, {$img}hero-bg-2880.webp 2880w\" sizes=\"100vw\" width=\"2166\" height=\"1218\" alt=\"{\'lbar.rd.hero.alt\' | lexicon}\" loading=\"eager\" fetchpriority=\"high\" decoding=\"async\">\n            </picture>\n            <div class=\"lb-hero__art\" aria-hidden=\"true\">\n                <img class=\"lb-hero__arches\" src=\"{$img}hero-arches.svg\" width=\"220\" height=\"600\" alt=\"\" loading=\"eager\">\n                <img class=\"lb-hero__vline\" src=\"{$img}hero-line.svg\" width=\"44\" height=\"660\" alt=\"\" loading=\"eager\">\n                <img class=\"lb-hero__letters\" src=\"{$img}hero-letters.svg\" width=\"912\" height=\"410\" alt=\"\" loading=\"eager\">\n            </div>\n            <div class=\"lb-hero__deco\" aria-hidden=\"true\">\n                <span class=\"lb-hero__spark lb-hero__spark--p1\"><svg viewBox=\"0 0 40 40\"><path fill=\"currentColor\" d=\"M20 0c.9 10.6 8.4 18.6 20 20-11.6 1.4-19.1 9.4-20 20-.9-10.6-8.4-18.6-20-20C11.6 18.6 19.1 10.6 20 0z\"/></svg></span>\n                <span class=\"lb-hero__spark lb-hero__spark--s lb-hero__spark--p2\"><svg viewBox=\"0 0 40 40\"><path fill=\"currentColor\" d=\"M20 0c.9 10.6 8.4 18.6 20 20-11.6 1.4-19.1 9.4-20 20-.9-10.6-8.4-18.6-20-20C11.6 18.6 19.1 10.6 20 0z\"/></svg></span>\n                <span class=\"lb-hero__spark lb-hero__spark--s lb-hero__spark--p3\"><svg viewBox=\"0 0 40 40\"><path fill=\"currentColor\" d=\"M20 0c.9 10.6 8.4 18.6 20 20-11.6 1.4-19.1 9.4-20 20-.9-10.6-8.4-18.6-20-20C11.6 18.6 19.1 10.6 20 0z\"/></svg></span>\n                <span class=\"lb-hero__spark lb-hero__spark--p4\"><svg viewBox=\"0 0 40 40\"><path fill=\"currentColor\" d=\"M20 0c.9 10.6 8.4 18.6 20 20-11.6 1.4-19.1 9.4-20 20-.9-10.6-8.4-18.6-20-20C11.6 18.6 19.1 10.6 20 0z\"/></svg></span>\n                <span class=\"lb-hero__spark lb-hero__spark--s lb-hero__spark--p5\"><svg viewBox=\"0 0 40 40\"><path fill=\"currentColor\" d=\"M20 0c.9 10.6 8.4 18.6 20 20-11.6 1.4-19.1 9.4-20 20-.9-10.6-8.4-18.6-20-20C11.6 18.6 19.1 10.6 20 0z\"/></svg></span>\n            </div>\n            <picture class=\"lb-hero__master\" aria-hidden=\"true\">\n                <source media=\"(max-width: 1024px)\" srcset=\"{$px}\">\n                <img src=\"{$img}hero-master-v2.webp\" srcset=\"{$img}hero-master-v2.webp 570w, {$img}hero-master-v2-2x.webp 1140w\" sizes=\"30vw\" width=\"570\" height=\"760\" alt=\"\" loading=\"eager\" decoding=\"async\">\n            </picture>\n        </div>\n    </div>\n\n    <div class=\"lb-hero__content\">\n        {if $parts | length > 2}\n        <h1 class=\"lb-hero__title{($parts[1] | trim | length) > 9 ? \' lb-hero__title--t2l\' : \'\'}\"><span class=\"lb-hero__t1\">{$parts[0] | trim}</span> <span class=\"lb-hero__t2\">{$parts[1] | trim}</span> <span class=\"lb-hero__t3\">{$parts[2] | trim}</span></h1>\n        {elseif $tb}\n        <h1 class=\"lb-hero__title lb-hero__title--plain\">{$tb}</h1>\n        {/if}\n        <span class=\"lb-hero__line\" aria-hidden=\"true\"></span>\n        {if $_modx->resource[\'suptitle-banner\']}\n        <p class=\"lb-hero__sub\">{$_modx->resource[\'suptitle-banner\']}</p>\n        {/if}\n        <div class=\"lb-hero__btns\">\n            <a class=\"lb-btn lb-btn--solid js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n            <a class=\"lb-btn lb-btn--ghost\" href=\"#conract\">{\'lbar.buttons.banner.consultation\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n        </div>\n    </div>\n\n    <ul class=\"lb-hero__cards\">\n        {* преимущества: число / подпись — лексикон lbar.rd.hero.cardN.num / .txt; иконки — бриллиант, песочные часы, корона *}\n        <li class=\"lb-card\">\n            <span class=\"lb-card__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 56 44\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"><path d=\"M12 2h32l10 12-26 28L2 14 12 2z\"/><path d=\"M2 14h52M12 2l8 12 8-12 8 12 8-12M20 14l8 28 8-28\"/></svg></span>\n            <span class=\"lb-card__num\">{\'lbar.rd.hero.card1.num\' | lexicon}</span>\n            <span class=\"lb-card__txt\">{\'lbar.rd.hero.card1.txt\' | lexicon}</span>\n        </li>\n        <li class=\"lb-card\">\n            <span class=\"lb-card__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 36 46\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 2h26M5 44h26\"/><path d=\"M8 2c0 8.5 3.6 13.5 10 21 6.4-7.5 10-12.5 10-21\"/><path d=\"M8 44c0-8.5 3.6-13.5 10-21 6.4 7.5 10 12.5 10 21\"/><path d=\"M12.5 9.5h11M18 23v6M11.5 40.5c1.6-3.6 3.8-6 6.5-7.8 2.7 1.8 4.9 4.2 6.5 7.8z\"/></svg></span>\n            <span class=\"lb-card__num\">{\'lbar.rd.hero.card2.num\' | lexicon}</span>\n            <span class=\"lb-card__txt\">{\'lbar.rd.hero.card2.txt\' | lexicon}</span>\n        </li>\n        <li class=\"lb-card\">\n            <span class=\"lb-card__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 54 44\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"><path d=\"M6 14l10 12 11-20 11 20 10-12-4 22H10L6 14z\"/><path d=\"M10 41h34\"/><circle cx=\"27\" cy=\"4.5\" r=\"2.6\"/><circle cx=\"5\" cy=\"12\" r=\"2.4\"/><circle cx=\"49\" cy=\"12\" r=\"2.4\"/></svg></span>\n            <span class=\"lb-card__num\">{\'lbar.rd.hero.card3.num\' | lexicon}</span>\n            <span class=\"lb-card__txt\">{\'lbar.rd.hero.card3.txt\' | lexicon}</span>\n        </li>\n    </ul>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-banner-main.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (271,1,0,'lb-about','Редизайн: блок «О микропигментации» (главная)',0,128,0,'{* Блок «О микропигментации» (редизайн, 2-й экран главной; на страницах услуг — вместо bl1-about-us).\n   Заголовок и текст — прежние TV: title_bl1_about, text_bl1_about.\n   Часть заголовка после тире выводится курсивом. Текст свёрнут до 3 строк (на услугах — до 7).\n   Надзаголовков (eyebrow) нет — убраны по просьбе пользователя, как во всех блоках.\n   Страницы услуг (модификатор --svc): без преимуществ и цитаты главной; фото — TV img_bl1_about\n   (если задано — поверх фото фона в той же рамке; если нет — фото фона). Фон с фото в рамке — кадр пользователя (about-bg-v2 / about-mobile-v2,\n   _dev/hero2/make_about.py), печати «Studio LBar» нет. «Citește mai mult» — под текстом.\n   Удаление тату (шаблон «Удаление тату», шаг 54, вызов с &tz=`1`): TV старого блока bl1-about-service — заголовок\n   bl1_about_service-title (был H2 — остаётся H2; span.gold-word — только оформление, текст тот же), текст text_1, подзаголовок title_2\n   (H3, если заполнен) + text_2, примечание text_3; фото — bl1_about_service-img. *}\n{* параметр &tz из вызова чанка в шаблоне: MODX-плейсхолдер подставляется до Fenom (без параметра остаётся «[[+tz]]» → не 1) *}\n{set $tz = (\'[[+tz]]\' == \'1\')}\n{set $r = $_modx->resource}\n{set $title = ($tz ? ($r[\'bl1_about_service-title\'] | striptags) : $r[\'title_bl1_about\']) | trim}\n{set $dash = \'\'}\n{if \' — \' in $title}{set $dash = \'—\'}{elseif \' – \' in $title}{set $dash = \'–\'}{/if}\n{set $tp = ($dash ? ($title | split : (\' \' ~ $dash ~ \' \')) : [$title])}\n{if $tz}\n{set $t2 = $r[\'bl1_about_service-title_2\'] | striptags | trim}\n{set $text = ($r[\'bl1_about_service-text_1\'] | trim) ~ ($t2 ? (\'<h3>\' ~ $t2 ~ \'</h3>\') : \'\') ~ ($r[\'bl1_about_service-text_2\'] | trim) ~ ($r[\'bl1_about_service-text_3\'] | trim)}\n{else}\n{set $text = $r[\'text_bl1_about\']}\n{/if}\n{set $img = \'/assets/templates/redesign/img/\'}\n{set $svc = $_modx->resource.id != $_modx->config.site_start}\n{set $photo = $tz ? ($r[\'bl1_about_service-img\'] | trim | ereplace : \'~^/+~\' : \'\') : ($svc ? (\'[[*img_bl1_about]]\' | trim) : \'\')}\n<div id=\"bl1\"></div>\n<section class=\"lb-about{$svc ? \' lb-about--svc\' : \'\'}\" id=\"lb-about\">\n    <div class=\"lb-about__bg\">\n        <picture>\n            <source media=\"(max-width: 1024px)\" srcset=\"{$img}about-mobile-v2.webp\" width=\"840\" height=\"1090\">\n            <img src=\"{$img}about-bg-v2.webp\" srcset=\"{$img}about-bg-v2-1440.webp 1440w, {$img}about-bg-v2.webp 2166w\" sizes=\"100vw\" width=\"2166\" height=\"1218\" alt=\"{$photo ? \'\' : (\'lbar.rd.about.alt\' | lexicon)}\" loading=\"lazy\" decoding=\"async\">\n        </picture>\n        {if $photo}\n        <img class=\"lb-about__photo\" src=\"/{$photo | replace : \' \' : \'%20\'}\" alt=\"{$title | escape}\" width=\"540\" height=\"850\" loading=\"lazy\" decoding=\"async\">\n        {/if}\n    </div>\n\n    <div class=\"lb-about__col\">\n        {if $title}\n        <{$tz ? \'h2\' : \'div\'} class=\"lb-about__title{($svc && ($title | length) > 40) ? \' lb-about__title--long\' : \'\'}\">\n            {if $tp | length > 1}\n            <span class=\"lb-about__t1\">{$tp[0]}&nbsp;{$dash}</span>\n            <span class=\"lb-about__t2\">{$tp[1]}</span>\n            {else}\n            <span class=\"lb-about__t1\">{$title}</span>\n            {/if}\n        </{$tz ? \'h2\' : \'div\'}>\n        {/if}\n\n        {if $text}\n        <div class=\"lb-about__textwrap\">\n            <div class=\"lb-about__text\" id=\"lb-about-text\">{$text}</div>\n            <button class=\"lb-about__more\" type=\"button\" aria-controls=\"lb-about-text\" aria-expanded=\"false\">\n                <span class=\"lb-about__moretxt\">{\'lbar.rd.about.more\' | lexicon}</span><span class=\"lb-about__less\">{\'lbar.rd.about.less\' | lexicon}</span>\n                <svg viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2.5 4.5 6 8l3.5-3.5\"/></svg>\n            </button>\n        </div>\n        {/if}\n\n        {if !$svc}\n        <ul class=\"lb-about__list\">\n            <li class=\"lb-about__item\">\n                <span class=\"lb-about__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 29 27 9\"/><path d=\"M27.5 8.5c-5.5-1.8-13.4.8-16.6 7.8-1.6 3.4-1.7 7-1.3 9.9 3 .5 6.6.2 10-1.4 7-3.3 9.6-11 7.9-16.3z\"/><path d=\"M12.5 21h6.5M15.5 17.5h6M19 14h4.5\"/></svg></span>\n                <span class=\"lb-about__label\">{\'lbar.rd.about.f1\' | lexicon}</span>\n            </li>\n            <li class=\"lb-about__item\">\n                <span class=\"lb-about__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.35\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"18\" cy=\"18\" r=\"12.5\"/><path d=\"M18 10.5V18l5 4\"/></svg></span>\n                <span class=\"lb-about__label\">{\'lbar.rd.about.f2\' | lexicon}</span>\n            </li>\n            <li class=\"lb-about__item\">\n                <span class=\"lb-about__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 36 36\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.35\" stroke-linejoin=\"round\"><path d=\"M13 13c.5 4.6 2.9 7 7.5 7.5-4.6.5-7 2.9-7.5 7.5-.5-4.6-2.9-7-7.5-7.5 4.6-.5 7-2.9 7.5-7.5z\"/><path d=\"M24.5 6c.3 2.9 1.8 4.4 4.7 4.7-2.9.3-4.4 1.8-4.7 4.7-.3-2.9-1.8-4.4-4.7-4.7 2.9-.3 4.4-1.8 4.7-4.7z\"/></svg></span>\n                <span class=\"lb-about__label\">{\'lbar.rd.about.f3\' | lexicon}</span>\n            </li>\n        </ul>\n\n        <div class=\"lb-about__quote\">\n            <svg class=\"lb-about__qmark\" viewBox=\"0 0 55 44\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M12.6 44C5.3 44 0 38.6 0 31.4 0 19.6 9.6 6.4 22.3 0l2.2 3.3C16.8 8.2 12 14.6 11.3 20.4c.7-.2 1.5-.3 2.3-.3 6.4 0 11.3 5 11.3 11.7S19.8 44 12.6 44zm30.1 0c-7.3 0-12.6-5.4-12.6-12.6C30.1 19.6 39.7 6.4 52.4 0l2.2 3.3C46.9 8.2 42.1 14.6 41.4 20.4c.7-.2 1.5-.3 2.3-.3 6.4 0 11.3 5 11.3 11.7S49.9 44 42.7 44z\"/></svg>\n            <p class=\"lb-about__qtext\">{\'lbar.rd.about.quote\' | lexicon}</p>\n        </div>\n        {/if}\n\n        <a class=\"lb-btn lb-btn--solid lb-about__cta\" href=\"#form-bl4\">{\'lbar.rd.about.cta\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-about.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (272,1,0,'lb.serviceCard','Редизайн: tpl карточки услуги',0,128,0,'{* Карточка услуги (pdoResources tpl). Фото — из макета для трёх услуг главной, для остальных — TV im-category. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $map = [2 => \'brows\', 303 => \'brows\', 1002 => \'brows\', 162 => \'eyeliner\', 317 => \'eyeliner\', 1162 => \'eyeliner\', 167 => \'lips\', 319 => \'lips\', 1167 => \'lips\']}\n{set $title = $_pls[\'tv.title-bl2\'] ?: $menutitle ?: $pagetitle}\n{set $src = $map[$id] ? (\'/assets/templates/redesign/img/service-\' ~ $map[$id] ~ \'.webp\') : $_pls[\'tv.im-category\']}\n<article class=\"lb-scard\">\n    <a class=\"lb-scard__img\" href=\"{$uri}\" aria-label=\"{$title | escape}\">\n        <img src=\"{$src}\" alt=\"{($_pls[\'tv.alt-im-category\'] ?: $title) | escape}\" width=\"498\" height=\"483\" loading=\"lazy\" decoding=\"async\">\n    </a>\n    <div class=\"lb-scard__body\">\n        <div class=\"lb-scard__num\" aria-hidden=\"true\">{$idx < 10 ? \'0\' : \'\'}{$idx}</div>\n        <div class=\"lb-scard__title\"><a href=\"{$uri}\">{$title}</a></div>\n        <div class=\"lb-scard__text\">{$_pls[\'tv.intro-text-bl2\']}</div>\n        <a class=\"lb-btn lb-btn--ghost lb-btn--sm lb-scard__btn\" href=\"{$uri}\">{\'lbar.buttons.category.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.serviceCard.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (273,1,0,'lb-services','Редизайн: блок «Услуги» (главная)',0,128,0,'{* Блок «Услуги» (редизайн, 3-й экран главной).\n   Заголовок, подзаголовок и список услуг — прежние TV: main-title-bl2, sub-title-bl2, id-bl2.\n   Карточка — чанк lb.serviceCard. Порядок — menuindex, при равном — id (шаг 65); в sortby после «{» пробел — иначе это тег Fenom. *}\n<section class=\"lb-services\" id=\"lb-services\">\n    <div class=\"lb-services__bg\" aria-hidden=\"true\">\n        <img src=\"/assets/templates/redesign/img/services-bg.webp?v=2\" srcset=\"/assets/templates/redesign/img/services-bg-1440.webp?v=2 1440w, /assets/templates/redesign/img/services-bg.webp?v=2 2166w\" sizes=\"100vw\" width=\"2166\" height=\"1218\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n    </div>\n\n    <div class=\"lb-services__intro\">\n        {if $_modx->resource[\'main-title-bl2\']}\n        <h2 class=\"lb-services__title\">{$_modx->resource[\'main-title-bl2\']}</h2>\n        {/if}\n        {if $_modx->resource[\'sub-title-bl2\']}\n        <div class=\"lb-services__text\">{$_modx->resource[\'sub-title-bl2\']}</div>\n        {/if}\n    </div>\n\n    <div class=\"lb-services__list\">\n        [[pdoResources?\n            &parents=`0`\n            &resources=`[[*id-bl2]]`\n            &limit=`12`\n            &tpl=`lb.serviceCard`\n            &sortby=`{ \"menuindex\": \"ASC\", \"id\": \"ASC\" }`\n            &includeTVs=`im-category,alt-im-category,intro-text-bl2,title-bl2`\n        ]]\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-services.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (274,1,0,'lb-implica','Редизайн: блок «Micropigmentarea … implică» (главная)',0,128,0,'{* Блок «Micropigmentarea … implică:» (редизайн, 4-й экран главной).\n   Тексты — прежние TV: title-main-bl3 (H2), title-1..3-bl3, text-1..3-bl3.\n   Разбивка H2 на строки и курсив — из лексикона lbar.rd.implica.title: «|» — перенос строки, *слово* — курсив.\n   Если TV заголовка изменят и он перестанет совпадать с лексиконом, заголовок выводится как есть (без разбивки и курсива).\n   Страницы услуг (вместо bl3-text, модификатор --svc): заголовок — курсив после тире / двоеточия (lb.accent), надзаголовков нет\n   (на главной «LBAR STUDIO» тоже убран), вместо иконок — номера 01–03 (как в старом блоке); фото — TV im-1-bl3 (alt — alt-im-1-bl3)\n   в круге на месте фото главной (--photo), фон — тон блока; нет фото — фон главной (implica-bg-v2 — кадр пользователя).\n   Кнопка с «плеем» — видео студии на YouTube в окне fancybox (подключён в старом main.js), текст — lbar.rd.implica.video. *}\n{set $title = $_modx->resource[\'title-main-bl3\'] | trim}\n{set $fmt = \'lbar.rd.implica.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n{set $video = \'https://www.youtube.com/watch?v=2xwQU_Vt1ys\'}\n{set $img = \'/assets/templates/redesign/img/\'}\n{set $svc = $_modx->resource.id != $_modx->config.site_start}\n{set $photo = $svc ? (\'[[*im-1-bl3]]\' | trim) : \'\'}\n{set $icons = [\n    1 => \'<svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.15\" stroke-linejoin=\"round\"><path d=\"M14.5 10h19l7.5 9.5L24 39 7 19.5 14.5 10z\"/><path d=\"M7 19.5h34M14.5 10l5 9.5L24 10l4.5 9.5 5-9.5M19.5 19.5 24 39l4.5-19.5\"/></svg>\',\n    2 => \'<svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.15\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M24 7.5 37.5 12v10.2c0 8.6-5.6 15.3-13.5 18.3-7.9-3-13.5-9.7-13.5-18.3V12L24 7.5z\"/><path d=\"m17.6 24.1 4.6 4.5 8.4-8.8\"/></svg>\',\n    3 => \'<svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\".9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><g transform=\"matrix(1.14 0 0 1.3 -3.4 -8)\"><path d=\"M24 13c4 4 5.5 9 5.5 13 0 4.5-2.2 8-5.5 10.5-3.3-2.5-5.5-6-5.5-10.5 0-4 1.5-9 5.5-13z\"/><path d=\"M24 36.5c-6-1-10-5.5-10.4-17 3.6 1 6 2.5 7.4 4.5M24 36.5c6-1 10-5.5 10.4-17-3.6 1-6 2.5-7.4 4.5\"/><path d=\"M18.7 34.8c-6.7.7-11.2-2.3-13.7-7.3 3-.9 6-.9 9.2.1M29.3 34.8c6.7.7 11.2-2.3 13.7-7.3-3-.9-6-.9-9.2.1\"/></g></svg>\'\n]}\n<section class=\"lb-implica{$svc ? \' lb-implica--svc\' : \'\'}{$photo ? \' lb-implica--photo\' : \'\'}\" id=\"lb-implica\">\n    <div class=\"lb-implica__bg\">\n        {if $photo}\n        <img class=\"lb-implica__photo\" src=\"/{$photo | replace : \' \' : \'%20\'}\" alt=\"{(\'[[*alt-im-1-bl3]]\' | trim) | escape}\" width=\"850\" height=\"850\" loading=\"lazy\" decoding=\"async\">\n        {else}\n        <picture>\n            <source media=\"(max-width: 1024px)\" srcset=\"{$img}implica-mobile-v2.webp\" width=\"840\" height=\"861\">\n            <img src=\"{$img}implica-bg-v2.webp\" srcset=\"{$img}implica-bg-v2-1440.webp 1440w, {$img}implica-bg-v2.webp 2166w\" sizes=\"100vw\" width=\"2166\" height=\"1218\" alt=\"{\'lbar.rd.implica.alt\' | lexicon}\" loading=\"lazy\" decoding=\"async\">\n        </picture>\n        {/if}\n    </div>\n\n    <svg class=\"lb-implica__arc\" viewBox=\"0 0 1920 1080\" aria-hidden=\"true\">\n        <defs>\n            <linearGradient id=\"lb-implica-arc\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                <stop offset=\"0\" stop-color=\"#9f6e50\" stop-opacity=\".08\"/>\n                <stop offset=\".14\" stop-color=\"#9f6e50\" stop-opacity=\".55\"/>\n                <stop offset=\".3\" stop-color=\"#9f6e50\" stop-opacity=\".95\"/>\n                <stop offset=\".8\" stop-color=\"#9f6e50\" stop-opacity=\".9\"/>\n                <stop offset=\"1\" stop-color=\"#9f6e50\" stop-opacity=\"0\"/>\n            </linearGradient>\n        </defs>\n        <path class=\"lb-implica__arcline\" d=\"M903.8 306A435 435 0 0 1 878.5 925\" stroke=\"url(#lb-implica-arc)\"/>\n    </svg>\n\n    <div class=\"lb-implica__col\">\n\n        {if $title}\n        <h2 class=\"lb-implica__title\">\n            {if $plain == $title}\n            {foreach ($fmt | split : \'|\') as $line}\n            <span class=\"lb-implica__line\"><span class=\"lb-implica__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n            {/foreach}\n            {else}\n            <span class=\"lb-implica__line\"><span class=\"lb-implica__lin\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $title])}</span></span>\n            {/if}\n        </h2>\n        {/if}\n\n        <ul class=\"lb-implica__list\">\n            {foreach 1..3 as $i}\n            {set $name = $_modx->resource[\'title-\' ~ $i ~ \'-bl3\']}\n            {if $name}\n            <li class=\"lb-implica__item lb-implica__item--{$i}\">\n                <span class=\"lb-implica__dot\" aria-hidden=\"true\"></span>\n                <span class=\"lb-implica__ic\" aria-hidden=\"true\">{if $svc}<span class=\"lb-implica__num\">0{$i}</span>{else}{$icons[$i]}{/if}</span>\n                <div class=\"lb-implica__body\">\n                    <div class=\"lb-implica__name\">{$name}</div>\n                    <p class=\"lb-implica__text\">{$_modx->resource[\'text-\' ~ $i ~ \'-bl3\']}</p>\n                </div>\n            </li>\n            {/if}\n            {/foreach}\n        </ul>\n\n        <div class=\"lb-implica__btns\">\n            <a class=\"lb-btn lb-btn--solid lb-implica__cta js-lb-book\" href=\"#bl8-form\">{\'lbar.rd.implica.cta\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n            <a class=\"lb-implica__play\" href=\"{$video}\" data-fancybox=\"lb-video\">\n                <span class=\"lb-implica__playic\" aria-hidden=\"true\"><svg viewBox=\"0 0 12 14\"><path fill=\"currentColor\" d=\"M1.5 1.6v10.8c0 .5.5.8.9.5l8.6-5.4c.4-.2.4-.8 0-1L2.4 1.1c-.4-.3-.9 0-.9.5z\"/></svg></span>\n                <span class=\"lb-implica__playtxt\">{\'lbar.rd.implica.video\' | lexicon}</span>\n            </a>\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-implica.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (275,1,0,'lb-consult','Редизайн: блок «Консультация» (форма, главная)',0,128,0,'{* Блок «Консультация» (редизайн, 5-й экран главной) — вместо bl4-form.\n   Заголовок и подзаголовок — прежние TV: main-title-bl4, sub-title-bl4; текст кнопки — TV link-form-bl4.\n   Разбивка заголовка на строки и курсив — лексикон lbar.rd.consult.title («|» — перенос, *слово* — курсив);\n   если TV изменят и он перестанет совпадать с лексиконом — заголовок выводится как есть.\n   Заголовок — не H2 (как и в старом блоке), чтобы не менять структуру заголовков страницы.\n   Форма: AjaxForm + FormIt с прежними параметрами, id формы — form-bl4 (на него завязаны якоря и редирект после отправки). *}\n{* на страницах услуг TV пустые — берутся с главной контекста (как :default в старом bl4-form) *}\n{* удаление тату (шаг 54, &tz=`1`): в старом bl4-form-new заголовок был H2 — остаётся H2; span.gold-word → курсив *}\n{* параметр &tz из вызова чанка в шаблоне: MODX-плейсхолдер подставляется до Fenom (без параметра остаётся «[[+tz]]» → не 1) *}\n{set $tz = (\'[[+tz]]\' == \'1\')}\n{set $start = $_modx->config.site_start}\n{set $title = ($_modx->resource[\'main-title-bl4\'] ?: $_modx->runSnippet(\'pdoField\', [\'id\' => $start, \'field\' => \'main-title-bl4\'])) | trim}\n{set $sub = $_modx->resource[\'sub-title-bl4\'] ?: $_modx->runSnippet(\'pdoField\', [\'id\' => $start, \'field\' => \'sub-title-bl4\'])}\n{if $tz}{set $title = $title | replace : \'<span class=\"gold-word\">\' : \'<em>\' | replace : \'</span>\' : \'</em>\'}{/if}\n{set $fmt = \'lbar.rd.consult.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n<div id=\"conract\"></div>\n<section class=\"lb-consult\" id=\"lb-consult\">\n    <div class=\"lb-consult__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-consult__intro\">\n\n        {if $title}\n        <{$tz ? \'h2\' : \'div\'} class=\"lb-consult__title\">\n            {if $plain == $title}\n            {foreach ($fmt | split : \'|\') as $line}\n            <span class=\"lb-consult__line\"><span class=\"lb-consult__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n            {/foreach}\n            {else}\n            <span class=\"lb-consult__line\"><span class=\"lb-consult__lin\">{$title}</span></span>\n            {/if}\n        </{$tz ? \'h2\' : \'div\'}>\n        <svg class=\"lb-consult__flourish\" viewBox=\"0 0 440 50\" aria-hidden=\"true\">\n            <defs>\n                <linearGradient id=\"lb-consult-fl\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n                    <stop offset=\"0\" stop-color=\"#a87856\" stop-opacity=\".2\"/>\n                    <stop offset=\".25\" stop-color=\"#a87856\" stop-opacity=\".9\"/>\n                    <stop offset=\".6\" stop-color=\"#a87856\" stop-opacity=\".85\"/>\n                    <stop offset=\"1\" stop-color=\"#a87856\" stop-opacity=\"0\"/>\n                </linearGradient>\n            </defs>\n            <path fill=\"url(#lb-consult-fl)\" d=\"M12 45C110 25 240 9 392 13C250 14 120 30 12 45Z\"/>\n            <path fill=\"url(#lb-consult-fl)\" d=\"M100 40C140 26 190 15 250 11C195 18 150 30 106 42C101 44 97 42 100 40Z\"/>\n        </svg>\n        {/if}\n\n        {if $sub}\n        <div class=\"lb-consult__text\">{$sub}</div>\n        {/if}\n    </div>\n\n    <div class=\"lb-consult__card\">\n        [[!AjaxForm?\n            &form=`lb.formConsult`\n            &snippet=`FormIt`\n            &hooks=`spam,email,FormItSaveForm,GoogleSheetsSaveForm`\n            &emailSubject=`Заявка \"[[++tema.form]]\"`\n            &emailTo=`[[++form-mail]]`\n            &emailFrom=`[[++form-mail]]`\n            &emailFromName=`[[++site_name]]`\n            &emailTpl=`tpl.email`\n            &fiarSubject=`Спасибо за Ваше сообщение!`\n            &fiarTpl=`tpl.email.client`\n            &fiarFromName=`[[++site_name]]`\n            &fiarFrom=`[[++form-mail]]`\n            &spamCheckIp=`true`\n            &validate=`name:required,phone:minLength=^8^:required,workemail:blank`\n            &validationErrorMessage=`Пожалуйста, заполните обязательные поля*`\n            &successMessage=`Ваше сообщение было успешно отправлено!`\n            &frontend_css=``\n            &frontend_js=``\n            &formFields=`name,phone,title,link`\n        ]]\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-consult.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (276,1,0,'lb.formConsult','Редизайн: tpl формы блока «Консультация» (AjaxForm)',0,128,0,'{* Форма блока «Консультация» (tpl для AjaxForm). Поля и скрытые поля — как в старом tpl.Form.Bl4.\n   Телефон оформляет intlTelInput (чанк inttelinput): флаг, код страны и разделитель встают слева в поле. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $phName = $_modx->lexicon(\'lbar.form.input.name\')}\n{set $phTel = $_modx->lexicon(\'lbar.form.input.phone\')}\n<form method=\"post\" id=\"form-bl4\" class=\"lb-cform\">\n    <label class=\"lb-cform__field lb-cform__field--name\">\n        <span class=\"lb-cform__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"16\" cy=\"10.5\" r=\"6\"/><path d=\"M4.5 29c.9-6.2 5.6-10 11.5-10s10.6 3.8 11.5 10\"/></svg></span>\n        <input type=\"text\" name=\"name\" value=\"\" placeholder=\"{$phName}\" aria-label=\"{$phName | replace : \'*\' : \'\'}\" autocomplete=\"name\">\n    </label>\n    <div class=\"lb-cform__field lb-cform__field--phone\">\n        <input type=\"tel\" name=\"phone\" value=\"\" placeholder=\"{$phTel}\" aria-label=\"{$phTel | replace : \'*\' : \'\'}\" autocomplete=\"tel\">\n    </div>\n    <input type=\"hidden\" name=\"title\" value=\"\">\n    <input type=\"hidden\" name=\"link\" value=\"[[*uri]]\">\n    <input type=\"hidden\" name=\"workemail\" value=\"\">\n    <button type=\"submit\" class=\"lb-btn lb-btn--solid lb-cform__btn\">[[*link-form-bl4:default=`[[pdoField? &id=`[[++site_start]]` &field=`link-form-bl4`]]`]]<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n    <p class=\"lb-cform__policy\">\n        <svg viewBox=\"0 0 26 30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2\" y=\"12.5\" width=\"22\" height=\"16\" rx=\"3\"/><path d=\"M7 12.5V8.5a6 6 0 0 1 12 0v4\"/><path d=\"M13 19v3.5\"/></svg>\n        <span>{$_modx->lexicon(\'lbar.form.policy\') | replace : \'<br/>\' : \' \' | replace : \'<br>\' : \' \'}</span>\n    </p>\n</form>\n',0,NULL,1,'core/elements/redesign/chunks/lb.formConsult.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (277,1,0,'lb-master','Редизайн: блок «Мастер» (главная)',0,128,0,'{* Блок «Познакомьтесь с мастером» (редизайн, 6-й экран главной) — вместо bl2-study-trener.\n   Заголовок (H2) — TV title-bl2-study (выделенная часть — <span class=\"gold-word\">), пункты — TV text-1..6-bl2-study (6-й добавлен в шаге 43).\n   Если TV у ресурса пустые — берутся с главной своего контекста (как в старом блоке); у страниц со своими пунктами (ресницы, лазер —\n   5 пунктов о другом мастерстве) с главной ничего не подставляется и иконки — прежние. Жирное — <b> в тексте TV (если его нет — числа от 3 цифр).\n   Фото — img/master-v2.webp (вырезка с кубком и дипломом WULOP).\n   Кнопка открывает прежний попап .overlay-trainer (обработчик по классу trainer-btn в main.js / script.js). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $start = $_modx->config.site_start}\n{set $title = $_modx->resource[\'title-bl2-study\'] ?: $_modx->runSnippet(\'pdoField\', [\'id\' => $start, \'field\' => \'title-bl2-study\'])}\n{set $isRu = $_modx->config.cultureKey == \'ru\'}\n{set $own = ($_modx->resource.id != $start) && ($_modx->resource[\'text-1-bl2-study\'] | trim)}\n{set $ic = [\n    \'diamond\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linejoin=\"round\"><path d=\"M12 9h16l6 7.5L20 33 6 16.5 12 9z\"/><path d=\"M6 16.5h28M12 9l4 7.5L20 9l4 7.5L28 9M16 16.5 20 33l4-16.5\"/></svg>\',\n    \'people\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"15\" cy=\"14\" r=\"5\"/><circle cx=\"26.5\" cy=\"14.5\" r=\"4.3\"/><path d=\"M5.5 31c.6-5.6 4.4-9 9.5-9s8.9 3.4 9.5 9H5.5zM22.5 22.6c1.2-.5 2.5-.8 4-.8 4.4 0 7.7 3 8.2 8.2H26\"/></svg>\',\n    \'building\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 33V12l11-5 11 5v21M5.5 33h29\"/><path d=\"M13.5 15.5h3M23.5 15.5h3M13.5 20.5h3M23.5 20.5h3M13.5 25.5h3M23.5 25.5h3M17.5 33v-5.5h5V33\"/></svg>\',\n    \'cap\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 10 4.5 17 20 24l15.5-7L20 10z\"/><path d=\"M11 20v6.5c2.4 2.3 5.4 3.5 9 3.5s6.6-1.2 9-3.5V20M35.5 17v8\"/></svg>\',\n    \'star\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linejoin=\"round\"><path d=\"m20 6.5 4.2 8.7 9.5 1.3-6.9 6.6 1.7 9.4L20 28l-8.5 4.5 1.7-9.4-6.9-6.6 9.5-1.3L20 6.5z\"/></svg>\',\n    \'crown\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8.5 28.5 6 13.5l8 6.5 6-10.5 6 10.5 8-6.5-2.5 15h-23z\"/><path d=\"M9 33h22\"/><circle cx=\"20\" cy=\"7.2\" r=\"1.6\"/><circle cx=\"5.6\" cy=\"11.2\" r=\"1.4\"/><circle cx=\"34.4\" cy=\"11.2\" r=\"1.4\"/></svg>\',\n    \'globe\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"20\" cy=\"20\" r=\"13\"/><path d=\"M7 20h26M9 13.5h22M9 26.5h22\"/><path d=\"M20 7c3.6 3.6 5.4 8 5.4 13s-1.8 9.4-5.4 13c-3.6-3.6-5.4-8-5.4-13S16.4 10.6 20 7z\"/></svg>\',\n    \'feather\' => \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 32 30 11\"/><path d=\"M31 9.5c-6-2-14.6.8-18.1 8.5-1.8 3.7-1.9 7.6-1.4 10.8 3.3.5 7.2.2 10.9-1.5 7.6-3.6 10.4-12 8.6-17.8z\"/><path d=\"M14.7 24h7M18 20.2h6.5M21.8 16.4h4.9\"/></svg>\'\n]}\n{* иконки по смыслу пунктов: главная (6 пунктов, порядок во всех языках один) — опыт, чемпионат, ученики, методика, тренер, студия;\n   страницы со своими пунктами — прежние наборы (в RO / EN и RU порядок пунктов разный) *}\n{set $icons = $own ? ($isRu ? [\'diamond\', \'star\', \'cap\', \'feather\', \'building\'] : [\'diamond\', \'people\', \'building\', \'cap\', \'star\']) : [\'star\', \'crown\', \'cap\', \'feather\', \'globe\', \'building\']}\n<section class=\"lb-master\" id=\"lb-master\">\n    <div class=\"lb-master__bg\" aria-hidden=\"true\">\n        <svg class=\"lb-master__lines\" viewBox=\"0 0 1920 890\" preserveAspectRatio=\"none\">\n            <defs>\n                <linearGradient id=\"lb-master-arc\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                    <stop offset=\"0\" stop-color=\"#d8b39a\" stop-opacity=\".75\"/>\n                    <stop offset=\".45\" stop-color=\"#cfa48a\" stop-opacity=\".85\"/>\n                    <stop offset=\"1\" stop-color=\"#b98a70\" stop-opacity=\".15\"/>\n                </linearGradient>\n                <linearGradient id=\"lb-master-sheen\" x1=\"0\" y1=\"1\" x2=\"1\" y2=\"0\">\n                    <stop offset=\"0\" stop-color=\"#f3d2bd\" stop-opacity=\"0\"/>\n                    <stop offset=\".55\" stop-color=\"#f6dccb\" stop-opacity=\".9\"/>\n                    <stop offset=\"1\" stop-color=\"#f3d2bd\" stop-opacity=\"0\"/>\n                </linearGradient>\n            </defs>\n            <path class=\"lb-master__arc\" d=\"M247 0A803 803 0 0 1 693 890\" stroke=\"url(#lb-master-arc)\"/>\n            <path class=\"lb-master__sheen\" d=\"M1560 890C1680 835 1790 772 1920 700\" stroke=\"url(#lb-master-sheen)\"/>\n        </svg>\n    </div>\n\n    <div class=\"lb-master__photo\">\n        <img src=\"/assets/templates/redesign/img/master-v2.webp\" alt=\"{\'lbar.rd.master.alt\' | lexicon}\" width=\"860\" height=\"1106\" loading=\"lazy\" decoding=\"async\">\n    </div>\n\n    <div class=\"lb-master__col\">\n        {if $title}\n        <h2 class=\"lb-master__title\">{$title}</h2>\n        {/if}\n\n        <div class=\"lb-master__lists\">\n            {* пункты 1–3 — в первой колонке, 4–6 — во второй *}\n            {foreach [ [1, 2, 3], [4, 5, 6] ] as $col}\n            <ul class=\"lb-master__list\">\n                {foreach $col as $i}\n                {set $t = $_modx->resource[\'text-\' ~ $i ~ \'-bl2-study\'] ?: ($own ? \'\' : $_modx->runSnippet(\'pdoField\', [\'id\' => $start, \'field\' => \'text-\' ~ $i ~ \'-bl2-study\']))}\n                {if $t}\n                <li class=\"lb-master__item\">\n                    {set $key = $icons[$i - 1]}\n                    <span class=\"lb-master__ic\" aria-hidden=\"true\">{$ic[$key]}</span>\n                    <span class=\"lb-master__text\">{if \'<b>\' in $t}{$t}{else}{$t | ereplace : \'/(\\d{3,}\\s?\\+?)/u\' : \'<b>$1</b>\'}{/if}</span>\n                </li>\n                {/if}\n                {/foreach}\n            </ul>\n            {/foreach}\n        </div>\n\n        <button class=\"lb-btn lb-btn--light lb-master__btn trainer-btn\" type=\"button\">{\'lbar.trainer.button.consultation\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n    </div>\n</section>\n<div class=\"overlay-trainer\">\n  <div class=\"popup\">\n    <h2 class=\"popup-title\">{$_modx->lexicon(\"lbar.popup.trainer.title\")}</h2>\n        <p class=\"popup-subtitle\">{$_modx->lexicon(\"lbar.popup.trainer.subtitle\")}</p>\n      [[!AjaxForm?\n              &form=`tpl.Form.Study.Modal.BL2`\n              &snippet=`FormIt`\n              &formFields=`name,phone,title,link`\n              &hooks=`spam,email,FormItSaveForm,GoogleSheetsSaveForm`\n              &emailSubject=`Заявка \"Получить личную консультацию\"`\n              &emailTo=`[[++form-mail]]`\n              &emailFrom=`[[++form-mail]]`\n              &emailFromName=`[[++site_name]]`\n              &emailTpl=`tpl.email.study`\n              &spamCheckIp=`true`\n              &validate=`name:required,phone:minLength=^10^:required,workemail:blank`\n              &validationErrorMessage=`Пожалуйста, заполните обязательные поля*`\n              &successMessage=`Ваше сообщение было успешно отправлено!`\n              &frontend_css=``\n              &frontend_js=``\n        ]]\n        <div class=\"close-popup\"></div>\n  </div>\n</div>\n',0,NULL,1,'core/elements/redesign/chunks/lb-master.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (278,1,0,'lb.galleryItem','Редизайн: tpl галереи главной (ms2Gallery)',0,128,0,'{* Галерея главной (tpl для ms2Gallery): сетка 4 / 3 / 2 в ряд, первые 8 фото видны, остальные — по кнопке.\n   Ссылки на полноразмерные фото с data-fancybox — как в старом tpl.ms2GalleryPortfolioFrontPage. *}\n{if $files?}\n<div class=\"lb-gallery\" id=\"lb-gallery\">\n    {foreach $files as $key => $file}\n    <a class=\"lb-gallery__item{$key > 7 ? \' lb-gallery__item--more\' : \'\'}\" href=\"{$file[\'url\']}\" data-fancybox=\"gallery-{$file[\'resource_id\']}\" aria-label=\"{$file[\'description\'] ?: $file[\'name\']}\">\n        <img src=\"{$file[\'medium\']}\" srcset=\"{$file[\'medium\']} 400w, {$file[\'url\']} 1200w\" sizes=\"(max-width: 600px) 50vw, (max-width: 1024px) 33vw, 22vw\" alt=\"{$file[\'description\']}\" width=\"400\" height=\"400\" loading=\"lazy\" decoding=\"async\">\n        <span class=\"lb-gallery__zoom\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m15.5 15.5 5 5M10.5 7.5v6M7.5 10.5h6\"/></svg></span>\n    </a>\n    {/foreach}\n</div>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.galleryItem.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (279,1,0,'lb-portfolio','Редизайн: блок «Галерея фото» (главная)',0,128,0,'{* Блок «Галерея фото» (редизайн, 7-й экран главной) — вместо bl6-portfolio-front-page.\n   H2 — TV title-bl6 (текст не менялся); разбивка на строки и курсив — лексикон lbar.rd.portfolio.title\n   («|» — перенос, *…* — курсив); если TV изменят и он перестанет совпадать — H2 выводится как есть.\n   Подзаголовок — TV sub-title-bl6 (с главной контекста, как было). Фото — ms2Gallery ресурса (у EN — RO-двойника, lb.roId; tpl lb.galleryItem):\n   первые 8 видны, остальные раскрываются кнопкой; увеличение — fancybox (data-fancybox, как было). *}\n{set $title = $_modx->resource[\'title-bl6\'] | trim}\n{set $fmt = \'lbar.rd.portfolio.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n<section class=\"lb-portfolio\" id=\"lb-portfolio\">\n    <div class=\"lb-portfolio__bg\" aria-hidden=\"true\">\n        <svg class=\"lb-portfolio__lines\" viewBox=\"0 0 1920 1160\" preserveAspectRatio=\"none\">\n            <defs>\n                <linearGradient id=\"lb-portfolio-arc\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n                    <stop offset=\"0\" stop-color=\"#c49a80\" stop-opacity=\".05\"/>\n                    <stop offset=\".35\" stop-color=\"#c49a80\" stop-opacity=\".75\"/>\n                    <stop offset=\"1\" stop-color=\"#c49a80\" stop-opacity=\".1\"/>\n                </linearGradient>\n            </defs>\n            <path class=\"lb-portfolio__arc\" d=\"M1560 40C1440 150 1370 260 1340 360\" stroke=\"url(#lb-portfolio-arc)\"/>\n            <path class=\"lb-portfolio__arc\" d=\"M0 600C190 640 300 760 320 1160\" stroke=\"url(#lb-portfolio-arc)\"/>\n        </svg>\n    </div>\n\n    <div class=\"lb-portfolio__head\">\n        {if $title}\n        <h2 class=\"lb-portfolio__title\">\n            {if $plain == $title}\n            {foreach ($fmt | split : \'|\') as $line}\n            <span class=\"lb-portfolio__line\"><span class=\"lb-portfolio__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n            {/foreach}\n            {else}\n            <span class=\"lb-portfolio__line\"><span class=\"lb-portfolio__lin\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $title])}</span></span>\n            {/if}\n        </h2>\n        {/if}\n        {set $sub = $_modx->runSnippet(\'pdoField\', [\'id\' => $_modx->config.site_start, \'field\' => \'sub-title-bl6\'])}\n        {if $sub}\n        <p class=\"lb-portfolio__sub\">{$sub}</p>\n        {/if}\n    </div>\n\n    {if !$gallery = $_modx->cacheManager->get(\'lb-portfolio\' ~ $_modx->config.cultureKey ~ $_modx->resource.id)}\n        {set $gallery = $_modx->runSnippet(\'!ms2Gallery\', [\n            \'resources\' => ($_modx->getChunk(\'lb.roId\') | trim),\n            \'tpl\' => \'lb.galleryItem\',\n            \'frontend_css\' => \'\',\n            \'frontend_js\' => \'\',\n        ])}\n        {set $null = $_modx->cacheManager->set(\'lb-portfolio\' ~ $_modx->config.cultureKey ~ $_modx->resource.id, $gallery, 3600 * 24)}\n    {/if}\n    {$gallery}\n\n    {* «Vezi toate lucrările» — ссылка на портфолио: на страницах услуг — из TV link-bl6 (как кнопка старого bl6-portfolio),\n       иначе — общая страница портфолио контекста (RO 100 / RU 198 / EN 1100). В блоке — первые 8 фото, остальные — в окне просмотра. *}\n    {set $pfIds = [\'ro\' => 100, \'ru\' => 198, \'en\' => 1100]}\n    {set $link = ($_modx->resource.id != $_modx->config.site_start) ? ($_modx->resource[\'link-bl6\'] | trim) : \'\'}\n    {set $link = $link ?: $_modx->makeUrl($pfIds[$_modx->config.cultureKey] ?: 100)}\n    <div class=\"lb-portfolio__foot\">\n        <a class=\"lb-btn lb-btn--solid lb-portfolio__more\" href=\"{$link}\">{\'lbar.portfolio.button.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-portfolio.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (280,1,0,'lb-price','Редизайн: блок «Цены» (главная)',0,128,0,'{* Блок «Цены» (редизайн, 8-й экран главной) — вместо bl7-price (условие [[*title-bl7:notempty=…]] в шаблоне сохранено).\n   H2 — TV title-bl7 (текст не менялся); разбивка на строки и курсив — лексикон lbar.rd.price.title\n   («|» — перенос, *…* — курсив); если TV изменят и он перестанет совпадать — H2 выводится как есть.\n   Текст над таблицей — TV table-bl7 (свёрнут до 3 строк + «Citește mai mult»). Таблица — MIGX TV table-res-bl7:\n   col-1 — процедура (часть в скобках выводится второй строкой), col-2 — длительность, цена — col-4 (TOP Trainer, как в\n   выбранной на главной таблице «3 колонки, без топ-мастера»), если пусто — col-3. Иконки — по ключевым словам названия.\n   Кнопка — прежний текст lbar.prices.button.book, якорь #bl8-form (на других страницах — попап, js-lb-book).\n   Страницы услуг: вид таблицы — по TV table_select, как в старом bl7-price: «3 колонки без топ-мастера» — как на главной;\n   table-defult-bl7 (по умолчанию) — длительность + две цены (TOP Master col-3 / TOP Trainer col-4); table-three-col-bl7 —\n   две цены (col-2 / col-3, «за сеанс» / «8 сеансов»), без длительности; table-two-col-bl7 — одна цена (col-3).\n   Подписи колонок — прежние ключи lbar.price.table.title*. Длинная цена («100% din prețul…») переносится.\n   Таблица — общий чанк lb.ptable (он же на странице «Цены»). *}\n{set $title = $_modx->resource[\'title-bl7\'] | trim}\n{set $fmt = \'lbar.rd.price.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n{set $rows = $_modx->resource[\'table-res-bl7\'] | trim}\n{set $intro = $_modx->resource[\'table-bl7\'] | trim}\n{set $sel = $_modx->resource[\'table_select\'] | trim}\n{set $mode = ($sel | ematch : \'/two-col/\') ? \'two\' : (($sel | ematch : \'/three-col-bl7/\') ? \'three\' : (($sel | ematch : \'/without-top/\') ? \'notop\' : \'full\'))}\n<section class=\"lb-price{($_modx->resource.id != $_modx->config.site_start) ? \' lb-price--svc\' : \'\'}\" id=\"lb-price\">\n    <div class=\"lb-price__bg\" aria-hidden=\"true\">\n        <svg class=\"lb-price__lines\" viewBox=\"0 0 1920 1080\" preserveAspectRatio=\"none\">\n            <defs>\n                <linearGradient id=\"lb-price-line\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n                    <stop offset=\"0\" stop-color=\"#c9a38a\" stop-opacity=\".1\"/>\n                    <stop offset=\".4\" stop-color=\"#c9a38a\" stop-opacity=\".8\"/>\n                    <stop offset=\"1\" stop-color=\"#c9a38a\" stop-opacity=\".05\"/>\n                </linearGradient>\n                <linearGradient id=\"lb-price-silk\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n                    <stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\"0\"/>\n                    <stop offset=\".35\" stop-color=\"#fff\" stop-opacity=\".7\"/>\n                    <stop offset=\"1\" stop-color=\"#fff\" stop-opacity=\"0\"/>\n                </linearGradient>\n            </defs>\n            <path class=\"lb-price__silk\" d=\"M-20 742C120 760 230 818 330 900S540 1040 720 1088L520 1088C390 1060 300 990 220 925S80 812-20 800Z\" fill=\"url(#lb-price-silk)\"/>\n            <path class=\"lb-price__line\" d=\"M-20 742C120 760 230 818 330 900S540 1040 720 1088\" stroke=\"url(#lb-price-line)\"/>\n            <path class=\"lb-price__line lb-price__line--thin\" d=\"M-20 800C80 812 160 852 220 925S390 1060 520 1088\" stroke=\"url(#lb-price-line)\"/>\n        </svg>\n    </div>\n\n    <div class=\"lb-price__intro\">\n        {if $title}\n        <h2 class=\"lb-price__title\">\n            {if $plain == $title}\n            {foreach ($fmt | split : \'|\') as $line}\n            <span class=\"lb-price__line-t\"><span class=\"lb-price__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n            {/foreach}\n            {else}\n            <span class=\"lb-price__line-t\"><span class=\"lb-price__lin\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $title])}</span></span>\n            {/if}\n        </h2>\n        {/if}\n        <a class=\"lb-btn lb-btn--solid lb-price__cta js-lb-book\" href=\"#bl8-form\">{\'lbar.prices.button.book\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n\n    <div class=\"lb-price__main{$intro ? \'\' : \' lb-price__main--notext\'}\">\n        {if $intro}\n        <div class=\"lb-price__textwrap\">\n            <div class=\"lb-price__text\" id=\"lb-price-text\">{$intro}</div>\n            <button class=\"lb-price__more\" type=\"button\" aria-controls=\"lb-price-text\" aria-expanded=\"false\">\n                <span class=\"lb-price__moretxt\">{\'lbar.rd.about.more\' | lexicon}</span><span class=\"lb-price__less\">{\'lbar.rd.about.less\' | lexicon}</span>\n                <svg viewBox=\"0 0 12 12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M2.5 4.5 6 8l3.5-3.5\"/></svg>\n            </button>\n        </div>\n        {/if}\n\n        {if $rows}\n        <div class=\"lb-price__card\">\n            {* таблица — div с ARIA-ролями: старый custom.js клонирует все <table> (resTables) и прячет их на мобильном *}\n            {$_modx->getChunk(\'lb.ptable\', [\'rows\' => $_modx->resource[\'table-res-bl7\'], \'mode\' => $mode, \'label\' => $title, \'uid\' => \'p\'])}\n        </div>\n        {/if}\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-price.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (281,1,0,'lb-book','Редизайн: блок «Запись на процедуру» (главная)',0,128,0,'{* Блок «Запись на процедуру» (редизайн, форма перед отзывами на главной) — вместо bl8-form. Сделан по образцу lb-consult.\n   Заголовок и подзаголовок — прежние TV: main-title-bl8, sub-title-bl8 (сначала -interial, как в старом чанке); текст кнопки — TV link-form-bl8.\n   Разбивка заголовка на строки и курсив — лексикон lbar.rd.book.title («|» — перенос, *слово* — курсив);\n   если TV изменят и он перестанет совпадать с лексиконом — заголовок выводится как есть.\n   Заголовок — не H2 (как и в старом блоке), чтобы не менять структуру заголовков страницы.\n   Форма: AjaxForm + FormIt с прежними параметрами bl8-form, id формы — form-bl8 (на него завязан редирект после отправки).\n   Якорь #bl8-form (кнопки «Записаться» в шапке, баннере, «Ценах») — прежний пустой div перед блоком. *}\n{* на страницах услуг TV пустые — берутся main-title-bl8 / sub-title-bl8 с главной контекста (как :default в старом bl8-form) *}\n{set $start = $_modx->config.site_start}\n{set $title = ($_modx->resource[\'main-title-bl8-interial\'] ?: $_modx->resource[\'main-title-bl8\'] ?: $_modx->runSnippet(\'pdoField\', [\'id\' => $start, \'field\' => \'main-title-bl8\'])) | trim}\n{set $sub = $_modx->resource[\'sub-title-bl8-interial\'] ?: $_modx->resource[\'sub-title-bl8\'] ?: $_modx->runSnippet(\'pdoField\', [\'id\' => $start, \'field\' => \'sub-title-bl8\'])}\n{set $fmt = \'lbar.rd.book.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n<div id=\"bl8-form\"></div>\n<section class=\"lb-book\" id=\"lb-book\">\n    <div class=\"lb-book__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-book__intro\">\n        {if $title}\n        <div class=\"lb-book__title\">\n            {if $plain == $title}\n            {foreach ($fmt | split : \'|\') as $line}\n            <span class=\"lb-book__line\"><span class=\"lb-book__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n            {/foreach}\n            {else}\n            <span class=\"lb-book__line\"><span class=\"lb-book__lin\">{$title}</span></span>\n            {/if}\n        </div>\n        <svg class=\"lb-book__flourish\" viewBox=\"0 0 440 50\" aria-hidden=\"true\">\n            <defs>\n                <linearGradient id=\"lb-book-fl\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n                    <stop offset=\"0\" stop-color=\"#a87856\" stop-opacity=\".2\"/>\n                    <stop offset=\".25\" stop-color=\"#a87856\" stop-opacity=\".9\"/>\n                    <stop offset=\".6\" stop-color=\"#a87856\" stop-opacity=\".85\"/>\n                    <stop offset=\"1\" stop-color=\"#a87856\" stop-opacity=\"0\"/>\n                </linearGradient>\n            </defs>\n            <path fill=\"url(#lb-book-fl)\" d=\"M12 45C110 25 240 9 392 13C250 14 120 30 12 45Z\"/>\n            <path fill=\"url(#lb-book-fl)\" d=\"M100 40C140 26 190 15 250 11C195 18 150 30 106 42C101 44 97 42 100 40Z\"/>\n        </svg>\n        {/if}\n\n        {if $sub}\n        <div class=\"lb-book__text\">{$sub}</div>\n        {/if}\n    </div>\n\n    <div class=\"lb-book__card\">\n        [[!AjaxForm?\n            &form=`lb.formBook`\n            &snippet=`FormIt`\n            &hooks=`spam,email,FormItSaveForm,GoogleSheetsSaveForm`\n            &emailSubject=`Заявка \"[[++tema.form]]\"`\n            &emailTo=`[[++form-mail]]`\n            &emailFrom=`[[++form-mail]]`\n            &emailFromName=`[[++site_name]]`\n            &emailTpl=`tpl.email`\n            &fiarSubject=`Спасибо за Ваше сообщение!`\n            &fiarTpl=`tpl.email.client`\n            &fiarFromName=`[[++site_name]]`\n            &fiarFrom=`[[++form-mail]]`\n            &spamCheckIp=`true`\n            &validate=`name:required,phone:minLength=^10^:required,workemail:blank`\n            &validationErrorMessage=`Пожалуйста, заполните обязательные поля*`\n            &successMessage=`Ваше сообщение было успешно отправлено!`\n            &frontend_css=``\n            &frontend_js=``\n            &formFields=`name,phone,title,link`\n        ]]\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-book.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (282,1,0,'lb.formBook','Редизайн: форма блока «Запись на процедуру» (tpl для AjaxForm)',0,128,0,'{* Форма блока «Запись на процедуру» (tpl для AjaxForm). Поля и скрытые поля — как в старом tpl.Form.Bl8, вёрстка — как lb.formConsult.\n   Телефон оформляет intlTelInput (чанк inttelinput): флаг, код страны и разделитель встают слева в поле. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $phName = $_modx->lexicon(\'lbar.form.input.name\')}\n{set $phTel = $_modx->lexicon(\'lbar.form.input.phone\')}\n<form method=\"post\" id=\"form-bl8\" class=\"lb-cform\">\n    <label class=\"lb-cform__field lb-cform__field--name\">\n        <span class=\"lb-cform__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"16\" cy=\"10.5\" r=\"6\"/><path d=\"M4.5 29c.9-6.2 5.6-10 11.5-10s10.6 3.8 11.5 10\"/></svg></span>\n        <input type=\"text\" name=\"name\" value=\"\" placeholder=\"{$phName}\" aria-label=\"{$phName | replace : \'*\' : \'\'}\" autocomplete=\"name\">\n    </label>\n    <div class=\"lb-cform__field lb-cform__field--phone\">\n        <input type=\"tel\" name=\"phone\" value=\"\" placeholder=\"{$phTel}\" aria-label=\"{$phTel | replace : \'*\' : \'\'}\" autocomplete=\"tel\">\n    </div>\n    <input type=\"hidden\" name=\"title\" value=\"\">\n    <input type=\"hidden\" name=\"link\" value=\"[[*uri]]\">\n    <input type=\"hidden\" name=\"workemail\" value=\"\">\n    <button type=\"submit\" class=\"lb-btn lb-btn--solid lb-cform__btn\">[[*link-form-bl8:default=`[[pdoField? &id=`[[++site_start]]` &field=`link-form-bl8`]]`]]<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n    <p class=\"lb-cform__policy\">\n        <svg viewBox=\"0 0 26 30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2\" y=\"12.5\" width=\"22\" height=\"16\" rx=\"3\"/><path d=\"M7 12.5V8.5a6 6 0 0 1 12 0v4\"/><path d=\"M13 19v3.5\"/></svg>\n        <span>{$_modx->lexicon(\'lbar.form.policy\') | replace : \'<br/>\' : \' \' | replace : \'<br>\' : \' \'}</span>\n    </p>\n</form>\n',0,NULL,1,'core/elements/redesign/chunks/lb.formBook.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (283,1,0,'lb.ecForm','Редизайн: форма отзыва (tplForm для ecForm)',0,128,0,'{* Форма отзыва EasyComm (tplForm для ecForm) в окне блока «Отзывы». Поля, имена и id — как в старом tpl.ecForm.Blog.2:\n   на них завязан JS easyComm из custom.js (ajax-отправка, ошибки #ec-<поле>-error-<fid>, звёзды .ec-rating, успех #ec-form-success-<fid>).\n   Антиспам-поле скрыто CSS. Отзыв публикуется после модерации (как раньше). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n<form class=\"ec-form lb-rform\" method=\"post\" id=\"ec-form-[[+fid]]\" data-fid=\"[[+fid]]\" action=\"\">\n    <input type=\"hidden\" name=\"thread\" value=\"[[+thread]]\">\n    <div class=\"form-group ec-antispam\">\n        <label for=\"ec-[[+antispam_field]]-[[+fid]]\" class=\"control-label\">[[%ec_fe_message_antismap]]</label>\n        <input type=\"text\" name=\"[[+antispam_field]]\" class=\"form-control\" id=\"ec-[[+antispam_field]]-[[+fid]]\" value=\"\" tabindex=\"-1\" autocomplete=\"off\">\n    </div>\n\n    <div class=\"lb-rform__row\">\n        <div class=\"form-group lb-rform__field\">\n            <input type=\"text\" name=\"user_name\" class=\"form-control\" placeholder=\"[[%ec_fe_message_user_name]]*\" aria-label=\"[[%ec_fe_message_user_name]]\" id=\"ec-user_name-[[+fid]]\" value=\"[[+user_name]]\" autocomplete=\"name\">\n            <span class=\"ec-error help-block\" id=\"ec-user_name-error-[[+fid]]\"></span>\n        </div>\n        <div class=\"form-group lb-rform__field\">\n            <input type=\"text\" name=\"user_email\" class=\"form-control\" placeholder=\"[[%ec_fe_message_user_email]]\" aria-label=\"[[%ec_fe_message_user_email]]\" id=\"ec-user_email-[[+fid]]\" value=\"[[+user_email]]\" autocomplete=\"email\" inputmode=\"email\">\n            <span class=\"ec-error help-block\" id=\"ec-user_email-error-[[+fid]]\"></span>\n        </div>\n    </div>\n    <div class=\"form-group lb-rform__field lb-rform__field--text\">\n        <textarea name=\"text\" class=\"form-control\" rows=\"5\" placeholder=\"[[%ec_fe_message_text]]*\" aria-label=\"[[%ec_fe_message_text]]\" id=\"ec-text-[[+fid]]\">[[+text]]</textarea>\n        <span class=\"ec-error help-block\" id=\"ec-text-error-[[+fid]]\"></span>\n    </div>\n\n    [[+recaptcha]]\n\n    <div class=\"lb-rform__foot\">\n        <div class=\"form-group lb-rform__rating\">\n            <label for=\"ec-rating-[[+fid]]\" class=\"control-label\">{$_modx->lexicon(\"lbar.reviews.rating.label\")}:</label>\n            <input type=\"hidden\" name=\"rating\" id=\"ec-rating-[[+fid]]\" value=\"[[+rating]]\">\n            <div class=\"ec-rating\" data-storage-id=\"ec-rating-[[+fid]]\">\n                <div class=\"ec-rating-stars\">\n                    <span data-rating=\"1\" data-description=\"[[%ec_fe_message_rating_1]]\"></span>\n                    <span data-rating=\"2\" data-description=\"[[%ec_fe_message_rating_2]]\"></span>\n                    <span data-rating=\"3\" data-description=\"[[%ec_fe_message_rating_3]]\"></span>\n                    <span data-rating=\"4\" data-description=\"[[%ec_fe_message_rating_4]]\"></span>\n                    <span data-rating=\"5\" data-description=\"[[%ec_fe_message_rating_5]]\"></span>\n                </div>\n            </div>\n            <span class=\"ec-error help-block\" id=\"ec-rating-error-[[+fid]]\"></span>\n        </div>\n        <button type=\"submit\" class=\"lb-btn lb-btn--solid lb-btn--sm lb-rform__btn\" name=\"send\" value=\"1\">[[%ec_fe_send]]<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n    </div>\n</form>\n<div class=\"lb-rform__success\" id=\"ec-form-success-[[+fid]]\"></div>\n',0,NULL,1,'core/elements/redesign/chunks/lb.ecForm.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (284,1,0,'lb.reviewCard','Редизайн: карточка отзыва (tpl для ecMessages)',0,128,0,'{* Карточка отзыва (tpl для ecMessages) в блоке «Отзывы». Поля EasyComm: user_name, text (с <br>), rating, reply_author, reply_text.\n   Аватар — инициалы (фото клиенток нет); цвет — от имени. Текст в карточке обрезается CSS (8 строк), полный — в окне по кнопке ⋮\n   (берётся из этой же разметки). Ответ студии виден только в окне. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $name = $user_name | trim}\n{set $parts = $name | replace : \',\' : \' \' | split : \' \'}\n{set $ini = $parts[0] | truncate : 1 : \'\'}\n{if $parts[1]?}{set $ini = $ini ~ ($parts[1] | truncate : 1 : \'\')}{/if}\n{set $star = \'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2.4l2.95 6.02 6.63.95-4.8 4.67 1.13 6.6L12 17.52l-5.91 3.12 1.13-6.6-4.8-4.67 6.63-.95z\"/></svg>\'}\n<article class=\"lb-rcard\" id=\"lb-rcard-{$id}\">\n    <div class=\"lb-rcard__head\">\n        <span class=\"lb-rcard__ava lb-rcard__ava--{($name | crc32) % 4}\" aria-hidden=\"true\">{$ini | upper}</span>\n        <div class=\"lb-rcard__who\">\n            <div class=\"lb-rcard__name\">{$name}</div>\n            {if $rating > 0}\n            <div class=\"lb-rcard__stars\" role=\"img\" aria-label=\"{$rating} / 5\">{foreach 1..5 as $i}<span class=\"lb-rcard__star{if $i > $rating} is-off{/if}\">{$star}</span>{/foreach}</div>\n            {/if}\n        </div>\n        <button class=\"lb-rcard__more\" type=\"button\" aria-haspopup=\"dialog\" aria-controls=\"lb-rmodal\" aria-label=\"{$_modx->lexicon(\'lbar.rd.reviews.read\')}: {$name | escape}\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"5.5\" r=\"1.7\"/><circle cx=\"12\" cy=\"12\" r=\"1.7\"/><circle cx=\"12\" cy=\"18.5\" r=\"1.7\"/></svg></button>\n    </div>\n    <div class=\"lb-rcard__text\">{$text}</div>\n    {if $reply_text}\n    <div class=\"lb-rcard__reply\" hidden>{if $reply_author}<b>{$reply_author}</b>{/if}<div>{$reply_text}</div></div>\n    {/if}\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.reviewCard.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (285,1,0,'lb-reviews','Редизайн: блок «Отзывы» (главная)',0,128,0,'{* Блок «Отзывы» (редизайн, главная, после «Записи на процедуру») — вместо bl9-reviews.\n   H2 — TV title-bl9 (текст не менялся); разбивка на строки и курсив — лексикон lbar.rd.reviews.title\n   («|» — перенос, *…* — курсив; сравнение — без тегов: в RU-TV есть <br>). Если TV изменят — H2 выводится как есть.\n   Отзывы — EasyComm, как раньше: [[!ecMessages]] (некэшируемо, ветка resource-<id>, только опубликованные, новые сверху),\n   карточка — lb.reviewCard, обёртка с рейтингом ветки и каруселью — lb.reviewsWrap. Рейтинг и число — данные ветки EasyComm.\n   «Vezi toate recenziile» — страница отзывов (RO 171 / RU 300 / EN 1171). На EN-страницах — ветка (отзывы и форма) RO-двойника\n   (lb.roId: общие с RO отзывы и рейтинг; у RO и RU — своя ветка resource-<id>, как было). «Lăsați o recenzie» — окно с формой EasyComm [[!ecForm]]\n   (прежние письма и модерация; шаблон формы — lb.ecForm, JS отправки — easyComm из старого custom.js).\n   Полный текст отзыва (и ответ студии) — окно по кнопке ⋮ в карточке.\n   Страница «Отзывы» (шаблон 16, модификатор --page): все отзывы сеткой (без карусели), первые 12, дальше — кнопкой по 12;\n   кнопки «Все отзывы» нет (это она и есть). *}\n{set $raw = $_modx->resource[\'title-bl9\'] | trim}\n{set $title = $raw | striptags | replace : \'  \' : \' \' | trim}\n{set $fmt = \'lbar.rd.reviews.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n{set $allIds = [\'ro\' => 171, \'ru\' => 300, \'en\' => 1171]}\n{set $allId = $allIds[$_modx->config.cultureKey] ?: 171}\n{set $tid = $_modx->getChunk(\'lb.roId\') | trim}\n{set $page = $_modx->resource.template == 16}\n<section class=\"lb-reviews{$page ? \' lb-reviews--page\' : \'\'}\" id=\"lb-reviews\">\n    <div class=\"lb-reviews__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-reviews__head\">\n        {if $raw}\n        <h2 class=\"lb-reviews__title\">\n            {if $plain == $title}\n            {foreach ($fmt | split : \'|\') as $line}\n            <span class=\"lb-reviews__line\"><span class=\"lb-reviews__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n            {/foreach}\n            {else}\n            <span class=\"lb-reviews__line\"><span class=\"lb-reviews__lin\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $raw])}</span></span>\n            {/if}\n        </h2>\n        {/if}\n        <p class=\"lb-reviews__sub\">{\'lbar.rd.reviews.sub\' | lexicon}</p>\n    </div>\n\n    <div id=\"review\"></div>\n    [[!ecMessages?\n        &thread=`resource-{$tid}`\n        &tpl=`lb.reviewCard`\n        &tplWrapper=`lb.reviewsWrap`\n        &limit=`80`\n    ]]\n\n    <div class=\"lb-reviews__btns\">\n        {if $page}\n        <button class=\"lb-btn lb-btn--solid lb-btn--sm lb-reviews__btn lb-reviews__morebtn\" type=\"button\">{\'lbar.rd.reviews.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n        {else}\n        <a class=\"lb-btn lb-btn--solid lb-btn--sm lb-reviews__btn\" href=\"{$allId | url}\">{\'lbar.rd.reviews.all\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n        {/if}\n        <button class=\"lb-btn lb-btn--ghost lb-btn--sm lb-reviews__btn js-lb-review-form\" type=\"button\" aria-haspopup=\"dialog\" aria-controls=\"lb-rform\">{\'lbar.reviews.form.title\' | lexicon}<svg class=\"lb-reviews__pen\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 20h4.2L19.4 8.8a2.3 2.3 0 0 0 0-3.2l-1-1a2.3 2.3 0 0 0-3.2 0L4 15.8V20z\"/><path d=\"m13.6 6.2 4.2 4.2\"/></svg></button>\n    </div>\n\n    {* окно: полный текст отзыва (заполняется из карточки) *}\n    <dialog class=\"lb-rmodal\" id=\"lb-rmodal\" aria-labelledby=\"lb-rmodal-name\">\n        <div class=\"lb-rmodal__box\">\n            <button class=\"lb-rmodal__close\" type=\"button\" aria-label=\"{\'lbar.rd.reviews.close\' | lexicon}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg></button>\n            <div class=\"lb-rmodal__body\"></div>\n        </div>\n    </dialog>\n\n    {* окно: форма отзыва EasyComm *}\n    <dialog class=\"lb-rmodal lb-rmodal--form\" id=\"lb-rform\" aria-labelledby=\"lb-rform-title\">\n        <div class=\"lb-rmodal__box\">\n            <button class=\"lb-rmodal__close\" type=\"button\" aria-label=\"{\'lbar.rd.reviews.close\' | lexicon}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6 6 18\"/></svg></button>\n            <div class=\"lb-rmodal__title\" id=\"lb-rform-title\">{\'lbar.reviews.form.title\' | lexicon}</div>\n            [[!ecForm?\n                &thread=`resource-{$tid}`\n                &tplForm=`lb.ecForm`\n                &tplSuccess=`tpl.ecForm.Success.Blog`\n                &tplNewEmailManager=`tpl.ecForm.New.Email.Manager.Blog`\n                &tplUpdateEmailUser=`tpl.ecForm.Update.Email.User.Blog`\n                &tplNewEmailUser=`tpl.ecForm.New.Email.User.Blog`\n            ]]\n        </div>\n    </dialog>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-reviews.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (286,1,0,'lb.reviewsWrap','Редизайн: обёртка отзывов с рейтингом и каруселью (tplWrapper для ecMessages)',0,128,0,'{* Обёртка ecMessages для блока «Отзывы» (tplWrapper): рейтинг ветки EasyComm + карусель карточек.\n   Поля ветки: rating_simple (средняя оценка), count (число опубликованных отзывов); {$output} — карточки lb.reviewCard.\n   Навигация (стрелки, точки) — JS (redesign.js): если карточки помещаются в ширину экрана — ряд без карусели. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $lang = $_modx->config.cultureKey}\n{set $n = $count | number_format : 0 : \'\' : \'\'}\n{set $forms = $_modx->lexicon(\'lbar.rd.reviews.forms\') | split : \'|\'}\n{if $lang == \'ru\'}\n{set $word = $count | declension : $_modx->lexicon(\'lbar.rd.reviews.forms\')}\n{else}\n{set $m = $count % 100}\n{set $word = ($count == 1) ? $forms[0] : (($m >= 1 && $m <= 19) ? $forms[1] : $forms[2])}\n{/if}\n{set $star = \'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2.4l2.95 6.02 6.63.95-4.8 4.67 1.13 6.6L12 17.52l-5.91 3.12 1.13-6.6-4.8-4.67 6.63-.95z\"/></svg>\'}\n{if $output}\n<div class=\"lb-reviews__pill\">\n    {* значок «Google Reviews» (как в макете); логотип — google-icon из набора @iconify-json/logos *}\n    <div class=\"lb-reviews__google\">\n        <svg class=\"lb-reviews__g\" viewBox=\"0 0 256 262\" aria-hidden=\"true\"><path fill=\"#4285f4\" d=\"M255.878 133.451c0-10.734-.871-18.567-2.756-26.69H130.55v48.448h71.947c-1.45 12.04-9.283 30.172-26.69 42.356l-.244 1.622l38.755 30.023l2.685.268c24.659-22.774 38.875-56.282 38.875-96.027\"/><path fill=\"#34a853\" d=\"M130.55 261.1c35.248 0 64.839-11.605 86.453-31.622l-41.196-31.913c-11.024 7.688-25.82 13.055-45.257 13.055c-34.523 0-63.824-22.773-74.269-54.25l-1.531.13l-40.298 31.187l-.527 1.465C35.393 231.798 79.49 261.1 130.55 261.1\"/><path fill=\"#fbbc05\" d=\"M56.281 156.37c-2.756-8.123-4.351-16.827-4.351-25.82c0-8.994 1.595-17.697 4.206-25.82l-.073-1.73L15.26 71.312l-1.335.635C5.077 89.644 0 109.517 0 130.55s5.077 40.905 13.925 58.602z\"/><path fill=\"#eb4335\" d=\"M130.55 50.479c24.514 0 41.05 10.589 50.479 19.438l36.844-35.974C195.245 12.91 165.798 0 130.55 0C79.49 0 35.393 29.301 13.925 71.947l42.211 32.783c10.59-31.477 39.891-54.251 74.414-54.251\"/></svg>\n        <span>{$_modx->lexicon(\'lbar.rd.reviews.google\')}</span>\n    </div>\n    <span class=\"lb-reviews__sep\" aria-hidden=\"true\"></span>\n    {if $rating_simple > 0}\n    <div class=\"lb-reviews__score\"><b class=\"lb-reviews__num\">{$rating_simple | number_format : 1 : \'.\' : \'\'}</b><span class=\"lb-reviews__max\">/5</span></div>\n    <div class=\"lb-reviews__stars\" role=\"img\" aria-label=\"{$rating_simple | number_format : 1 : \'.\' : \'\'} {$_modx->lexicon(\'lbar.rd.reviews.of\')} 5\">\n        {foreach 1..5 as $i}<span class=\"lb-reviews__star{if $i > ($rating_simple + 0.25)} is-off{/if}\">{$star}</span>{/foreach}\n    </div>\n    <span class=\"lb-reviews__sep\" aria-hidden=\"true\"></span>\n    {/if}\n    <div class=\"lb-reviews__based\">{$_modx->lexicon(\'lbar.rd.reviews.based\')} {$n} {$word}</div>\n</div>\n\n<div class=\"lb-reviews__carousel\" data-prev=\"{$_modx->lexicon(\'lbar.rd.reviews.prev\')}\" data-next=\"{$_modx->lexicon(\'lbar.rd.reviews.next\')}\" data-dot=\"{$_modx->lexicon(\'lbar.rd.reviews.dot\')}\" data-read=\"{$_modx->lexicon(\'lbar.rd.reviews.read\')}\">\n    <div class=\"lb-reviews__viewport\">\n        <div class=\"lb-reviews__track\">\n            {$output}\n        </div>\n    </div>\n    <div class=\"lb-reviews__nav\">\n        <button class=\"lb-reviews__arrow lb-reviews__arrow--prev\" type=\"button\" aria-label=\"{$_modx->lexicon(\'lbar.rd.reviews.prev\')}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14.5 6.5 9 12l5.5 5.5\"/></svg></button>\n        <div class=\"lb-reviews__dots\"></div>\n        <button class=\"lb-reviews__arrow lb-reviews__arrow--next\" type=\"button\" aria-label=\"{$_modx->lexicon(\'lbar.rd.reviews.next\')}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M9.5 6.5 15 12l-5.5 5.5\"/></svg></button>\n    </div>\n</div>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.reviewsWrap.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (287,1,0,'lb-faq','Редизайн: блок «Вопросы и ответы» (главная)',0,128,0,'{* Блок «Вопросы и ответы» (редизайн, главная, после «Отзывов») — вместо bl-faq (условие migx_questions:notempty в шаблоне сохранено).\n   H2 — прежний TV title-bl-faq (текст не менялся); разбивка на строки и курсив — лексикон lbar.rd.faq.title\n   («|» — перенос, *…* — курсив; сравнение — без тегов: в RU-TV есть <br/>). Если TV изменят — H2 выводится как есть.\n   Вопросы и ответы — прежний MIGX TV migx_questions (questions-title / questions-text, до 18 шт., как в старом getImageList).\n   Микроразметка schema.org FAQPage / Question / Answer — как в старом блоке. Аккордеон — redesign.js (первый вопрос открыт).\n   Слева — короткий текст и кнопки (лексикон lbar.rd.faq.*): консультация → блок «Консультация», телефон — настройка phone-1\n   (настройки ClientConfig — MODX-тегами (++ключ): в $_modx->config Fenom их может не оказаться, и в кэш попадёт пусто). *}\n{set $raw = $_modx->resource[\'title-bl-faq\'] | trim}\n{set $title = $raw | striptags | replace : \'  \' : \' \' | trim}\n{set $fmt = \'lbar.rd.faq.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n{set $items = $_modx->resource[\'migx_questions\'] | fromJSON}\n{if $items}\n<section class=\"lb-faq\" id=\"lb-faq\">\n    <div class=\"lb-faq__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-faq__inner\">\n        <div class=\"lb-faq__intro\">\n            {if $raw}\n            <h2 class=\"lb-faq__title\">\n                {if $plain == $title}\n                {foreach ($fmt | split : \'|\') as $line}\n                <span class=\"lb-faq__line\"><span class=\"lb-faq__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n                {/foreach}\n                {else}\n                <span class=\"lb-faq__line\"><span class=\"lb-faq__lin\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $raw])}</span></span>\n                {/if}\n            </h2>\n            <svg class=\"lb-faq__flourish\" viewBox=\"0 0 440 50\" aria-hidden=\"true\">\n                <defs>\n                    <linearGradient id=\"lb-faq-fl\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n                        <stop offset=\"0\" stop-color=\"#a87856\" stop-opacity=\".2\"/>\n                        <stop offset=\".25\" stop-color=\"#a87856\" stop-opacity=\".9\"/>\n                        <stop offset=\".6\" stop-color=\"#a87856\" stop-opacity=\".85\"/>\n                        <stop offset=\"1\" stop-color=\"#a87856\" stop-opacity=\"0\"/>\n                    </linearGradient>\n                </defs>\n                <path fill=\"url(#lb-faq-fl)\" d=\"M12 45C110 25 240 9 392 13C250 14 120 30 12 45Z\"/>\n                <path fill=\"url(#lb-faq-fl)\" d=\"M100 40C140 26 190 15 250 11C195 18 150 30 106 42C101 44 97 42 100 40Z\"/>\n            </svg>\n            {/if}\n            <p class=\"lb-faq__text\">{\'lbar.rd.faq.text\' | lexicon}</p>\n            <div class=\"lb-faq__ctas\">\n                <a class=\"lb-btn lb-btn--solid lb-faq__btn js-lb-book\" href=\"#lb-consult\">{\'lbar.rd.faq.cta\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n                <a class=\"lb-btn lb-btn--ghost lb-faq__btn lb-faq__btn--tel\" href=\"tel:[[++phone-1:replace=` ==`]]\"><svg class=\"lb-faq__tel\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 16.4v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 1.1 3.7 2 2 0 0 1 3.1 1.5h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L7.1 9.3a16 16 0 0 0 6 6l1.2-1.2a2 2 0 0 1 2.1-.5c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.8 2.1z\"/></svg>[[++phone-1]]</a>\n            </div>\n        </div>\n\n        <ul class=\"lb-faq__list\" itemscope=\"itemscope\" itemtype=\"https://schema.org/FAQPage\">\n            {foreach $items as $i => $it}\n            {if $i >= 18}{break}{/if}\n            {set $n = $i + 1}\n            <li class=\"lb-faq__item{if $n == 1} is-open{/if}\" itemprop=\"mainEntity\" itemscope=\"itemscope\" itemtype=\"https://schema.org/Question\">\n                <button class=\"lb-faq__q\" type=\"button\" id=\"lb-faq-q{$n}\" aria-controls=\"lb-faq-a{$n}\" aria-expanded=\"{$n == 1 ? \'true\' : \'false\'}\">\n                    <span class=\"lb-faq__num\" aria-hidden=\"true\">{$n < 10 ? \'0\' : \'\'}{$n}</span>\n                    <span class=\"lb-faq__qt\" itemprop=\"name\">{$it[\'questions-title\']}</span>\n                    <span class=\"lb-faq__ic\" aria-hidden=\"true\"></span>\n                </button>\n                <div class=\"lb-faq__a\" id=\"lb-faq-a{$n}\" role=\"region\" aria-labelledby=\"lb-faq-q{$n}\" itemprop=\"acceptedAnswer\" itemscope=\"itemscope\" itemtype=\"https://schema.org/Answer\">\n                    <div class=\"lb-faq__ain\">\n                        <div class=\"lb-faq__body\" itemprop=\"text\">{$it[\'questions-text\']}</div>\n                    </div>\n                </div>\n            </li>\n            {/foreach}\n        </ul>\n    </div>\n</section>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-faq.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (288,1,0,'lb-seo','Редизайн: блок «SEO-текст» (главная)',0,128,0,'{* Блок «SEO-текст» (редизайн, главная и страницы услуг, после FAQ) — вместо bl-seo.\n   ВАЖНО: тексты выводятся как есть, теми же тегами MODX, что в старом чанке (TV title-bl-seo, text-bl-seo, text-bl-seo-2).\n   В HTML текста ничего не добавляется и не меняется (никаких span/em/классов внутри): всё оформление — только CSS по существующим тегам\n   (h2, h3, p, ul/li, strong) в scss/_seo.scss. Новые здесь только обёртки блока. Декоративная opacity-text-bl11.png не выводится.\n   Картинка TV img-bl-seo (alt — img-bl-alt, как в старом bl-seo; пусто — текст H2): слева, справа — H2 и первый текст за медной линией\n   (модификатор --img). Нет картинки — H2 слева, текст справа (как в макете главной). *}\n{set $pic = \'[[*img-bl-seo]]\' | trim}\n<section class=\"lb-seo\" id=\"lb-seo\">\n    <div class=\"lb-seo__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-seo__inner\">\n        {if $pic}\n        <div class=\"lb-seo__head lb-seo__head--img\">\n            <img class=\"lb-seo__img\" src=\"/{$pic | replace : \' \' : \'%20\'}\" alt=\"{((\'[[*img-bl-alt]]\' | trim) ?: (\'[[*title-bl-seo]]\' | striptags | trim)) | escape}\" width=\"560\" height=\"400\" loading=\"lazy\" decoding=\"async\">\n            <div class=\"lb-seo__side\">\n                <h2 class=\"lb-seo__title\">[[*title-bl-seo]]</h2>\n                <div class=\"lb-seo__lead\">[[*text-bl-seo]]</div>\n            </div>\n        </div>\n        {else}\n        <div class=\"lb-seo__head\">\n            <h2 class=\"lb-seo__title\">[[*title-bl-seo]]</h2>\n            <div class=\"lb-seo__lead\">[[*text-bl-seo]]</div>\n        </div>\n        {/if}\n        <div class=\"lb-seo__body\">[[*text-bl-seo-2]]</div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-seo.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (289,1,0,'lb-blog','Редизайн: блок «Статьи» (главная)',0,128,0,'{* Блок «Статьи» (редизайн, главная, после SEO-текста) — вместо bl-blog. Макета не было — сделан в стилистике сайта.\n   Данные — прежние TV главной: заголовок title-blog-bl12 (как и раньше — не заголовок h2, а подпись блока; разбивка/курсив — лексикон\n   lbar.rd.blog.title, если TV изменят — выводится как есть), карточки img-st-N / alt-st-N / title-st-N / text-st-N (N = 1…3; 2-я и 3-я —\n   если заполнен заголовок, как в старом чанке). В старом чанке у 2-й карточки по ошибке выводился text-st-1 — здесь text-st-2.\n   Ссылка карточки — TV link-st-N (id или путь статьи, разбор — чанк lb.blogHref): если статья опубликована, заголовок становится ссылкой,\n   а её область (::after) растянута на всю карточку; удалённые / снятые статьи — карточка без ссылки. Кнопка «Toate articolele» — на блог (RO, id 31);\n   в RU блога нет — кнопка не выводится. Картинки — pthumb, как раньше (в RU pthumb отдаёт путь с /ru/ — убираем: файл лежит в /assets/image-cache/); если файла нет — под ним графическая подложка. *}\n{if $_modx->config.cultureKey != \'en\'}{* в EN блога нет (статьи не переводились) — блок не выводится *}\n{set $raw = $_modx->resource[\'title-blog-bl12\'] | trim}\n{set $title = $raw | striptags | replace : \'  \' : \' \' | trim}\n{set $fmt = \'lbar.rd.blog.title\' | lexicon}\n{set $plain = $fmt | replace : \'|\' : \' \' | replace : \'*\' : \'\'}\n{set $isRu = $_modx->config.cultureKey == \'ru\'}\n{set $read = \'lbar.rd.blog.read\' | lexicon}\n{* Карточки — развёрнуты по номерам. Порядок обработки: сначала MODX-теги, потом Fenom — поэтому переменные Fenom внутри MODX-тегов нельзя\n   (pThumb получал имя TV с «{$i}» буквально), а значения TV — не в строковые литералы Fenom (кавычки в тексте сломали бы шаблон). *}\n<section class=\"lb-blog\" id=\"lb-blog\">\n    <div class=\"lb-blog__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-blog__inner\">\n        {if $raw}\n        <div class=\"lb-blog__head\">\n            <div class=\"lb-blog__title\">\n                {if $plain == $title}\n                {foreach ($fmt | split : \'|\') as $line}\n                <span class=\"lb-blog__line\"><span class=\"lb-blog__lin\">{foreach ($line | split : \'*\') as $k => $part}{if $k % 2}<em>{$part}</em>{else}{$part}{/if}{/foreach}</span></span>\n                {/foreach}\n                {else}\n                <span class=\"lb-blog__line\"><span class=\"lb-blog__lin\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $raw])}</span></span>\n                {/if}\n            </div>\n            <svg class=\"lb-blog__flourish\" viewBox=\"0 0 440 50\" aria-hidden=\"true\">\n                <defs>\n                    <linearGradient id=\"lb-blog-fl\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n                        <stop offset=\"0\" stop-color=\"#a87856\" stop-opacity=\"0\"/>\n                        <stop offset=\".3\" stop-color=\"#a87856\" stop-opacity=\".9\"/>\n                        <stop offset=\".7\" stop-color=\"#a87856\" stop-opacity=\".85\"/>\n                        <stop offset=\"1\" stop-color=\"#a87856\" stop-opacity=\"0\"/>\n                    </linearGradient>\n                </defs>\n                <path fill=\"url(#lb-blog-fl)\" d=\"M12 45C110 25 240 9 392 13C250 14 120 30 12 45Z\"/>\n                <path fill=\"url(#lb-blog-fl)\" d=\"M100 40C140 26 190 15 250 11C195 18 150 30 106 42C101 44 97 42 100 40Z\"/>\n            </svg>\n        </div>\n        {/if}\n\n        <div class=\"lb-blog__list\">\n            {set $href1 = $_modx->getChunk(\'lb.blogHref\', [\'v\' => $_modx->resource[\'link-st-1\']]) | trim}\n            <article class=\"lb-blog__card{if $href1} lb-blog__card--link{/if}\">\n                <div class=\"lb-blog__img\">\n                    <img src=\"[[pthumb:replace=`/ru/assets/==/assets/`? &input=`[[*img-st-1]]` &options=`w=1040&h=700&zc=1`]]\" alt=\"[[*alt-st-1]]\" width=\"520\" height=\"350\">\n                </div>\n                <div class=\"lb-blog__info\">\n                    <span class=\"lb-blog__num\" aria-hidden=\"true\">01</span>\n                    <div class=\"lb-blog__name\">{if $href1}<a class=\"lb-blog__link\" href=\"{$href1}\">[[*title-st-1]]</a>{else}[[*title-st-1]]{/if}</div>\n                    <div class=\"lb-blog__text\">[[*text-st-1]]</div>\n                    {if $href1}<span class=\"lb-blog__more\" aria-hidden=\"true\">{$read}<svg viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></span>{/if}\n                </div>\n            </article>\n            {if ($_modx->resource[\'title-st-2\'] | trim)}\n            {set $href2 = $_modx->getChunk(\'lb.blogHref\', [\'v\' => $_modx->resource[\'link-st-2\']]) | trim}\n            <article class=\"lb-blog__card{if $href2} lb-blog__card--link{/if}\">\n                <div class=\"lb-blog__img\">\n                    <img src=\"[[pthumb:replace=`/ru/assets/==/assets/`? &input=`[[*img-st-2]]` &options=`w=1040&h=700&zc=1`]]\" alt=\"[[*alt-st-2]]\" width=\"520\" height=\"350\">\n                </div>\n                <div class=\"lb-blog__info\">\n                    <span class=\"lb-blog__num\" aria-hidden=\"true\">02</span>\n                    <div class=\"lb-blog__name\">{if $href2}<a class=\"lb-blog__link\" href=\"{$href2}\">[[*title-st-2]]</a>{else}[[*title-st-2]]{/if}</div>\n                    <div class=\"lb-blog__text\">[[*text-st-2]]</div>\n                    {if $href2}<span class=\"lb-blog__more\" aria-hidden=\"true\">{$read}<svg viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></span>{/if}\n                </div>\n            </article>\n            {/if}\n            {if ($_modx->resource[\'title-st-3\'] | trim)}\n            {set $href3 = $_modx->getChunk(\'lb.blogHref\', [\'v\' => $_modx->resource[\'link-st-3\']]) | trim}\n            <article class=\"lb-blog__card{if $href3} lb-blog__card--link{/if}\">\n                <div class=\"lb-blog__img\">\n                    <img src=\"[[pthumb:replace=`/ru/assets/==/assets/`? &input=`[[*img-st-3]]` &options=`w=1040&h=700&zc=1`]]\" alt=\"[[*alt-st-3]]\" width=\"520\" height=\"350\">\n                </div>\n                <div class=\"lb-blog__info\">\n                    <span class=\"lb-blog__num\" aria-hidden=\"true\">03</span>\n                    <div class=\"lb-blog__name\">{if $href3}<a class=\"lb-blog__link\" href=\"{$href3}\">[[*title-st-3]]</a>{else}[[*title-st-3]]{/if}</div>\n                    <div class=\"lb-blog__text\">[[*text-st-3]]</div>\n                    {if $href3}<span class=\"lb-blog__more\" aria-hidden=\"true\">{$read}<svg viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></span>{/if}\n                </div>\n            </article>\n            {/if}\n        </div>\n\n        {if !$isRu}\n        <div class=\"lb-blog__cta\">\n            <a class=\"lb-btn lb-btn--ghost\" href=\"[[~31]]\">{\'lbar.rd.blog.all\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n        </div>\n        {/if}\n    </div>\n</section>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-blog.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (290,1,0,'lb-contact','Редизайн: блок «Контакты» (главная)',0,128,0,'{* Блок «Контакты» (редизайн: главная и внутренние страницы перед подвалом; страница «Контакты» — режим page) — вместо bl-contact /\n   bl-contact-page. Вид — по макету: слева заголовок с линией и звездой, подзаголовок и карта; справа стеклянная карточка — телефон,\n   почта, адрес, разделитель, график, три плашки «как добраться» (метро / трамвай) и кнопка «By appointment only» (запись: якорь\n   #bl8-form, нет формы на странице — окно «Заказать звонок», js-lb-book).\n   H2 — прежний лексикон lbar.contacts.title (на странице «Контакты» вместо него — H1, см. ниже). Телефон и почта — настройки phone-1 / e-mail, карта — настройка google-map (iframe Google),\n   как раньше (в {disableSource} — карта не отдаётся Lighthouse); язык карточки Google — язык контекста (RO — румынский, EN — английский, RU — как в настройке). Адрес, метро, трамвай, график —\n   лексикон lbar.rd.contacts.* (у метро время после « – » выводится второй строкой).\n   Страница «Контакты» (шаблон «Контакты», 9): блок — первый экран под шапкой (баннера нет): заголовок блока — H1 с исходным текстом\n   (pagetitle, как в старом banner-interial-contact), хлебные крошки — pdoCrumbs с прежними параметрами и микроразметкой — под картой.\n   Якорь #conract (старые ссылки) сохранён. *}\n{set $lang = $_modx->config.cultureKey}\n{set $page = $_modx->resource.template == 9}\n{* настройки ClientConfig выводим MODX-тегами (++ключ): в $_modx->config Fenom их может не оказаться (снимок конфига до ClientConfig) — в кэш попало бы пусто *}\n{set $mapTitle = \'lbar.rd.contacts.map\' | lexicon}\n{set $sub = \'lbar.rd.contacts.sub\' | lexicon}\n{set $star = \'<svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M10 0c.5 5.3 4.2 9.3 10 10-5.8.7-9.5 4.7-10 10-.5-5.3-4.2-9.3-10-10C5.8 9.3 9.5 5.3 10 0z\"/></svg>\'}\n{set $walk = \'<svg class=\"lb-contact__walk\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" role=\"img\" aria-label=\"\' ~ (\'lbar.rd.contacts.walk\' | lexicon) ~ \'\"><circle cx=\"13.2\" cy=\"3.6\" r=\"1.8\"/><path d=\"m10 21 2-6.5 3 3V22M8 12.5l1.5-4.2a2 2 0 0 1 2.4-1.2l1.4.4a2 2 0 0 1 1.3 1.3l.9 2.8 2.5 1.4M12 14.5l-.9-4.3-2.6 2.3L6.5 11\"/></svg>\'}\n<div id=\"conract\"></div>\n<section class=\"lb-contact{$page ? \' lb-contact--page\' : \'\'}\" id=\"lb-contact\">\n    <div class=\"lb-contact__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-contact__inner\">\n        <div class=\"lb-contact__main\">\n            <div class=\"lb-contact__head\">\n                {if $page}\n                <h1 class=\"lb-contact__title\">{$_modx->resource.pagetitle}</h1>\n                {else}\n                <h2 class=\"lb-contact__title\">{$_modx->lexicon(\'lbar.contacts.title\')}</h2>\n                {/if}\n                <span class=\"lb-contact__line\" aria-hidden=\"true\">{$star}</span>\n            </div>\n            <p class=\"lb-contact__sub\">{foreach ($sub | split : \'*\') as $k => $part}{if $k % 2}<span class=\"lb-contact__accent\">{$part}</span>{else}{$part}{/if}{/foreach}</p>\n            <div class=\"lb-contact__map\">\n                <div class=\"lb-contact__mapph\" aria-hidden=\"true\"></div>\n                <div class=\"lb-contact__frame\">{disableSource}{if $lang == \'ru\'}[[++google-map:replace=`<iframe ==<iframe title=\"{$mapTitle}\" `]]{elseif $lang == \'en\'}[[++google-map:replace=`!1sru!2sro==!1sen!2sro`:replace=`<iframe ==<iframe title=\"{$mapTitle}\" `]]{else}[[++google-map:replace=`!1sru!2sro==!1sro!2sro`:replace=`<iframe ==<iframe title=\"{$mapTitle}\" `]]{/if}{/disableSource}</div>\n            </div>\n            {if $page}\n            <nav class=\"lb-crumbs lb-contact__crumbs\" aria-label=\"{\'lbar.rd.aria.crumbs\' | lexicon}\">\n                {$_modx->runSnippet(\'!pdoCrumbs\', [\n                    \'showHome\' => 1,\n                    \'showAtHome\' => 0,\n                    \'tplWrapper\' => \'@INLINE <ol class=\"lb-crumbs__list\" itemscope itemtype=\"http://schema.org/BreadcrumbList\">[[+output]]</ol>\',\n                    \'tplHome\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link lb-crumbs__link--home\" href=\"[[+link]]\" itemprop=\"item\"><svg viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.2 10 3l7 6.2\"/><path d=\"M5 8v9h4v-5h2v5h4V8\"/></svg><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                    \'tpl\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link\" href=\"[[+link]]\" itemprop=\"item\"><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                    \'tplCurrent\' => \'@INLINE <li class=\"lb-crumbs__item lb-crumbs__item--current\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><span itemprop=\"name\">[[+menutitle]]</span><div itemprop=\"item\" content=\"[[++site_url]][[+link]]\"></div><meta itemprop=\"position\" content=\"[[+idx]]\" /></li>\',\n                ])}\n            </nav>\n            {/if}\n        </div>\n\n        <div class=\"lb-contact__card\">\n            <ul class=\"lb-contact__list\">\n                <li class=\"lb-contact__row\">\n                    <span class=\"lb-contact__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 16.4v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 1.1 3.7 2 2 0 0 1 3.1 1.5h3a2 2 0 0 1 2 1.7c.1 1 .4 1.9.7 2.8a2 2 0 0 1-.5 2.1L7.1 9.3a16 16 0 0 0 6 6l1.2-1.2a2 2 0 0 1 2.1-.5c.9.3 1.8.6 2.8.7a2 2 0 0 1 1.8 2.1z\"/></svg></span>\n                    <a class=\"lb-contact__big\" href=\"tel:[[++phone-1:replace=` ==`]]\" aria-label=\"{\'lbar.rd.contacts.phone\' | lexicon}: [[++phone-1]]\">[[++phone-1]]</a>\n                </li>\n                <li class=\"lb-contact__row\">\n                    <span class=\"lb-contact__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2.5\" y=\"4.5\" width=\"19\" height=\"15\" rx=\"2\"/><path d=\"m3 6 9 7 9-7\"/></svg></span>\n                    <a class=\"lb-contact__mail\" href=\"mailto:[[++e-mail]]\" aria-label=\"{\'lbar.rd.contacts.email\' | lexicon}: [[++e-mail]]\">[[++e-mail]]</a>\n                </li>\n                <li class=\"lb-contact__row\">\n                    <span class=\"lb-contact__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21.5s-7-6.1-7-11.7a7 7 0 0 1 14 0c0 5.6-7 11.7-7 11.7z\"/><circle cx=\"12\" cy=\"9.8\" r=\"2.6\"/></svg></span>\n                    <address class=\"lb-contact__addr\"><a href=\"{\'lbar.rd.contacts.mapurl\' | lexicon}\" target=\"_blank\" rel=\"nofollow noopener\"><b>{\'lbar.rd.contacts.city\' | lexicon}</b><span>{\'lbar.rd.contacts.street\' | lexicon}</span></a></address>\n                </li>\n            </ul>\n\n            <div class=\"lb-contact__sep\" aria-hidden=\"true\">{$star}</div>\n\n            <div class=\"lb-contact__row lb-contact__row--time\">\n                <span class=\"lb-contact__ic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3.5\" y=\"5\" width=\"17\" height=\"15.5\" rx=\"2.5\"/><path d=\"M3.5 10h17M8 3v4M16 3v4\"/></svg></span>\n                <div class=\"lb-contact__time\">\n                    <b>{\'lbar.rd.contacts.schedule.title\' | lexicon}</b>\n                    <span>{\'lbar.rd.contacts.schedule\' | lexicon}</span>\n                </div>\n            </div>\n\n            <ul class=\"lb-contact__route\">\n                {foreach [\'metro1\', \'metro2\'] as $m}\n                {set $mt = (\'lbar.rd.contacts.\' ~ $m) | lexicon}\n                {set $mn = $mt | ereplace : \'~\\s+[–-]\\s+.*$~u\' : \'\'}\n                {set $mm = ($mn != $mt) ? ($mt | ereplace : \'~^.*\\s[–-]\\s+~u\' : \'\') : \'\'}\n                <li class=\"lb-contact__tile\">\n                    <span class=\"lb-contact__tic lb-contact__tic--metro\" aria-hidden=\"true\">M</span>\n                    <span class=\"lb-contact__ttxt\"><span class=\"lb-contact__tname\">{$mn}</span>{if $mm}<span class=\"lb-contact__tmeta\">~ {$mm}{$walk}</span>{/if}</span>\n                </li>\n                {/foreach}\n                <li class=\"lb-contact__tile\">\n                    <span class=\"lb-contact__tic\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"5\" y=\"5.5\" width=\"14\" height=\"12\" rx=\"3\"/><path d=\"M5 12.5h14M9 2.5h6M12 2.5v3M8.5 15h.01M15.5 15h.01M8 17.5l-1.5 3M16 17.5l1.5 3\"/></svg></span>\n                    <span class=\"lb-contact__ttxt\"><span class=\"lb-contact__tname\">{\'lbar.rd.contacts.tram\' | lexicon}</span></span>\n                </li>\n            </ul>\n\n            <a class=\"lb-btn lb-btn--solid lb-contact__btn js-lb-book\" href=\"#bl8-form\">{\'lbar.rd.contacts.appointment\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-contact.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (291,1,0,'lb-footer','Редизайн: подвал (только главная)',0,128,0,'{* Подвал (редизайн) — вместо footer, ТОЛЬКО в шаблоне «Главная» (старый footer остаётся на остальных шаблонах). Макета не было — в стилистике сайта.\n   Данные — как в старом подвале: копирайт (лексикон lbar.footer.copyright), меню — поля foot-link-l / foot-link-r главной (pdoField, вывод как есть;\n   в RU там текст без ссылок — так и было), соцсети — настройки youtube / facebook / insta (+ telegram / viber / whatsapp, которые были в старом блоке\n   контактов), кнопка «Solicită un apel» + окно с формой — та же разметка и AjaxForm, что в старом подвале (открывает старый custom.js: .btn-mobal →\n   соседний .form-modal-overlay; вид окна переопределён в _footer.scss). Контакты и график — как в блоке «Контакты» (лексикон lbar.rd.contacts.*).\n   Иконки соцсетей — набор Simple Icons (CC0). Кнопка «наверх» (.cd-top, старый main.js) и кнопка WhatsApp — прежняя разметка. *}\n{* настройки ClientConfig — MODX-тегами (++ключ) (как в старом подвале): в $_modx->config Fenom их может не оказаться — в кэш попало бы пусто *}\n</main>{* открыт в конце lb-header *}\n<footer class=\"lb-footer\" id=\"lb-footer\">\n    <div class=\"lb-footer__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-footer__inner\">\n        <div class=\"lb-footer__top\">\n            <div class=\"lb-footer__brand\">\n                <a class=\"lb-footer__logo\" href=\"[[++site_url]]\" aria-label=\"[[++site_name]]\"><img src=\"/assets/templates/redesign/img/logo-light.svg?v=3\" width=\"242\" height=\"119\" alt=\"LBar\" loading=\"lazy\"></a>\n                <p class=\"lb-footer__copy\">&copy; 2016 - {\'\' | date : \'Y\'}. <br/>{$_modx->lexicon(\"lbar.footer.copyright\")}</p>\n                <div class=\"lb-footer__social\">\n            <a class=\"lb-footer__soc\" href=\"[[++youtube]]\" rel=\"nofollow\" target=\"_blank\" aria-label=\"YouTube\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M23.498 6.186a3.02 3.02 0 0 0-2.122-2.136C19.505 3.545 12 3.545 12 3.545s-7.505 0-9.377.505A3.02 3.02 0 0 0 .502 6.186C0 8.07 0 12 0 12s0 3.93.502 5.814a3.02 3.02 0 0 0 2.122 2.136c1.871.505 9.376.505 9.376.505s7.505 0 9.377-.505a3.02 3.02 0 0 0 2.122-2.136C24 15.93 24 12 24 12s0-3.93-.502-5.814M9.545 15.568V8.432L15.818 12z\"/></svg></a>\n            <a class=\"lb-footer__soc\" href=\"[[++facebook]]\" rel=\"nofollow\" target=\"_blank\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M9.101 23.691v-7.98H6.627v-3.667h2.474v-1.58c0-4.085 1.848-5.978 5.858-5.978c.401 0 .955.042 1.468.103a9 9 0 0 1 1.141.195v3.325a9 9 0 0 0-.653-.036a27 27 0 0 0-.733-.009c-.707 0-1.259.096-1.675.309a1.7 1.7 0 0 0-.679.622c-.258.42-.374.995-.374 1.752v1.297h3.919l-.386 2.103l-.287 1.564h-3.246v8.245C19.396 23.238 24 18.179 24 12.044c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.628 3.874 10.35 9.101 11.647\"/></svg></a>\n            <a class=\"lb-footer__soc\" href=\"[[++insta]]\" rel=\"nofollow\" target=\"_blank\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M7.03.084c-1.277.06-2.149.264-2.91.563a5.9 5.9 0 0 0-2.124 1.388a5.9 5.9 0 0 0-1.38 2.127C.321 4.926.12 5.8.064 7.076s-.069 1.688-.063 4.947s.021 3.667.083 4.947c.061 1.277.264 2.149.563 2.911c.308.789.72 1.457 1.388 2.123a5.9 5.9 0 0 0 2.129 1.38c.763.295 1.636.496 2.913.552c1.278.056 1.689.069 4.947.063s3.668-.021 4.947-.082c1.28-.06 2.147-.265 2.91-.563a5.9 5.9 0 0 0 2.123-1.388a5.9 5.9 0 0 0 1.38-2.129c.295-.763.496-1.636.551-2.912c.056-1.28.07-1.69.063-4.948c-.006-3.258-.02-3.667-.081-4.947c-.06-1.28-.264-2.148-.564-2.911a5.9 5.9 0 0 0-1.387-2.123a5.9 5.9 0 0 0-2.128-1.38c-.764-.294-1.636-.496-2.914-.55C15.647.009 15.236-.006 11.977 0S8.31.021 7.03.084m.14 21.693c-1.17-.05-1.805-.245-2.228-.408a3.7 3.7 0 0 1-1.382-.895a3.7 3.7 0 0 1-.9-1.378c-.165-.423-.363-1.058-.417-2.228c-.06-1.264-.072-1.644-.08-4.848c-.006-3.204.006-3.583.061-4.848c.05-1.169.246-1.805.408-2.228c.216-.561.477-.96.895-1.382a3.7 3.7 0 0 1 1.379-.9c.423-.165 1.057-.361 2.227-.417c1.265-.06 1.644-.072 4.848-.08c3.203-.006 3.583.006 4.85.062c1.168.05 1.804.244 2.227.408c.56.216.96.475 1.382.895s.681.817.9 1.378c.165.422.362 1.056.417 2.227c.06 1.265.074 1.645.08 4.848c.005 3.203-.006 3.583-.061 4.848c-.051 1.17-.245 1.805-.408 2.23c-.216.56-.477.96-.896 1.38a3.7 3.7 0 0 1-1.378.9c-.422.165-1.058.362-2.226.418c-1.266.06-1.645.072-4.85.079s-3.582-.006-4.848-.06m9.783-16.192a1.44 1.44 0 1 0 1.437-1.442a1.44 1.44 0 0 0-1.437 1.442M5.839 12.012a6.161 6.161 0 1 0 12.323-.024a6.162 6.162 0 0 0-12.323.024M8 12.008A4 4 0 1 1 12.008 16A4 4 0 0 1 8 12.008\"/></svg></a>\n                </div>\n            </div>\n\n            <nav class=\"lb-footer__nav\" aria-label=\"[[++site_name]]\">\n                <div class=\"lb-footer__col\">[[pdoField? &id=`[[++site_start]]` &field=`foot-link-l`]]</div>\n                <div class=\"lb-footer__col\">[[pdoField? &id=`[[++site_start]]` &field=`foot-link-r`]]</div>\n            </nav>\n\n            <div class=\"lb-footer__contacts\">\n                <div class=\"lb-footer__label\">{$_modx->lexicon(\'lbar.contacts.title\')}</div>\n                <a class=\"lb-footer__phone\" href=\"tel:[[++phone-1:replace=` ==`]]\">[[++phone-1]]</a>\n                <a class=\"lb-footer__mail\" href=\"mailto:[[++e-mail]]\">[[++e-mail]]</a>\n                <a class=\"lb-footer__addr\" href=\"{\'lbar.rd.contacts.mapurl\' | lexicon}\" target=\"_blank\" rel=\"nofollow noopener\">{\'lbar.rd.contacts.city\' | lexicon}, {\'lbar.rd.contacts.street\' | lexicon}</a>\n                <div class=\"lb-footer__time\">\n                    <span class=\"lb-footer__time-t\">{\'lbar.rd.contacts.schedule.title\' | lexicon}</span>\n                    <span>{\'lbar.rd.contacts.schedule\' | lexicon}</span>\n                    <span class=\"lb-footer__badge\">{\'lbar.rd.contacts.appointment\' | lexicon}</span>\n                </div>\n                <div class=\"lb-footer__call\">\n                    <button class=\"lb-btn lb-btn--solid btn-mobal\" type=\"button\">{$_modx->lexicon(\"lbar.footer.button.callback\")}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n                    <div class=\"form-modal-overlay\">\n                        <div class=\"form-modal-body\">\n                            <div class=\"form-modal-content\">\n                                <div class=\"ic-close modal-close\"></div>\n                                <div class=\"form-modal-title-content\">\n                                    <div class=\"form-modal-title-big\">{$_modx->lexicon(\"lbar.footer.popup.title\")}</div>\n                                </div>\n                                {disableSource}\n                                [[!AjaxForm?\n                                    &form=`tpl.Form.Modal`\n                                    &snippet=`FormIt`\n                                    &hooks=`spam,email,FormItSaveForm,GoogleSheetsSaveForm`\n                                    &emailSubject=`Заявка \"[[++tema.form.aparat]]\"`\n                                    &emailTo=`[[++form-mail]]`\n                                    &emailFrom=`[[++form-mail]]`\n                                    &emailFromName=`[[++site_name]]`\n                                    &emailTpl=`tpl.email`\n                                    &spamCheckIp=`true`\n                                    &validate=`name:required,phone:minLength=^10^:required,workemail:blank`\n                                    &validationErrorMessage=`Будь ласка, заповніть обов\'язкові поля*`\n                                    &successMessage=`Ваше повідомлення було успішно відправлено!`\n                                    &frontend_css=``\n                                    &frontend_js=``\n                                    &formFields = `name,phone,title,link`\n                                ]]\n                                {/disableSource}\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"lb-footer__bottom\">\n            <p class=\"lb-footer__dev\">{$_modx->lexicon(\"lbar.footer.sitedev\")}&nbsp;<a href=\"https://impulse-design.com.ua/\" target=\"_blank\" title=\"Impulse Design\" rel=\"noopener\"><img src=\"/images/design/copyright-white-min.png\" alt=\"\" width=\"152\" height=\"23\" class=\"jcepopup\" title=\"{if $_modx->config.cultureKey == \'ro\'}Crearea site-ului - studio Impulse Design{elseif $_modx->config.cultureKey == \'en\'}Website by Impulse Design{else}Создание сайта - студия Impulse Design{/if}\" /></a></p>\n        </div>\n    </div>\n</footer>\n<a href=\"#0\" class=\"cd-top\"></a>\n<a href=\"[[++whatsapp]]\" id=\"whatsapp-button\" target=\"_blank\" title=\"{if $_modx->config.cultureKey == \'ro\'}Scrie-ne pe WhatsApp{elseif $_modx->config.cultureKey == \'en\'}Message us on WhatsApp{else}Написать в Whatsapp{/if}\" rel=\"nofollow noopener noreferrer\" aria-label=\"whatsapp\">\n    <div class=\"whatsapp-button\">\n        <svg height=\"23px\" style=\"fill:#fff;fill-rule:evenodd;clip-rule:evenodd;stroke-linejoin:round;stroke-miterlimit:2;\" version=\"1.1\" viewBox=\"0 0 512 512\" width=\"23px\" xml:space=\"preserve\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:serif=\"http://www.serif.com/\" xmlns:xlink=\"http://www.w3.org/1999/xlink\">\n            <path d=\"M373.295,307.064c-6.37,-3.188 -37.687,-18.596 -43.526,-20.724c-5.838,-2.126 -10.084,-3.187 -14.331,3.188c-4.246,6.376 -16.454,20.725 -20.17,24.976c-3.715,4.251 -7.431,4.785 -13.8,1.594c-6.37,-3.187 -26.895,-9.913 -51.225,-31.616c-18.935,-16.89 -31.72,-37.749 -35.435,-44.126c-3.716,-6.377 -0.397,-9.824 2.792,-13c2.867,-2.854 6.371,-7.44 9.555,-11.16c3.186,-3.718 4.247,-6.377 6.37,-10.626c2.123,-4.252 1.062,-7.971 -0.532,-11.159c-1.591,-3.188 -14.33,-34.542 -19.638,-47.298c-5.171,-12.419 -10.422,-10.737 -14.332,-10.934c-3.711,-0.184 -7.963,-0.223 -12.208,-0.223c-4.246,0 -11.148,1.594 -16.987,7.969c-5.838,6.377 -22.293,21.789 -22.293,53.14c0,31.355 22.824,61.642 26.009,65.894c3.185,4.252 44.916,68.59 108.816,96.181c15.196,6.564 27.062,10.483 36.312,13.418c15.259,4.849 29.145,4.165 40.121,2.524c12.238,-1.827 37.686,-15.408 42.995,-30.286c5.307,-14.882 5.307,-27.635 3.715,-30.292c-1.592,-2.657 -5.838,-4.251 -12.208,-7.44m-116.224,158.693l-0.086,0c-38.022,-0.015 -75.313,-10.23 -107.845,-29.535l-7.738,-4.592l-80.194,21.037l21.405,-78.19l-5.037,-8.017c-21.211,-33.735 -32.414,-72.726 -32.397,-112.763c0.047,-116.825 95.1,-211.87 211.976,-211.87c56.595,0.019 109.795,22.088 149.801,62.139c40.005,40.05 62.023,93.286 62.001,149.902c-0.048,116.834 -95.1,211.889 -211.886,211.889m180.332,-392.224c-48.131,-48.186 -112.138,-74.735 -180.335,-74.763c-140.514,0 -254.875,114.354 -254.932,254.911c-0.018,44.932 11.72,88.786 34.03,127.448l-36.166,132.102l135.141,-35.45c37.236,20.31 79.159,31.015 121.826,31.029l0.105,0c140.499,0 254.87,-114.366 254.928,-254.925c0.026,-68.117 -26.467,-132.166 -74.597,-180.352\" id=\"WhatsApp-Logo\"></path>\n        </svg>\n    </div>\n</a>\n',0,NULL,1,'core/elements/redesign/chunks/lb-footer.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (319,1,0,'lb-aculise','Редизайн',0,128,0,'{* Страница «О нас» (шаг 47, видео — шаг 49): «За кулисами» — H2, короткий текст, ссылка на канал YouTube\n   @kseniyalbarstudio и ролики. Шаг 63: один ролик (промо студии) на всю ширину вместо пяти в сетке (были 2 + 3, на мобильном — лента;\n   прежние: PJqHE2pRXgY, PhwprTgrmi0, N0eVKPtpJFA, 3uWCXcCothQ, Qjl6Ia0EuTk — подписи lbar.rd.ab.vid.1–5).\n   Плитка — превью 16:9 с кнопкой play и подписью; по клику — ролик в окне fancybox старого main.js (группа lb-aculise).\n   Превью: src — hqdefault (есть у любого ролика, 4:3 с полосами — в плитке 16:9 полосы обрезаются ровно),\n   data-yt-hd — maxresdefault (1280×720): redesign.js подменяет, если у ролика он есть (иначе YouTube отдаёт заглушку 120×90).\n   Ролики — массив $videos (id ролика => ключ подписи в лексиконе). Один ролик — класс lb-aculise__grid--one (стили _apage.scss). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $videos = [\'2xwQU_Vt1ys\' => \'lbar.rd.ab.vid.promo\']}\n<section class=\"lb-aculise\" id=\"lb-aculise\">\n    <div class=\"lb-aculise__inner\">\n        <div class=\"lb-aculise__head\">\n            <h2 class=\"lb-aculise__title\"><span class=\"lb-aculise__t1\">{\'lbar.rd.ab.cul.h2a\' | lexicon}</span> <span class=\"lb-aculise__t2\">{\'lbar.rd.ab.cul.h2b\' | lexicon}</span></h2>\n            <div class=\"lb-aculise__aside\">\n                <p class=\"lb-aculise__side\">{\'lbar.rd.ab.cul.side\' | lexicon}</p>\n                <a class=\"lb-aculise__all\" href=\"https://www.youtube.com/@kseniyalbarstudio/videos\" target=\"_blank\" rel=\"nofollow noopener\">{\'lbar.rd.ab.vid.all\' | lexicon}<svg class=\"lb-aculise__arr\" viewBox=\"0 0 22 12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 6h19M15.5 1.5 20 6l-4.5 4.5\"/></svg></a>\n            </div>\n        </div>\n        <ul class=\"lb-aculise__grid{if count($videos) == 1} lb-aculise__grid--one{/if}\">\n            {foreach $videos as $v => $key}\n            {set $cap = $key | lexicon}\n            <li class=\"lb-aculise__item\">\n                <a class=\"lb-aculise__tile\" href=\"https://www.youtube.com/watch?v={$v}\" data-fancybox=\"lb-aculise\" data-caption=\"{$cap}\">\n                    <img src=\"https://i.ytimg.com/vi/{$v}/hqdefault.jpg\" data-yt-hd=\"https://i.ytimg.com/vi/{$v}/maxresdefault.jpg\" width=\"480\" height=\"360\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n                    <span class=\"lb-aculise__play\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M8 5.6v12.8c0 .7.8 1.1 1.4.7l10-6.4c.5-.3.5-1.1 0-1.4l-10-6.4C8.8 4.5 8 4.9 8 5.6z\"/></svg></span>\n                    <span class=\"lb-aculise__cap\">{$cap}</span>\n                </a>\n            </li>\n            {/foreach}\n        </ul>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-aculise.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (293,1,0,'lb.navParent','Редизайн: родительский пункт меню шапки (tplParentRow для pdoMenu)',0,128,0,'{* tpl родительского пункта pdoMenu в шапке (tplParentRow). Пункт «Servicii / Услуги / Services» (id 80 / 302 / 1080) — мега-меню lb.navMega,\n   остальные пункты с подменю — как раньше (выпадающий список .lb-nav__sub). *}\n{if $id == 80 || $id == 302 || $id == 1080}\n{$_modx->getChunk(\'lb.navMega\', [\'id\' => $id, \'link\' => $link, \'menutitle\' => $menutitle, \'classes\' => $classes, \'attributes\' => $attributes])}\n{else}\n<li{$classes}><a class=\"lb-nav__link\" href=\"{$link}\" {$attributes}>{$menutitle}</a><button class=\"lb-nav__toggle\" type=\"button\" aria-label=\"{$menutitle}\" aria-expanded=\"false\"></button>{$wrapper}</li>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.navParent.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (295,1,0,'lb-shero','Редизайн: баннер страниц услуг (шаблон «Категория»)',0,128,0,'{* Баннер страниц услуг (шаблон «Категория», id 8) — вместо banner-interial-category(-with-img) и breadcrumb-wrap. По макету.\n   Тексты — прежние TV ресурса, без правок:\n   - надзаголовка нет (был suptitle-banner главной — убран вместе со всеми eyebrow);\n   - H1 — title-banner: первое слово прямо, остальное курсивом (только разметка, текст H1 тот же);\n   - подзаголовок — sub-title-banner;\n   - description-banner: 2–3 строки (по <br> / <p>) до 80 символов — список с отметками (шаг 57: и короткие строки — тоже списком,\n     как у остальных услуг; колонки с иконками lb-shero__feats — только у удаления тату), иначе (длинный текст, 4+ строк) — выводится\n     как было, HTML из TV.\n   Фото — TV img_banner_main. Если его нет — фото родителя (подразделы бровей); если фото нет и у родителя — графическая подложка.\n   Плашки title/description-banner-categoty-1/2 на фото (были у страниц без своего фото) — убраны по просьбе пользователя (шаг 57).\n   Кнопки — прежние: запись (#bl8-form), консультация (#conract). Хлебные крошки — pdoCrumbs с прежними параметрами и микроразметкой.\n   Общие страницы (режим hub): «Услуги» / «Обучение» (шаблоны «Услуги — общая» и «Внутренняя - Обучение»), «Внутренняя» (3),\n   портфолио (10, 13), «Цены» (14), «Отзывы» (16), список статей блога (4) — вместо banner-interial:\n   H1 — pagetitle (как в banner-interial), под ним — TV description-banner-inerial (до 300 знаков; длиннее — в lb-pgallery),\n   хлебные крошки — без exclude (как в banner-interial). Кнопок нет (в banner-interial их не было, шаг 45);\n   фото — только своё, без фото — простой баннер: фон, H1, текст, крошки, без графики справа (lb-shero--simple, шаг 45).\n   Статья блога (5) баннера не имеет — H1, крошки и сведения выводит lb-article (шаг 45).\n   Удаление тату (шаблон «Удаление тату», шаг 54, вызов с &tz=`1`): как у услуги, но TV старого баннера banner-interial-category-new —\n   H1 title-banner-study, подзаголовок sub-title-2-banner-study, 4 преимущества text-1…4-banner-study (колонки с иконками, 2 × 2);\n   надзаголовок sub-title-1-banner-study не выводится (без eyebrow, как везде).\n   Внимание: в выражениях Fenom не писать «*» + «/» подряд (закрывает служебный комментарий в скомпилированном шаблоне). *}\n{set $r = $_modx->resource}\n{* параметр &tz из вызова чанка в шаблоне: MODX-плейсхолдер подставляется до Fenom (без параметра остаётся «[[+tz]]» → не 1) *}\n{set $tz = (\'[[+tz]]\' == \'1\')}\n{set $hub = $r.template != 8 && !$tz}\n{set $t = ($hub ? $r.pagetitle : ($tz ? $r[\'title-banner-study\'] : $r[\'title-banner\'])) | trim}\n{set $first = $t | ereplace : \'~\\s.*$~s\' : \'\'}\n{set $rest = $t | ereplace : \'~^\\S+\\s*~\' : \'\'}\n\n{* преимущества *}\n{set $desc = $hub ? \'\' : ($r[\'description-banner\'] | trim)}\n{set $items = []}\n{set $max = 0}\n{if $desc}\n{foreach ($desc | ereplace : \'~<br[^>]*>|</p>|</li>|</div>~i\' : \'|\' | striptags | ereplace : \'~\\s+~u\' : \' \' | split : \'|\') as $it}\n{set $it = $it | trim}\n{if $it}{set $items[] = $it}{if ($it | length) > $max}{set $max = $it | length}{/if}{/if}\n{/foreach}\n{/if}\n{if $tz}\n{set $items = []}\n{foreach [1, 2, 3, 4] as $k}{set $it = $r[\'text-\' ~ $k ~ \'-banner-study\'] | striptags | trim}{if $it}{set $items[] = $it}{/if}{/foreach}\n{/if}\n{set $n = $items | length}\n{set $mode = $tz ? ($n ? \'cols\' : \'\') : (($n >= 2 && $n <= 3) ? ($max <= 80 ? \'list\' : \'html\') : ($desc ? \'html\' : \'\'))}\n\n{* фото: своё → родителя → нет *}\n{set $own = $_modx->getResource($r.id, [\'includeTVs\' => \'img_banner_main\', \'processTVs\' => 1, \'tvPrefix\' => \'\', \'select\' => \'id,parent\'])}\n{set $photo = $own.img_banner_main | trim}\n{if !$photo && $r.parent && !$hub}\n{set $par = $_modx->getResource($r.parent, [\'includeTVs\' => \'img_banner_main\', \'processTVs\' => 1, \'tvPrefix\' => \'\', \'select\' => \'id\'])}\n{set $photo = $par.img_banner_main | trim}\n{/if}\n{set $alt = $t | striptags}\n{set $simple = $hub && !$photo}\n\n{set $ico = [\n    \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 32c2-11 9-19 24-24-1 15-9 22-20 24-1.3.2-2.7.2-4 0z\"/><path d=\"M8 32 22 18\"/><path d=\"M15 25h7M19 21v-5\"/></svg>\',\n    \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 4 33 9v9c0 9-5.6 15.4-13 18-7.4-2.6-13-9-13-18V9z\"/><path d=\"m14 20 4.5 4.5L27 16\"/></svg>\',\n    \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"6\" y=\"9\" width=\"28\" height=\"25\" rx=\"3\"/><path d=\"M6 16h28M13 5v7M27 5v7\"/><path d=\"M13 22h.01M20 22h.01M27 22h.01M13 28h.01M20 28h.01M27 28h.01\" stroke-width=\"2.6\"/></svg>\'\n]}\n{* удаление тату: безопасность, время сеанса, кожа без следов, любой тип тату *}\n{if $tz}\n{set $ico = [\n    $ico[1],\n    \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"20\" cy=\"21\" r=\"14\"/><path d=\"M20 12v9l6 4\"/><path d=\"M16 4h8\"/></svg>\',\n    $ico[0],\n    \'<svg viewBox=\"0 0 40 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 4v8M20 28v8M4 20h8M28 20h8M8.7 8.7l5.6 5.6M25.7 25.7l5.6 5.6M31.3 8.7l-5.6 5.6M14.3 25.7l-5.6 5.6\"/><circle cx=\"20\" cy=\"20\" r=\"3\"/></svg>\'\n]}\n{/if}\n{set $arr = \'<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-shero{if !$photo} lb-shero--art{/if}{if $hub} lb-shero--hub{/if}{if $simple} lb-shero--simple{/if}\" id=\"lb-shero\">\n    <div class=\"lb-shero__bg\" aria-hidden=\"true\"></div>\n\n    {if !$simple}\n    <div class=\"lb-shero__media\">\n        <div class=\"lb-shero__frame\" aria-hidden=\"true\"></div>\n        <div class=\"lb-shero__photo\">\n            {if $photo}\n            <img src=\"/{$photo}\" alt=\"{$alt}\" loading=\"eager\" fetchpriority=\"high\" decoding=\"async\">\n            {/if}\n        </div>\n    </div>\n    {/if}\n\n    <div class=\"lb-shero__inner\">\n        <div class=\"lb-shero__content\">\n            <h1 class=\"lb-shero__title\"><span class=\"lb-shero__t1\">{$first}</span>{if $rest} <span class=\"lb-shero__t2\">{$rest}</span>{/if}</h1>\n            {if $hub}\n            {* длинный текст (у мастеров — биография, 1–2 тыс. знаков) в баннер не помещается — его выводит блок под баннером (lb-pgallery) *}\n            {set $hdesc = $r[\'description-banner-inerial\'] | trim}\n            {if $hdesc && ($hdesc | striptags | trim | length) <= 300}<div class=\"lb-shero__desc\">{$hdesc}</div>{/if}\n            {elseif $tz}{if $r[\'sub-title-2-banner-study\'] | trim}<p class=\"lb-shero__sub\">{$r[\'sub-title-2-banner-study\']}</p>{/if}\n            {elseif $r[\'sub-title-banner\'] | trim}<p class=\"lb-shero__sub\">{$r[\'sub-title-banner\']}</p>{/if}\n\n            {if $mode == \'cols\'}\n            {set $nic = $ico | length}\n            <ul class=\"lb-shero__feats{($n > 3) ? \' lb-shero__feats--4\' : \'\'}\">\n                {foreach $items as $i => $it}\n                <li class=\"lb-shero__feat\"><span class=\"lb-shero__ico\">{$ico[$i % $nic]}</span><span class=\"lb-shero__feat-t\">{$it}</span></li>\n                {/foreach}\n            </ul>\n            {elseif $mode == \'list\'}\n            <ul class=\"lb-shero__list\">\n                {foreach $items as $it}\n                <li class=\"lb-shero__li\">{$it}</li>\n                {/foreach}\n            </ul>\n            {elseif $mode == \'html\'}\n            <div class=\"lb-shero__desc\">{$desc}</div>\n            {/if}\n\n            {if !$hub}\n            <div class=\"lb-shero__btns\">\n                <a class=\"lb-btn lb-btn--solid js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}{$arr}</a>\n                <a class=\"lb-btn lb-btn--ghost\" href=\"#conract\">{\'lbar.buttons.banner.consultation\' | lexicon}{$arr}</a>\n            </div>\n            {/if}\n        </div>\n\n        <nav class=\"lb-crumbs\" aria-label=\"{\'lbar.rd.aria.crumbs\' | lexicon}\">\n            {$_modx->runSnippet(\'!pdoCrumbs\', [\n                \'showHome\' => 1,\n                \'showAtHome\' => 0,\n                \'exclude\' => $hub ? \'\' : \'80,60\',\n                \'tplWrapper\' => \'@INLINE <ol class=\"lb-crumbs__list\" itemscope itemtype=\"http://schema.org/BreadcrumbList\">[[+output]]</ol>\',\n                \'tplHome\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link lb-crumbs__link--home\" href=\"[[+link]]\" itemprop=\"item\"><svg viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.2 10 3l7 6.2\"/><path d=\"M5 8v9h4v-5h2v5h4V8\"/></svg><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                \'tpl\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link\" href=\"[[+link]]\" itemprop=\"item\"><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                \'tplCurrent\' => \'@INLINE <li class=\"lb-crumbs__item lb-crumbs__item--current\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><span itemprop=\"name\">[[+menutitle]]</span><div itemprop=\"item\" content=\"[[++site_url]][[+link]]\"></div><meta itemprop=\"position\" content=\"[[+idx]]\" /></li>\',\n            ])}\n        </nav>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-shero.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (294,1,0,'lb.blogHref','Редизайн: URL статьи для карточки lb-blog по значению TV link-st-N (id или путь), только опубликованные',0,128,0,'{* Ссылка карточки статьи (lb-blog): значение TV link-st-N → URL опубликованной статьи текущего контекста или пусто.\n   В TV можно указать id ресурса или путь (/alias, /ru/alias, полный URL). Удалённые и снятые с публикации — без ссылки. *}\n{set $v = $v | trim}\n{set $id = 0}\n{if $v | ematch : \'/^\\d+$/\'}\n{set $id = $v}\n{elseif $v}\n{set $uri = $v | ereplace : \'~^(https?://[^/]+)?/+~\' : \'\' | ereplace : \'~[?#].*$~\' : \'\' | ereplace : \'~^ru/~\' : \'\'}\n{set $id = $_modx->findResource($uri)}\n{/if}\n{if $id && $_modx->getResource($id, [\'select\' => \'id\'])}{$_modx->makeUrl($id)}{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.blogHref.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (296,1,0,'lb.accent','Редизайн: заголовок с курсивом после тире / двоеточия',0,128,0,'{* Заголовок с акцентом для страниц услуг: часть после первого « – » / « — » / «: » — курсивом (<em>), как в новом дизайне.\n   Вход: t — текст заголовка (из TV, не меняется). Нет разделителя — выводится как есть. Используется блоками,\n   когда заголовок не совпал с разметкой из лексикона (то есть не на главной). *}\n{set $t = $t | trim}\n{* с HTML-тегами (<br> в RU-TV, <h2>) — как есть, чтобы не разорвать разметку *}\n{set $head = $t | ereplace : \'/^(.+?(?:\\s[–—-]|:))\\s+(\\S.*)$/su\' : \'$1\'}\n{if $head != $t && !($t | ematch : \'/</\')}{$head} <em>{$t | ereplace : \'/^(.+?(?:\\s[–—-]|:))\\s+(\\S.*)$/su\' : \'$2\'}</em>{else}{$t}{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.accent.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (297,1,0,'lb.subserviceCard','Редизайн: карточка подуслуги (tpl pdoResources)',0,128,0,'{* Карточка подуслуги на странице услуги (tpl pdoResources в lb-subservices) — вид карточки услуг главной (lb-scard).\n   Данные — как в старом tpl.category.main: фото TV im-category (alt — alt-im-category), название TV title-bl2, текст TV intro-text-bl2. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $title = $_pls[\'tv.title-bl2\'] ?: $menutitle ?: $pagetitle}\n{* у EN путь картинки TV (источник файлов) приходит с base_url контекста «/en/» — файл лежит от корня *}\n{set $img = $_pls[\'tv.im-category\'] | ereplace : \'~^/en/(?=(?:images|assets)/)~\' : \'/\'}\n<article class=\"lb-scard\">\n    <a class=\"lb-scard__img\" href=\"{$uri}\" aria-label=\"{$title | escape}\">\n        {if $img}<img src=\"{$img}\" alt=\"{($_pls[\'tv.alt-im-category\'] ?: $title) | escape}\" width=\"420\" height=\"400\" loading=\"lazy\" decoding=\"async\">{/if}\n    </a>\n    <div class=\"lb-scard__body\">\n        <div class=\"lb-scard__num\" aria-hidden=\"true\">{$idx < 10 ? \'0\' : \'\'}{$idx}</div>\n        <div class=\"lb-scard__title\"><a href=\"{$uri}\">{$title}</a></div>\n        <div class=\"lb-scard__text\">{$_pls[\'tv.intro-text-bl2\']}</div>\n        <a class=\"lb-btn lb-btn--ghost lb-btn--sm lb-scard__btn\" href=\"{$uri}\">{\'lbar.buttons.category.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.subserviceCard.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (298,1,0,'lb-subservices','Редизайн: подуслуги на странице услуги (дочерние ресурсы)',0,128,0,'{* Блок «Подуслуги» на странице услуги (шаблон «Категория») — вместо bl2-category-inerial: дочерние ресурсы (как было:\n   pdoResources, parents = текущий, до 12, по menuindex; при равном menuindex — по id, шаг 65). Выводится, только если дети есть. H2 — TV main-title-bl2,\n   подзаголовок — TV sub-title-bl2 (как в tpl.moreWrap-category.main). Вид — блок «Услуги» главной (lb-scard).\n   Общая страница «Услуги» (шаблон «Услуги — общая», вместо bl2-category-inerial-2; режим hub): все опубликованные услуги-потомки\n   (шаблоны «Категория» 8 и «Категория NEW» 19, по menuindex), карточка lb.hubCard; H2 и подзаголовок — те же TV.\n   Шаг 54: и страницы шаблона «Удаление тату» (Redesign; id шаблона на серверах разный — по имени, через JOIN modTemplate). *}\n{set $hub = $_modx->resource.template != 8}\n{if $hub}\n{set $list = $_modx->runSnippet(\'pdoResources\', [\n    \'parents\' => $_modx->resource.id,\n    \'depth\' => 0,\n    \'limit\' => 0,\n    \'leftJoin\' => [\'Tpl\' => [\'class\' => \'modTemplate\', \'on\' => \'Tpl.id = modResource.template\']],\n    \'where\' => \'[{\"template:IN\":[8,19],\"OR:Tpl.templatename:=\":\"Удаление тату\"},{\"class_key:!=\":\"modWebLink\"}]\',\n    \'tpl\' => \'lb.hubCard\',\n    \'sortby\' => [\'menuindex\' => \'ASC\', \'id\' => \'ASC\'],\n    \'includeTVs\' => \'img_banner_main,im-category,intro-text-bl2,sub-title-banner\',\n    \'processTVs\' => \'img_banner_main,im-category\'\n])}\n{else}\n{set $list = $_modx->runSnippet(\'pdoResources\', [\n    \'parents\' => $_modx->resource.id,\n    \'limit\' => 12,\n    \'where\' => [\'class_key:!=\' => \'modWebLink\'],\n    \'tpl\' => \'lb.subserviceCard\',\n    \'sortby\' => [\'menuindex\' => \'ASC\', \'id\' => \'ASC\'],\n    \'includeTVs\' => \'im-category,alt-im-category,intro-text-bl2,title-bl2\'\n])}\n{/if}\n{if $list | trim}\n{set $title = $_modx->resource[\'main-title-bl2\'] | trim}\n<section class=\"lb-services lb-services--sub{$hub ? \' lb-services--hub\' : \'\'}\" id=\"lb-services\">\n    <div class=\"lb-services__bg\" aria-hidden=\"true\">\n        <img src=\"/assets/templates/redesign/img/services-bg.webp?v=2\" srcset=\"/assets/templates/redesign/img/services-bg-1440.webp?v=2 1440w, /assets/templates/redesign/img/services-bg.webp?v=2 2166w\" sizes=\"100vw\" width=\"2166\" height=\"1218\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n    </div>\n\n    <div class=\"lb-services__intro\">\n        {if $title}\n        <h2 class=\"lb-services__title\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $title])}</h2>\n        {/if}\n        {if $_modx->resource[\'sub-title-bl2\']}\n        <div class=\"lb-services__text\">{$_modx->resource[\'sub-title-bl2\']}</div>\n        {/if}\n    </div>\n\n    <div class=\"lb-services__list\">\n        {$list}\n    </div>\n</section>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-subservices.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (307,1,0,'lb.ptable','Редизайн: таблица цен (общая для блока «Цены» и страницы «Цены»)',0,128,0,'{* Таблица цен (div + ARIA-роли: старый custom.js клонирует все <table> и прячет их на мобильном) — общая для блока «Цены»\n   (lb-price: главная, страницы услуг) и страницы «Цены» (lb-prices). Параметры:\n   rows — JSON MIGX-таблицы (col-1 — процедура, часть в скобках — второй строкой; col-2…col-4 — по виду таблицы);\n   mode — вид: notop (длительность col-2 + цена col-4, пусто — col-3), full (длительность + TOP Master col-3 + TOP Trainer col-4),\n   three (цена col-2 «за сеанс» + col-3 «8 сеансов»), two (цена col-3), dur3 (длительность + цена col-3), two2 (цена col-2);\n   label — подпись таблицы (aria-label); uid — суффикс id градиента иконки (несколько таблиц на странице).\n   Подписи колонок — прежние ключи lbar.price.table.title*; hl1 / hl2 / hl3 — свои подписи колонок «процедура» / 1-я / 2-я цена\n   (удаление тату, шаг 54: из шапки HTML-таблицы TV). Иконки — по ключевым словам названия. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $rows = ($rows ?: \'[]\') | fromJSON}\n{set $uid = $uid ?: \'1\'}\n{if $mode == \'two\'}\n    {set $pcols = [[\'col-3\', \'lbar.price.table.title5\']]}{set $hasDur = false}{set $lay = \'two\'}\n{elseif $mode == \'two2\'}\n    {set $pcols = [[\'col-2\', \'lbar.price.table.title5\']]}{set $hasDur = false}{set $lay = \'two\'}\n{elseif $mode == \'three\'}\n    {set $pcols = [[\'col-2\', $hl2 ?: \'lbar.price.table.title6\'], [\'col-3\', $hl3 ?: \'lbar.price.table.title7\']]}{set $hasDur = false}{set $lay = \'three\'}\n{elseif $mode == \'full\'}\n    {set $pcols = [[\'col-3\', \'lbar.price.table.title3\'], [\'col-4\', \'lbar.price.table.title4\']]}{set $hasDur = true}{set $lay = \'full\'}\n{elseif $mode == \'dur3\'}\n    {set $pcols = [[\'col-3\', \'lbar.price.table.title5\']]}{set $hasDur = true}{set $lay = \'notop\'}\n{else}\n    {set $mode = \'notop\'}{set $pcols = [[\'col-4\', \'lbar.price.table.title5\']]}{set $hasDur = true}{set $lay = \'notop\'}\n{/if}\n{set $ic = [\n    \'brow\' => \'<svg viewBox=\"0 0 80 40\"><defs><linearGradient id=\"lb-pi-brow-\' ~ $uid ~ \'\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#b98a6a\" stop-opacity=\".25\"/><stop offset=\".35\" stop-color=\"#8d5a3c\"/><stop offset=\"1\" stop-color=\"#7a4528\"/></linearGradient></defs><path fill=\"url(#lb-pi-brow-\' ~ $uid ~ \')\" d=\"M6 27.5c8.5-6.6 19.6-11 31.7-12.2 11.6-1.1 22.6.6 31.9 5.7 2.6 1.4 4.6 3.1 6 5.2.5.8-.4 1.7-1.2 1.2-8.2-5.3-18.1-7.6-28.7-7.1-13.1.6-25.4 4.7-37 9.5-1.8.7-3.9-.9-2.7-2.3z\"/><path fill=\"none\" stroke=\"#a7795a\" stroke-opacity=\".5\" stroke-width=\".9\" stroke-linecap=\"round\" d=\"M10 27.2 12.6 22M15 25.6l2.4-5.6M20 23.8l2-5.6M25 22.3l1.6-5.6\"/></svg>\',\n    \'eye\' => \'<svg viewBox=\"0 0 80 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 21c7.9-8.6 19-13 34-13s26.1 4.4 34 13c-7.9 8.3-19 12.5-34 12.5S13.9 29.3 6 21z\"/><circle cx=\"40\" cy=\"20.5\" r=\"8.4\"/><circle cx=\"40\" cy=\"20.5\" r=\"3.6\" fill=\"currentColor\" stroke=\"none\"/><path d=\"M57 11.6 60 6.8M63 14.2l4-4.2M68 17.6l4.6-3M3.5 22.4 6 21l3.4 1.1\"/><path d=\"M74 21c1.7.6 3.2 1.7 4.4 3.2\" stroke-width=\"1.3\"/></svg>\',\n    \'lashes\' => \'<svg viewBox=\"0 0 80 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M8 15.5c8.6 7.6 19.4 11.4 32 11.4s23.4-3.8 32-11.4\"/><path d=\"M14.5 21.5 11 26.5M21 25l-2.6 5.4M28.2 27.6l-1.5 5.7M36 28.8v5.8M44 28.8v5.8M51.8 27.6l1.5 5.7M59 25l2.6 5.4M65.5 21.5l3.5 5\"/></svg>\',\n    \'lips\' => \'<svg viewBox=\"0 0 80 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><path d=\"M5 20.5c6.6-6.8 13.2-11.6 20-11.6 5.6 0 10 2.6 15 2.6s9.4-2.6 15-2.6c6.8 0 13.4 4.8 20 11.6-8.2 7.8-20 12-35 12s-26.8-4.2-35-12z\"/><path d=\"M5 20.5c11 1.6 22.6 2.4 35 .2 12.4 2.2 24 1.4 35-.2\"/></svg>\',\n    \'retouch\' => \'<svg viewBox=\"0 0 80 40\" fill=\"currentColor\"><circle cx=\"40\" cy=\"6\" r=\"1.5\"/><circle cx=\"40\" cy=\"34\" r=\"1.5\"/><circle cx=\"26\" cy=\"20\" r=\"1.5\"/><circle cx=\"54\" cy=\"20\" r=\"1.5\"/><circle cx=\"30.5\" cy=\"10.5\" r=\"1.3\"/><circle cx=\"49.5\" cy=\"10.5\" r=\"1.3\"/><circle cx=\"30.5\" cy=\"29.5\" r=\"1.3\"/><circle cx=\"49.5\" cy=\"29.5\" r=\"1.3\"/><circle cx=\"40\" cy=\"13\" r=\"1.1\"/><circle cx=\"40\" cy=\"27\" r=\"1.1\"/><circle cx=\"33\" cy=\"20\" r=\"1.1\"/><circle cx=\"47\" cy=\"20\" r=\"1.1\"/><circle cx=\"35\" cy=\"15\" r=\".9\"/><circle cx=\"45\" cy=\"25\" r=\".9\"/><circle cx=\"45\" cy=\"15\" r=\".9\"/><circle cx=\"35\" cy=\"25\" r=\".9\"/><circle cx=\"20\" cy=\"13\" r=\"1\"/><circle cx=\"60\" cy=\"27\" r=\"1\"/><circle cx=\"21\" cy=\"28\" r=\".9\"/><circle cx=\"59\" cy=\"12\" r=\".9\"/></svg>\',\n    \'laser\' => \'<svg viewBox=\"0 0 80 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M40 3v10M40 27v10M23 20h10M47 20h10M28 8.5l7 7M45 24.5l7 7M52 8.5l-7 7M35 24.5l-7 7\"/><path d=\"M38 17.5 40 20l2.5-2\" stroke-width=\"1.3\"/></svg>\',\n    \'drop\' => \'<svg viewBox=\"0 0 80 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"><path d=\"M40 5c5.6 7.2 9.5 13 9.5 18.2a9.5 9.5 0 0 1-19 0C30.5 18 34.4 12.2 40 5z\"/></svg>\'\n]}\n{* иконка — по первому совпадению ключевого слова в названии процедуры (RO / RU) *}\n{set $keys = [\n    [\'/sprânc|spranc|бров/iu\', \'brow\'],\n    [\'/buze|губ/iu\', \'lips\'],\n    [\'/pleoap|intergen|межреснич|ресниц/iu\', \'lashes\'],\n    [\'/ochi|săgeț|sageti|eyeliner|глаз|век/iu\', \'eye\'],\n    [\'/îndepărt|indepart|laser|удален|лазер/iu\', \'laser\'],\n    [\'/retu|corect|remover|коррекц|ремувер/iu\', \'retouch\']\n]}\n{set $clock = \'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9.6\"/><path d=\"M12 6.8V12l3.6 2.4\"/></svg>\'}\n{if $rows}\n<div class=\"lb-ptable lb-ptable--{$lay}\" role=\"table\" aria-label=\"{$label | striptags | escape}\">\n    <div class=\"lb-ptable__head\" role=\"row\">\n        <div class=\"lb-ptable__h lb-ptable__h--name\" role=\"columnheader\"><span>{($hl1 ?: \'lbar.price.table.title1\') | lexicon}</span><i class=\"lb-ptable__orn\" aria-hidden=\"true\"><svg viewBox=\"0 0 20 20\"><path fill=\"currentColor\" d=\"M10 0c.5 5.3 4.2 9.3 10 10-5.8.7-9.5 4.7-10 10-.5-5.3-4.2-9.3-10-10C5.8 9.3 9.5 5.3 10 0z\"/></svg></i></div>\n        {if $hasDur}<div class=\"lb-ptable__h lb-ptable__h--dur\" role=\"columnheader\">{\'lbar.price.table.title2\' | lexicon}</div>{/if}\n        {foreach $pcols as $pc}\n        <div class=\"lb-ptable__h lb-ptable__h--price\" role=\"columnheader\">{$pc[1] | lexicon}</div>\n        {/foreach}\n    </div>\n    <div class=\"lb-ptable__body\" role=\"rowgroup\">\n        {foreach $rows as $row}\n        {set $full = $row[\'col-1\'] | trim}\n        {set $name = $full | ereplace : \'/\\s*\\([^()]*\\)\\s*$/u\' : \'\'}\n        {set $sub = ($name != $full) ? ($full | ereplace : \'/^.*?(\\([^()]*\\))\\s*$/u\' : \'$1\') : \'\'}\n        {set $price = ($row[\'col-4\'] | trim) ?: ($row[\'col-3\'] | trim)}\n        {set $icon = \'drop\'}\n        {foreach $keys as $kw}\n        {if $full | ematch : $kw[0]}{set $icon = $kw[1]}{break}{/if}\n        {/foreach}\n        <div class=\"lb-ptable__row\" role=\"row\">\n            <div class=\"lb-ptable__name\" role=\"cell\">\n                <span class=\"lb-ptable__ic lb-ptable__ic--{$icon}\" aria-hidden=\"true\">{$ic[$icon]}</span>\n                <span class=\"lb-ptable__proc\"><b>{$name}</b>{if $sub}<span class=\"lb-ptable__sub\">{$sub}</span>{/if}</span>\n            </div>\n            {if $hasDur}<div class=\"lb-ptable__dur\" role=\"cell\">{if $row[\'col-2\']}<span class=\"lb-ptable__clock\" aria-hidden=\"true\">{$clock}</span>{$row[\'col-2\']}{/if}</div>{/if}\n            {foreach $pcols as $pc}\n            {set $pv = ($mode == \'notop\') ? $price : ($row[$pc[0]] | trim)}\n            <div class=\"lb-ptable__price{($pv | length) > 12 ? \' lb-ptable__price--long\' : \'\'}\" role=\"cell\"{if ($pcols | length) > 1} data-label=\"{$pc[1] | lexicon | striptags | escape}\"{/if}>{$pv | ereplace : \'/(\\d)(?=(\\d{3})+(?!\\d))/u\' : \'$1&nbsp;\'}</div>\n            {/foreach}\n        </div>\n        {/foreach}\n    </div>\n</div>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.ptable.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (299,1,0,'lb.courseCard','Редизайн: карточка курса (tpl pdoResources)',0,128,0,'{* Карточка курса (tpl pdoResources в lb-courses). Фото — TV im-category (alt — alt-im-category), название — TV title-bl2\n   (как в старом tpl.category.study), текст — TV intro-text-bl2 или подзаголовок баннера курса sub-title-2-banner-study,\n   пункты — text-1..4-banner-study (преимущества из баннера курса). Ссылка — страница курса. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $title = ($_pls[\'tv.title-bl2\'] | trim) ?: ($menutitle ?: $pagetitle)}\n{set $src = $_pls[\'tv.im-category\'] | trim}\n{if $src && !($src | ematch : \'~^(/|https?:)~\')}{set $src = \'/\' ~ $src}{/if}\n{set $text = ($_pls[\'tv.intro-text-bl2\'] | trim) ?: ($_pls[\'tv.sub-title-2-banner-study\'] | trim)}\n<article class=\"lb-course\">\n    <a class=\"lb-course__img\" href=\"{$uri}\" aria-label=\"{$title | escape}\">\n        {if $src}<img src=\"{$src | replace : \' \' : \'%20\'}\" alt=\"{($_pls[\'tv.alt-im-category\'] ?: $title) | escape}\" width=\"760\" height=\"560\" loading=\"lazy\" decoding=\"async\">{/if}\n    </a>\n    <div class=\"lb-course__body\">\n        <div class=\"lb-course__num\" aria-hidden=\"true\">{$idx < 10 ? \'0\' : \'\'}{$idx}</div>\n        <div class=\"lb-course__title\"><a href=\"{$uri}\">{$title}</a></div>\n        {if $text}<p class=\"lb-course__text\">{$text}</p>{/if}\n        <ul class=\"lb-course__list\">\n            {foreach 1..4 as $i}\n            {set $it = $_pls[\'tv.text-\' ~ $i ~ \'-banner-study\'] | trim}\n            {if $it}<li class=\"lb-course__li\">{$it}</li>{/if}\n            {/foreach}\n        </ul>\n        <a class=\"lb-btn lb-btn--solid lb-course__btn\" href=\"{$uri}\">{\'lbar.buttons.category.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.courseCard.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (300,1,0,'lb-courses','Редизайн: курсы на общей странице «Обучение»',0,128,0,'{* Блок «Курсы» на общей странице «Обучение» (шаблон «Внутренняя - Обучение», id 21) — вместо bl2-category-study.\n   Список — как было: pdoResources, parents = текущий, resources = TV id-bl2, по menuindex (при равном — по id, шаг 65). Карточка — lb.courseCard.\n   Заголовка H2 у старого блока не было — и здесь нет (надзаголовок убран вместе со всеми eyebrow), структура заголовков страницы та же. *}\n{set $list = $_modx->runSnippet(\'pdoResources\', [\n    \'parents\' => $_modx->resource.id,\n    \'resources\' => $_modx->resource[\'id-bl2\'] | trim,\n    \'limit\' => 12,\n    \'tpl\' => \'lb.courseCard\',\n    \'sortby\' => [\'menuindex\' => \'ASC\', \'id\' => \'ASC\'],\n    \'includeTVs\' => \'im-category,alt-im-category,title-bl2,intro-text-bl2,sub-title-2-banner-study,text-1-banner-study,text-2-banner-study,text-3-banner-study,text-4-banner-study\',\n    \'processTVs\' => \'im-category\'\n])}\n{if $list | trim}\n<section class=\"lb-courses\" id=\"lb-courses\">\n    <div class=\"lb-courses__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-courses__inner\">\n        <div class=\"lb-courses__list\">\n            {$list}\n        </div>\n    </div>\n</section>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-courses.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (301,1,0,'lb.hubCard','Редизайн: карточка услуги на общей странице «Услуги» (tpl pdoResources)',0,128,0,'{* Карточка услуги на общей странице «Услуги» (tpl pdoResources в lb-subservices, режим hub) — вид lb-scard.\n   Название — menutitle (как в меню; TV title-bl2 у многих услуг заполнен копией чужого названия).\n   Фото: у трёх услуг главной — фото из макета (как в lb.serviceCard), иначе TV img_banner_main → TV im-category → первое фото галереи (у EN-ресурса — галерея RO-двойника, BabelTranslation).\n   Текст: TV intro-text-bl2 → TV sub-title-banner (на RO-странице текст на кириллице пропускается — в базе есть RU-текст у RO-ресурса). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $map = [2 => \'brows\', 303 => \'brows\', 1002 => \'brows\', 162 => \'eyeliner\', 317 => \'eyeliner\', 1162 => \'eyeliner\', 167 => \'lips\', 319 => \'lips\', 1167 => \'lips\']}\n{set $title = $menutitle ?: $pagetitle}\n{set $src = $map[$id] ? (\'/assets/templates/redesign/img/service-\' ~ $map[$id] ~ \'.webp\') : (($_pls[\'tv.img_banner_main\'] | trim) ?: ($_pls[\'tv.im-category\'] | trim))}\n{if !$src}\n{set $gid = $id}\n{if $context_key == \'en\'}{set $ro = $_modx->runSnippet(\'BabelTranslation\', [\'resourceId\' => $id, \'contextKey\' => \'web\']) | trim}{if $ro}{set $gid = $ro}{/if}{/if}\n{set $src = $_modx->runSnippet(\'ms2Gallery\', [\'resources\' => $gid, \'limit\' => 1, \'frontend_css\' => \'\', \'frontend_js\' => \'\', \'tpl\' => \'@INLINE {foreach $files as $f}{$f.medium}{/foreach}\']) | trim}\n{/if}\n{if $src && !($src | ematch : \'~^(/|https?:)~\')}{set $src = \'/\' ~ $src}{/if}\n{set $text = $_pls[\'tv.intro-text-bl2\'] | trim}\n{if !$text}\n{set $text = $_pls[\'tv.sub-title-banner\'] | trim}\n{if $context_key == \'web\' && ($text | ematch : \'~\\p{Cyrillic}~u\')}{set $text = \'\'}{/if}\n{/if}\n<article class=\"lb-scard\">\n    <a class=\"lb-scard__img\" href=\"{$uri}\" aria-label=\"{$title | escape}\">\n        {if $src}<img src=\"{$src | replace : \' \' : \'%20\'}\" alt=\"{$title | escape}\" width=\"420\" height=\"400\" loading=\"lazy\" decoding=\"async\">{/if}\n    </a>\n    <div class=\"lb-scard__body\">\n        <div class=\"lb-scard__num\" aria-hidden=\"true\">{$idx < 10 ? \'0\' : \'\'}{$idx}</div>\n        <div class=\"lb-scard__title\"><a href=\"{$uri}\">{$title}</a></div>\n        {if $text}<div class=\"lb-scard__text\">{$text}</div>{/if}\n        <a class=\"lb-btn lb-btn--ghost lb-btn--sm lb-scard__btn\" href=\"{$uri}\">{\'lbar.buttons.category.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n    </div>\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.hubCard.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (302,1,0,'lb.galleryPage','Редизайн: tpl ms2Gallery для галереи страницы портфолио',0,128,0,'{* Галерея внутренней страницы портфолио (tpl ms2Gallery в lb-pgallery): сетка как у галереи главной (lb-gallery),\n   первые 16 фото видны, остальные — по кнопке порциями (redesign.js). Ссылки на полные фото с data-fancybox — как раньше. *}\n{if $files?}\n<div class=\"lb-gallery lb-gallery--page\" id=\"lb-gallery\">\n    {foreach $files as $key => $file}\n    <a class=\"lb-gallery__item{$key > 15 ? \' lb-gallery__item--more\' : \'\'}\" href=\"{$file[\'url\']}\" data-fancybox=\"gallery-{$file[\'resource_id\']}\" aria-label=\"{$file[\'description\'] ?: $file[\'name\']}\">\n        <img src=\"{$file[\'medium\']}\" srcset=\"{$file[\'medium\']} 400w, {$file[\'url\']} 1200w\" sizes=\"(max-width: 600px) 50vw, (max-width: 1024px) 33vw, 22vw\" alt=\"{$file[\'description\']}\" width=\"400\" height=\"400\" loading=\"lazy\" decoding=\"async\">\n        <span class=\"lb-gallery__zoom\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m15.5 15.5 5 5M10.5 7.5v6M7.5 10.5h6\"/></svg></span>\n    </a>\n    {/foreach}\n</div>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb.galleryPage.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (303,1,0,'lb-pfhub','Редизайн: портфолио — карточки мастеров и разделов',0,128,0,'{* Страница «Портфолио» (шаблон «Портфолио», id 10) — карточки мастеров и разделов (вместо сеток в banner-interial-portfolio).\n   Данные — прежние TV ресурса: мастера — img-master-N / alt-master-N / master-N / link-master-N (N = 1…3),\n   разделы — img-p-N / alt-p-N / title-p-N / link-p-N (N = 1…5). Карточка без ссылки не выводится (в старом блоке 5-я была пустой).\n   Заголовков H2 у старого блока не было — здесь тоже (надзаголовки «Maeștrii noștri» / «Lucrări pe tehnici» убраны вместе со всеми eyebrow). Фото — исходные файлы\n   (они 390×390, как и резал старый pthumb; карточки — квадратные фото, без лишнего пережатия). *}\n{set $r = $_modx->resource}\n{set $tvs = $_modx->getResource($r.id, [\'includeTVs\' => \'img-master-1,img-master-2,img-master-3,img-p-1,img-p-2,img-p-3,img-p-4,img-p-5\', \'processTVs\' => 1, \'tvPrefix\' => \'\', \'select\' => \'id\'])}\n{set $arr = \'<svg class=\"lb-pfcard__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-pfhub\" id=\"lb-pfhub\">\n    <div class=\"lb-pfhub__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-pfhub__inner\">\n        <div class=\"lb-pfhub__masters\">\n            {foreach 1..3 as $i}\n            {set $link = $r[\'link-master-\' ~ $i] | trim}\n            {if $link}\n            {set $img = $tvs[\'img-master-\' ~ $i] | trim}\n            {if $img && !($img | ematch : \'~^(/|https?:)~\')}{set $img = \'/\' ~ $img}{/if}\n            <a class=\"lb-pfcard lb-pfcard--master\" href=\"{$link}\">\n                <span class=\"lb-pfcard__img\">{if $img}<img src=\"{$img | replace : \' \' : \'%20\'}\" alt=\"{($r[\'alt-master-\' ~ $i] ?: $r[\'master-\' ~ $i]) | striptags | escape}\" width=\"390\" height=\"390\" loading=\"lazy\" decoding=\"async\">{/if}</span>\n                <span class=\"lb-pfcard__body\">\n                    <span class=\"lb-pfcard__title\">{$r[\'master-\' ~ $i]}</span>\n                    <span class=\"lb-pfcard__more\">{\'lbar.rd.implica.portfolio\' | lexicon}{$arr}</span>\n                </span>\n            </a>\n            {/if}\n            {/foreach}\n        </div>\n\n        <div class=\"lb-pfhub__cats\">\n            {foreach 1..5 as $i}\n            {set $link = $r[\'link-p-\' ~ $i] | trim}\n            {if $link}\n            {set $img = $tvs[\'img-p-\' ~ $i] | trim}\n            {if $img && !($img | ematch : \'~^(/|https?:)~\')}{set $img = \'/\' ~ $img}{/if}\n            <a class=\"lb-pfcard lb-pfcard--cat\" href=\"{$link}\">\n                <span class=\"lb-pfcard__img\">{if $img}<img src=\"{$img | replace : \' \' : \'%20\'}\" alt=\"{($r[\'alt-p-\' ~ $i] ?: $r[\'title-p-\' ~ $i]) | striptags | escape}\" width=\"390\" height=\"390\" loading=\"lazy\" decoding=\"async\">{/if}</span>\n                <span class=\"lb-pfcard__body\">\n                    <span class=\"lb-pfcard__num\" aria-hidden=\"true\">0{$i}</span>\n                    <span class=\"lb-pfcard__title\">{$r[\'title-p-\' ~ $i]}</span>\n                    <span class=\"lb-pfcard__more\">{\'lbar.rd.pf.open\' | lexicon}{$arr}</span>\n                </span>\n            </a>\n            {/if}\n            {/foreach}\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-pfhub.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (306,1,0,'lb-prices','Редизайн: страница «Цены» — таблицы table-price-N',0,128,0,'{* Страница «Цены» (шаблон «Цены», id 14) — вместо таблиц в banner-interial-price.\n   Текст над таблицами — TV description-banner-inerial (короткий — до 300 знаков — показывает баннер lb-shero, здесь не дублируется).\n   Таблицы — прежние TV table-price-N (N = 1…6), над каждой H2 — TV title-price-N (как раньше), под ним — TV text-price-N.\n   Колонки — как в старом чанке: 1–3 — длительность col-2 + цена col-4 (пусто — col-3), 4 — длительность + цена col-3, 5–6 — цена col-2.\n   Таблица — общий чанк lb.ptable (вид блока «Цены» главной). Кнопка — запись (#bl8-form). *}\n{set $r = $_modx->resource}\n{set $intro = $r[\'description-banner-inerial\'] | trim}\n{if ($intro | striptags | trim | length) <= 300}{set $intro = \'\'}{/if}\n{set $modes = [1 => \'notop\', 2 => \'notop\', 3 => \'notop\', 4 => \'dur3\', 5 => \'two2\', 6 => \'two2\']}\n{set $arr = \'<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-prices\" id=\"lb-prices\">\n    <div class=\"lb-prices__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-prices__inner\">\n        {if $intro}\n        <div class=\"lb-prices__intro\">{$intro}</div>\n        {/if}\n        {foreach 1..6 as $i}\n        {set $rows = $r[\'table-price-\' ~ $i] | trim}\n        {if $rows && $rows != \'[]\'}\n        {set $t = $r[\'title-price-\' ~ $i] | trim}\n        <div class=\"lb-prices__group\">\n            <div class=\"lb-prices__head\">\n                <span class=\"lb-prices__num\" aria-hidden=\"true\">0{$i}</span>\n                {if $t}<h2 class=\"lb-prices__title\">{$_modx->getChunk(\'lb.accent\', [\'t\' => $t])}</h2>{/if}\n                {if $r[\'text-price-\' ~ $i] | trim}<div class=\"lb-prices__text\">{$r[\'text-price-\' ~ $i]}</div>{/if}\n                <a class=\"lb-btn lb-btn--solid lb-prices__cta js-lb-book\" href=\"#bl8-form\">{\'lbar.prices.button.book\' | lexicon}{$arr}</a>\n            </div>\n            <div class=\"lb-price__card lb-prices__card\">\n                {$_modx->getChunk(\'lb.ptable\', [\'rows\' => $rows, \'mode\' => $modes[$i], \'label\' => $t, \'uid\' => $i])}\n            </div>\n        </div>\n        {/if}\n        {/foreach}\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-prices.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (305,1,0,'lb-pgallery','Редизайн: портфолио — галерея внутренней страницы с вкладками разделов',0,128,0,'{* Текст и галерея внутренней страницы. Шаблоны «Внутренняя - Галерея» (13, портфолио — вместо bl6-portfolio-interial),\n   «Внутренняя» (3: «О нас», вакансии, сертификат) и «Отзывы» (16) — вместо [[*gallery_select:notempty=`[[$bl6-portfolio-interial-2]]`]].\n   Текст — длинный TV description-banner-inerial (> 300 знаков; в баннер не помещается; короткий выводит баннер lb-shero), карточкой,\n   в одну колонку. Галерея — ms2Gallery ресурса (у EN — RO-двойника, lb.roId; tpl lb.galleryPage): в шаблоне 13 — всегда, в остальных — если задан TV gallery_select\n   (как раньше); первые 16 фото, дальше — кнопкой по 16 (redesign.js), увеличение — fancybox. Кнопка на TV link-bl6 — как в старом блоке.\n   Нет ни текста, ни фото — блок не выводится. Заголовка у старого блока не было — здесь тоже. *}\n{set $r = $_modx->resource}\n{set $showGal = $r.template == 13 || ($r[\'gallery_select\'] | trim)}\n{set $gallery = $showGal ? ($_modx->runSnippet(\'!ms2Gallery\', [\'resources\' => ($_modx->getChunk(\'lb.roId\') | trim), \'tpl\' => \'lb.galleryPage\', \'frontend_css\' => \'\', \'frontend_js\' => \'\']) | trim) : \'\'}\n{set $link = $r[\'link-bl6\'] | trim}\n{set $desc = $r[\'description-banner-inerial\'] | trim}\n{if !$desc || ($desc | striptags | trim | length) <= 300}{set $desc = \'\'}{/if}\n{if $desc || $gallery}\n<section class=\"lb-pgallery{$gallery ? \'\' : \' lb-pgallery--text\'}\" id=\"lb-pgallery\">\n    <div class=\"lb-pgallery__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-pgallery__inner\">\n        {if $desc}\n        <div class=\"lb-pgallery__intro\">\n            <div class=\"lb-pgallery__text\">{$desc}</div>\n        </div>\n        {/if}\n        {if $gallery}\n        {$gallery}\n        <div class=\"lb-pgallery__foot\">\n            <button class=\"lb-btn lb-btn--solid lb-pgallery__more\" type=\"button\" aria-controls=\"lb-gallery\">{\'lbar.rd.pf.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></button>\n            {if $link}\n            <a class=\"lb-btn lb-btn--ghost\" href=\"{$link}\">{\'lbar.portfolio.button.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n            {/if}\n        </div>\n        {/if}\n    </div>\n</section>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-pgallery.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (308,1,0,'lb-article','Редизайн: статья блога (текст, автор, соседние статьи, боковая колонка)',0,128,0,'{* Статья блога (шаблон «Блог - статья», id 5) — вместо content-blog. Баннера нет (шаг 45) — структура как у старой статьи:\n   хлебные крошки (pdoCrumbs, как в баннере общих страниц) и H1 (pagetitle, itemprop=\"headline\") во всю ширину; в колонке текста —\n   строка сведений, как была (рубрика — itemprop=\"genre\", автор — itemprop=\"author\" Person, просмотры — HitsPage, комментарии — #review;\n   дата — только в meta datePublished),\n   затем текст. Страница обёрнута в itemscope schema.org/Article (в шаблоне); здесь — те же скрытые свойства, что в старом чанке\n   (mainEntityOfPage, inLanguage, publisher, datePublished/dateModified, image) и itemprop=\"articleBody\" с текстом —\n   [[*content]] с прежней заменой путей картинок (галереи в тексте — чанки gallery_tagN, как раньше).\n   Под текстом: блок-призыв (TV title-action / sub-title-action / link-action, как было), автор, соседние статьи (pdoNeighbors).\n   Справа: популярные (5, по просмотрам) и новые (3) статьи — как blog-popular-page / blog-new-page. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $r = $_modx->resource}\n{set $isRo = $_modx->config.cultureKey == \'ro\'}\n{set $arr = \'<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-article\" id=\"lb-article\">\n    <div class=\"lb-article__bg\" aria-hidden=\"true\"></div>\n\n    <meta itemscope itemprop=\"mainEntityOfPage\" itemType=\"https://schema.org/WebPage\" itemid=\"\" content=\"\"/>\n    <meta itemprop=\"inLanguage\" content=\"uk\" />\n    <div itemprop=\"publisher\" itemscope itemtype=\"https://schema.org/Organization\" hidden>\n        <div itemprop=\"logo\" itemscope itemtype=\"https://schema.org/ImageObject\">\n            <img itemprop=\"url\" src=\"[[!++site_url]]images/design/logo-schema.jpg\" alt=\"[[++autor]]\" loading=\"lazy\">\n            <meta itemprop=\"width\" content=\"190\">\n            <meta itemprop=\"height\" content=\"36\">\n        </div>\n        <meta itemprop=\"name\" content=\"[[++site_name]]\">\n    </div>\n    <meta itemprop=\"datePublished dateModified\" content=\"[[*publishedon:strtotime:date=`%d/%m/%Y`]]\">\n    <div itemprop=\"image\" itemscope itemtype=\"https://schema.org/ImageObject\" hidden>\n        <img itemprop=\"image url\" alt=\"\" src=\"[[pthumb? &input=`[[*img-blog-prew]]` &options=`w=180&h=180`]]\" loading=\"lazy\">\n        <meta itemprop=\"width\" content=\"180\">\n        <meta itemprop=\"height\" content=\"180\">\n    </div>\n\n    {set $si = \' viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"\'}\n    <div class=\"lb-article__inner\">\n        <header class=\"lb-article__head\">\n            <nav class=\"lb-crumbs lb-crumbs--flow\" aria-label=\"{\'lbar.rd.aria.crumbs\' | lexicon}\">\n                {$_modx->runSnippet(\'!pdoCrumbs\', [\n                    \'showHome\' => 1,\n                    \'showAtHome\' => 0,\n                    \'tplWrapper\' => \'@INLINE <ol class=\"lb-crumbs__list\" itemscope itemtype=\"http://schema.org/BreadcrumbList\">[[+output]]</ol>\',\n                    \'tplHome\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link lb-crumbs__link--home\" href=\"[[+link]]\" itemprop=\"item\"><svg viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.2 10 3l7 6.2\"/><path d=\"M5 8v9h4v-5h2v5h4V8\"/></svg><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                    \'tpl\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link\" href=\"[[+link]]\" itemprop=\"item\"><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                    \'tplCurrent\' => \'@INLINE <li class=\"lb-crumbs__item lb-crumbs__item--current\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><span itemprop=\"name\">[[+menutitle]]</span><div itemprop=\"item\" content=\"[[++site_url]][[+link]]\"></div><meta itemprop=\"position\" content=\"[[+idx]]\" /></li>\',\n                ])}\n            </nav>\n            <h1 class=\"lb-article__title\" itemprop=\"headline\">{$r.pagetitle}</h1>\n        </header>\n\n        <article class=\"lb-article__main\">\n            <ul class=\"lb-article__info\">\n                <li class=\"lb-article__info-i lb-article__info-i--cat\"><a href=\"{$r.parent | url}\" itemprop=\"genre\"><svg{$si}><path d=\"M3 12.2V4.5A1.5 1.5 0 0 1 4.5 3h7.7l8.8 8.8a1.5 1.5 0 0 1 0 2.1l-7.1 7.1a1.5 1.5 0 0 1-2.1 0z\"/><circle cx=\"8\" cy=\"8\" r=\"1.6\"/></svg>{$_modx->runSnippet(\'pdoField\', [\'id\' => $r.parent, \'field\' => \'pagetitle\'])}</a></li>\n                <li class=\"lb-article__info-i\" itemprop=\"author\" itemscope itemtype=\"https://schema.org/Person\"><svg{$si}><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4.5 20.5c.9-3.9 3.9-6 7.5-6s6.6 2.1 7.5 6\"/></svg><span itemprop=\"name\">[[++autor]]</span><span itemprop=\"url\" hidden>[[ThisPageURL? &id=`[[*id]]`]]</span></li>\n                <li class=\"lb-article__info-i\" title=\"{\'lbar.rd.blog.views\' | lexicon}\"><svg{$si}><path d=\"M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg><span class=\"lb-article__info-v\">[[!HitsPage? &saveTv=`true`]]</span><span class=\"lb-article__info-l\">{\'lbar.rd.blog.views\' | lexicon}</span></li>\n                <li class=\"lb-article__info-i\"><a href=\"#review\"><svg{$si}><path d=\"M20.5 14.5a2 2 0 0 1-2 2H8l-4.5 4V5.5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z\"/></svg><span class=\"lb-article__info-v\">[[!ecMessagesCount]]</span><span class=\"lb-article__info-l\">{\'lbar.rd.blog.ncomments\' | lexicon}</span></a></li>\n            </ul>\n\n            <div class=\"lb-article__body\" itemprop=\"articleBody\">[[*content:replace=`<img src=\"==<img src=\"/`]]</div>\n\n            {if $r[\'title-action\'] | trim}\n            <div class=\"lb-article__action\">\n                <div class=\"lb-article__action-t\">{$r[\'title-action\']}</div>\n                {if $r[\'sub-title-action\'] | trim}<div class=\"lb-article__action-s\">{$r[\'sub-title-action\']}</div>{/if}\n                <a class=\"lb-btn lb-btn--solid\" href=\"{$r[\'link-action\']}\">{\'lbar.buttons.category.more\' | lexicon}{$arr}</a>\n            </div>\n            {/if}\n\n            <div class=\"lb-article__author\">\n                <img class=\"lb-article__author-img\" src=\"/images/design/autio-blog.jpg\" alt=\"\" width=\"150\" height=\"150\" loading=\"lazy\">\n                <div class=\"lb-article__author-info\">\n                    <div class=\"lb-article__author-name\">{$isRo ? \'Autor – Ksenia Kobilianskaia\' : \'Автор - <span>Ксения Кобылянская</span>\'}</div>\n                    <div class=\"lb-article__author-role\">{$isRo ? \'Master de Top/fondatorul studioului\' : \'ТОП-мастер/Основатель студии\'}</div>\n                    <div class=\"lb-article__author-text\">{$isRo ? \'Abonează-te la rețelele noastre de socializare și la canalul YouTube. <br/>Avem mult conținut interesant\' : \'Подписывайтесь на наши социальные сети и YouTube канал. <br/>У нас много крутого контента\'}</div>\n                </div>\n                <div class=\"lb-article__soc\">\n                    <a class=\"lb-article__soc-a\" href=\"[[++youtube]]\" rel=\"nofollow\" aria-label=\"YouTube\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M21.6 7.2a2.6 2.6 0 0 0-1.8-1.8C18.2 5 12 5 12 5s-6.2 0-7.8.4a2.6 2.6 0 0 0-1.8 1.8C2 8.8 2 12 2 12s0 3.2.4 4.8a2.6 2.6 0 0 0 1.8 1.8c1.6.4 7.8.4 7.8.4s6.2 0 7.8-.4a2.6 2.6 0 0 0 1.8-1.8c.4-1.6.4-4.8.4-4.8s0-3.2-.4-4.8zM10 15V9l5.2 3z\"/></svg></a>\n                    <a class=\"lb-article__soc-a\" href=\"[[++facebook]]\" rel=\"nofollow\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M13.5 21v-7.6h2.6l.4-3h-3V8.5c0-.9.3-1.5 1.5-1.5h1.6V4.3c-.3 0-1.2-.1-2.3-.1-2.3 0-3.8 1.4-3.8 3.9v2.3H7.9v3h2.6V21z\"/></svg></a>\n                    <a class=\"lb-article__soc-a\" href=\"[[++insta]]\" rel=\"nofollow\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" aria-hidden=\"true\"><rect x=\"3.5\" y=\"3.5\" width=\"17\" height=\"17\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.3\" cy=\"6.7\" r=\".9\" fill=\"currentColor\" stroke=\"none\"/></svg></a>\n                </div>\n            </div>\n\n            [[!pdoNeighbors?\n                &id=`[[*id]]`\n                &tplPrev=`lb.blogPrev`\n                &tplNext=`lb.blogNext`\n                &includeTVs=`img-blog-prew`\n                &tplWrapper=`@INLINE <nav class=\"lb-article__nb\">[[+prev]][[+next]]</nav>`\n            ]]\n        </article>\n\n        <aside class=\"lb-article__side\">\n            {$_modx->runSnippet(\'!pdoResources\', [\n                \'parents\' => $r.parent,\n                \'limit\' => 5,\n                \'hideContainers\' => 1,\n                \'resources\' => \'-\' ~ $r.id,\n                \'tpl\' => \'lb.blogSide\',\n                \'tplWrapper\' => \'@INLINE <div class=\"lb-side\"><div class=\"lb-side__title\">\' ~ ($isRo ? \'Publicații populare\' : \'Популярные публикации\') ~ \'</div><div class=\"lb-side__list\">[[+output]]</div></div>\',\n                \'includeTVs\' => \'img-blog-prew,HitsPage\',\n                \'sortby\' => \'HitsPage\',\n                \'sortdir\' => \'DESC\'\n            ])}\n            {$_modx->runSnippet(\'!pdoResources\', [\n                \'parents\' => $r.parent,\n                \'limit\' => 3,\n                \'hideContainers\' => 1,\n                \'resources\' => \'-\' ~ $r.id,\n                \'tpl\' => \'lb.blogSide\',\n                \'tplWrapper\' => \'@INLINE <div class=\"lb-side\"><div class=\"lb-side__title\">\' ~ ($isRo ? \'Publicații noi\' : \'Последние публикации\') ~ \'</div><div class=\"lb-side__list\">[[+output]]</div></div>\',\n                \'includeTVs\' => \'img-blog-prew\',\n                \'sortby\' => \'publishedon\',\n                \'sortdir\' => \'DESC\'\n            ])}\n            <div class=\"lb-side lb-side--cta\">\n                <div class=\"lb-side__cta-t\">{\'lbar.rd.blog.cta\' | lexicon}</div>\n                <a class=\"lb-btn lb-btn--solid lb-btn--sm js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}{$arr}</a>\n            </div>\n        </aside>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-article.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (309,1,0,'lb.blogCard','Редизайн: карточка статьи (tpl pdoPage)',0,128,0,'{* Карточка статьи в списке блога (tpl pdoPage в lb-bloglist). Данные — как в старом tpl.subcat.blog: превью TV img-blog-prew\n   (нет — настройка img-blog-prew-default), название — menutitle или pagetitle, просмотры — TV HitsPage (рубрики в карточке нет — шаг 45),\n   число комментариев — EasyComm ветки статьи (как было), анонс — introtext. Значки «видео» / «галерея» — TV video-icon / gallery-icon. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $img = ($_pls[\'tv.img-blog-prew\'] | trim) ?: (\'[[++img-blog-prew-default]]\' | trim)}\n{if $img && !($img | ematch : \'~^(/|https?:)~\')}{set $img = \'/\' ~ $img}{/if}\n{set $title = $menutitle ?: $pagetitle}\n<article class=\"lb-bcard\">\n    <a class=\"lb-bcard__img\" href=\"{$uri}\" tabindex=\"-1\" aria-hidden=\"true\">\n        {if $img}<img src=\"{$img | replace : \' \' : \'%20\'}\" alt=\"{$title | escape}\" width=\"600\" height=\"400\" loading=\"lazy\" decoding=\"async\">{/if}\n        {if $_pls[\'tv.video-icon\'] || $_pls[\'tv.gallery-icon\']}\n        <span class=\"lb-bcard__badges\">\n            {if $_pls[\'tv.video-icon\']}<span class=\"lb-bcard__badge\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M8 5.5v13c0 .6.6.9 1.1.6l10-6.5c.5-.3.5-1 0-1.3l-10-6.5C8.6 4.6 8 4.9 8 5.5z\"/></svg></span>{/if}\n            {if $_pls[\'tv.gallery-icon\']}<span class=\"lb-bcard__badge\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2.5\"/><circle cx=\"9\" cy=\"10\" r=\"1.8\"/><path d=\"m21 16-5-5-8 8\"/></svg></span>{/if}\n        </span>\n        {/if}\n    </a>\n    <div class=\"lb-bcard__body\">\n        <div class=\"lb-bcard__meta\">\n            <span class=\"lb-bcard__stat\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>{$_pls[\'tv.HitsPage\'] ?: 0}</span>\n        </div>\n        <div class=\"lb-bcard__title\"><a href=\"{$uri}\">{$title}</a></div>\n        {if $introtext}<p class=\"lb-bcard__text\">{$introtext}</p>{/if}\n        <div class=\"lb-bcard__foot\">\n            <a class=\"lb-bcard__stat lb-bcard__comments\" href=\"{$uri}#review\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20.5 14.5a2 2 0 0 1-2 2H8l-4.5 4V5.5a2 2 0 0 1 2-2h13a2 2 0 0 1 2 2z\"/></svg>[[!ecMessagesCount? &tpl=`tpl.ecThreadRating.BlogList` &thread=`resource-[[+id]]`]]</a>\n            <a class=\"lb-btn lb-btn--ghost lb-btn--sm lb-bcard__btn\" href=\"{$uri}\">{\'lbar.buttons.category.more\' | lexicon}<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></a>\n        </div>\n    </div>\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.blogCard.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (310,1,0,'lb-bloglist','Редизайн: список статей блога',0,128,0,'{* Список статей блога (шаблон «Блог - список статей», id 4) — вместо статей в content-blog-list (H1 и крошки — в баннере lb-shero).\n   Список — как было: pdoPage (parents = текущий, limit 60, hideContainers, setMeta, сортировка по просмотрам HitsPage), карточка lb.blogCard;\n   постраничная навигация — [[!+page.nav]]; текст раздела (content) — только на первой странице, как было. *}\n{set $list = $_modx->runSnippet(\'!pdoPage\', [\n    \'parents\' => $_modx->resource.id,\n    \'limit\' => 60,\n    \'hideContainers\' => 1,\n    \'setMeta\' => 1,\n    \'tpl\' => \'lb.blogCard\',\n    \'includeTVs\' => \'img-blog-prew,HitsPage,video-icon,gallery-icon\',\n    \'sortby\' => \'HitsPage\',\n    \'sortdir\' => \'DESC\',\n    \'tplPageWrapper\' => \'@INLINE <nav class=\"lb-pager\" aria-label=\"Pagination\"><ul class=\"lb-pager__list\">[[+first]][[+prev]][[+pages]][[+next]][[+last]]</ul></nav>\',\n    \'tplPage\' => \'@INLINE <li class=\"lb-pager__item\"><a class=\"lb-pager__link\" href=\"[[+href]]\">[[+pageNo]]</a></li>\',\n    \'tplPageActive\' => \'@INLINE <li class=\"lb-pager__item is-active\"><span class=\"lb-pager__link\">[[+pageNo]]</span></li>\',\n    \'tplPagePrev\' => \'@INLINE <li class=\"lb-pager__item lb-pager__item--prev\"><a class=\"lb-pager__link\" href=\"[[+href]]\" aria-label=\"&larr;\">&larr;</a></li>\',\n    \'tplPageNext\' => \'@INLINE <li class=\"lb-pager__item lb-pager__item--next\"><a class=\"lb-pager__link\" href=\"[[+href]]\" aria-label=\"&rarr;\">&rarr;</a></li>\',\n    \'tplPageFirst\' => \'\',\n    \'tplPageLast\' => \'\',\n    \'tplPagePrevEmpty\' => \'\',\n    \'tplPageNextEmpty\' => \'\',\n    \'tplPageSkip\' => \'@INLINE <li class=\"lb-pager__item lb-pager__item--skip\"><span>…</span></li>\'\n])}\n<section class=\"lb-bloglist\" id=\"lb-bloglist\">\n    <div class=\"lb-bloglist__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-bloglist__inner\">\n        <div class=\"lb-bloglist__grid\">\n            {$list}\n        </div>\n        [[!+page.nav]]\n        {if !$.get[\'page\'] && ($_modx->resource.content | trim)}\n        <div class=\"lb-bloglist__text\">{$_modx->resource.content}</div>\n        {/if}\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-bloglist.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (311,1,0,'lb.blogNext','Редизайн: следующая статья (pdoNeighbors)',0,128,0,'{* Соседняя статья — следующая (tplPext pdoNeighbors), как старый tpl.next: ссылка, название, превью (pthumb 300×180). *}\n<a class=\"lb-nb lb-nb--next\" href=\"/{$uri}\">\n    <span class=\"lb-nb__img\"><img src=\"[[pthumb? &input=`[[+tv.img-blog-prew:empty=`[[++img-blog-prew-default]]`]]` &options=`w=300&h=180&zc=1`]]\" alt=\"\" width=\"300\" height=\"180\" loading=\"lazy\" decoding=\"async\"></span>\n    <span class=\"lb-nb__body\">\n        <span class=\"lb-nb__dir\" aria-hidden=\"true\"><svg viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg></span>\n        <span class=\"lb-nb__title\">{$pagetitle}</span>\n    </span>\n</a>\n',0,NULL,1,'core/elements/redesign/chunks/lb.blogNext.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (312,1,0,'lb.blogPrev','Редизайн: предыдущая статья (pdoNeighbors)',0,128,0,'{* Соседняя статья — предыдущая (tplPrev pdoNeighbors), как старый tpl.prev: ссылка, название, превью (pthumb 300×180). *}\n<a class=\"lb-nb lb-nb--prev\" href=\"/{$uri}\">\n    <span class=\"lb-nb__img\"><img src=\"[[pthumb? &input=`[[+tv.img-blog-prew:empty=`[[++img-blog-prew-default]]`]]` &options=`w=300&h=180&zc=1`]]\" alt=\"\" width=\"300\" height=\"180\" loading=\"lazy\" decoding=\"async\"></span>\n    <span class=\"lb-nb__body\">\n        <span class=\"lb-nb__dir\" aria-hidden=\"true\"><svg viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M26 7H1.5M7.5 1.2 1.5 7l6 5.8\"/></svg></span>\n        <span class=\"lb-nb__title\">{$pagetitle}</span>\n    </span>\n</a>\n',0,NULL,1,'core/elements/redesign/chunks/lb.blogPrev.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (313,1,0,'lb.blogSide','Редизайн: статья в боковой колонке',0,128,0,'{* Статья в боковой колонке (популярные / новые) — данные как в старых tpl.blog.poular.page / tpl.blog.new.page:\n   превью TV img-blog-prew (нет — настройка img-blog-prew-default, pthumb 200×160), название — pagetitle. *}\n<a class=\"lb-side__item\" href=\"{$uri}\">\n    <span class=\"lb-side__img\"><img src=\"[[pthumb? &input=`[[+tv.img-blog-prew:empty=`[[++img-blog-prew-default]]`]]` &options=`w=200&h=160&zc=1`]]\" alt=\"\" width=\"100\" height=\"80\" loading=\"lazy\" decoding=\"async\"></span>\n    <span class=\"lb-side__name\">{$pagetitle}</span>\n</a>\n',0,NULL,1,'core/elements/redesign/chunks/lb.blogSide.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (314,1,0,'lb.commentRow','Редизайн: комментарий (tpl ecMessages)',0,128,0,'{* Комментарий к статье (tpl ecMessages в lb-comments): имя, звёзды, текст и ответ студии — полностью (как в старом tpl.ecMessages.Row.Blog). *}\n{set $name = $user_name | trim}\n{set $parts = $name | replace : \',\' : \' \' | split : \' \'}\n{set $ini = $parts[0] | truncate : 1 : \'\'}\n{if $parts[1]?}{set $ini = $ini ~ ($parts[1] | truncate : 1 : \'\')}{/if}\n{set $star = \'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2.4l2.95 6.02 6.63.95-4.8 4.67 1.13 6.6L12 17.52l-5.91 3.12 1.13-6.6-4.8-4.67 6.63-.95z\"/></svg>\'}\n<article class=\"lb-comment\" id=\"ec-{$thread_name}-message-{$id}\">\n    <div class=\"lb-comment__head\">\n        <span class=\"lb-rcard__ava lb-rcard__ava--{($name | crc32) % 4}\" aria-hidden=\"true\">{$ini | upper}</span>\n        <div class=\"lb-comment__who\">\n            <div class=\"lb-comment__name\">{$name}</div>\n            {if $rating > 0}\n            <div class=\"lb-rcard__stars\" role=\"img\" aria-label=\"{$rating} / 5\">{foreach 1..5 as $i}<span class=\"lb-rcard__star{if $i > $rating} is-off{/if}\">{$star}</span>{/foreach}</div>\n            {/if}\n        </div>\n    </div>\n    <div class=\"lb-comment__text\">{$text}</div>\n    {if $reply_text}\n    <div class=\"lb-comment__reply\">{if $reply_author}<b>{$reply_author}</b>{/if}<div>{$reply_text}</div></div>\n    {/if}\n</article>\n',0,NULL,1,'core/elements/redesign/chunks/lb.commentRow.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (315,1,0,'lb-comments','Редизайн: комментарии статьи (EasyComm)',0,128,0,'{* Комментарии статьи (шаблон «Блог - статья») — вместо row-comment-inst / row-comment-message-inst в content-blog.\n   EasyComm как раньше: [[!ecMessages]] (ветка resource-<id>, до 80, только опубликованные; tpl lb.commentRow) и [[!ecForm]]\n   с прежними письмами и модерацией (форма — lb.ecForm, как в окне отзывов; JS отправки — easyComm из старого custom.js).\n   Якорь #review — как было (на него ведёт счётчик в баннере). Заголовок — не H2 (у старого блока заголовка не было). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n<section class=\"lb-comments\" id=\"lb-comments\">\n    <div class=\"lb-comments__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-comments__inner\">\n        <div id=\"review\"></div>\n        <div class=\"lb-comments__head\">\n            <div class=\"lb-comments__title\">{\'lbar.rd.blog.comments\' | lexicon} <span class=\"lb-comments__count\">[[!ecMessagesCount]]</span></div>\n        </div>\n        <div class=\"lb-comments__grid\">\n            <div class=\"lb-comments__list\">\n                [[!ecMessages? &tpl=`lb.commentRow` &limit=`80` &tplWrapper=`@INLINE [[+output]]`]]\n            </div>\n            <div class=\"lb-comments__form\">\n                <div class=\"lb-comments__form-t\">{\'lbar.reviews.form.title\' | lexicon}</div>\n                [[!ecForm?\n                    &tplForm=`lb.ecForm`\n                    &tplSuccess=`tpl.ecForm.Success.Blog`\n                    &tplNewEmailManager=`tpl.ecForm.New.Email.Manager.Blog`\n                    &tplUpdateEmailUser=`tpl.ecForm.Update.Email.User.Blog`\n                    &tplNewEmailUser=`tpl.ecForm.New.Email.User.Blog`\n                ]]\n            </div>\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-comments.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (316,1,0,'lb-404','Редизайн: страница 404',0,128,0,'{* Страница 404 (редизайн; шаблон «404 eror page», 2: RO 20, RU 206) — вместо секции content-eror старого шаблона.\n   H1 — как было: «Hopa!» / «Упс!» (прежний текст из шаблона, теперь лексикон lbar.rd.msg.oops) + pagetitle.\n   Над H1 — графическое «404» (цифры шрифтом, ноль — овал-«портал», aria-hidden) вместо картинки images/design/404.png из content.\n   Текст — content ресурса без этой картинки и без списка со ссылкой; ссылка из списка («Înapoi la pagina principală» / «перейти на главную»,\n   href [[++site_url]]) — кнопкой с её же текстом. Вторая кнопка — запись (на странице нет формы — окно «Заказать звонок», js-lb-book).\n   Внимание: в выражениях Fenom не писать «*» + «/» подряд. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $r = $_modx->resource}\n{set $c = $r.content}\n{set $text = $c | ereplace : \'~<p>\\s*<img[^>]*>\\s*</p>~iu\' : \'\' | ereplace : \'~<ul\\b.*?</ul>~isu\' : \'\'}\n{set $home = \'\'}\n{set $href = \'\'}\n{if $c | ematch : \'~<a\\s[^>]*href=\"[^\"]+\"[^>]*>.+?</a>~isu\'}\n    {set $home = $c | ereplace : \'~^.*?<a\\s[^>]*>(.*?)</a>.*$~isu\' : \'$1\'}\n    {set $href = $c | ereplace : \'~^.*?<a\\s[^>]*href=\"([^\"]*)\".*$~isu\' : \'$1\'}\n{/if}\n{set $arr = \'<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-msg lb-msg--404\" id=\"lb-msg\">\n    <div class=\"lb-msg__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-msg__inner\">\n        <div class=\"lb-msg__num\" aria-hidden=\"true\">\n            <span class=\"lb-msg__digit\">4</span>\n            <span class=\"lb-msg__digit lb-msg__digit--zero\"><svg class=\"lb-msg__zero\" viewBox=\"0 0 240 300\">\n                <defs>\n                    <linearGradient id=\"lb404-f\" gradientUnits=\"userSpaceOnUse\" x1=\"0\" y1=\"18\" x2=\"0\" y2=\"282\"><stop offset=\"0\" stop-color=\"#dcae93\"/><stop offset=\".58\" stop-color=\"#ab7152\"/><stop offset=\"1\" stop-color=\"#875840\"/></linearGradient>\n                    <radialGradient id=\"lb404-g\" cx=\".5\" cy=\".42\" r=\".55\"><stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\".95\"/><stop offset=\".65\" stop-color=\"#f7e9e0\" stop-opacity=\".6\"/><stop offset=\"1\" stop-color=\"#efd9cb\" stop-opacity=\"0\"/></radialGradient>\n                </defs>\n                <ellipse cx=\"120\" cy=\"150\" rx=\"86\" ry=\"118\" fill=\"url(#lb404-g)\"/>\n                <path class=\"lb-msg__o\" fill=\"url(#lb404-f)\" fill-rule=\"evenodd\" d=\"M120 18c-56 0-98 59-98 132s42 132 98 132 98-59 98-132S176 18 120 18zm0 13c-35 0-62 53-62 119s27 119 62 119 62-53 62-119-27-119-62-119z\"/>\n                <ellipse class=\"lb-msg__ring\" cx=\"120\" cy=\"150\" rx=\"112\" ry=\"144\" fill=\"none\" stroke=\"url(#lb404-f)\" stroke-width=\"1.2\" stroke-opacity=\".55\" pathLength=\"1\"/>\n                <path class=\"lb-msg__spark\" fill=\"#b07455\" d=\"M206 20c.7 7.4 5.8 12.9 13.8 13.8-8 .9-13.1 6.4-13.8 13.8-.7-7.4-5.8-12.9-13.8-13.8 8-.9 13.1-6.4 13.8-13.8z\"/>\n                <path class=\"lb-msg__spark\" fill=\"#c99278\" d=\"M28 248c.5 4.6 3.6 8 8.6 8.6-5 .6-8.1 4-8.6 8.6-.5-4.6-3.6-8-8.6-8.6 5-.6 8.1-4 8.6-8.6z\"/>\n            </svg></span>\n            <span class=\"lb-msg__digit\">4</span>\n        </div>\n        <h1 class=\"lb-msg__title\"><span class=\"lb-msg__accent\">{\'lbar.rd.msg.oops\' | lexicon}</span> {$r.pagetitle}</h1>\n        {if $text | trim}<div class=\"lb-msg__text\">{$text}</div>{/if}\n        <div class=\"lb-msg__btns\">\n            <a class=\"lb-btn lb-btn--solid\" href=\"{$href ?: \'[[++site_url]]\'}\">{$home ?: (\'lbar.rd.thanks.home\' | lexicon)}{$arr}</a>\n            <a class=\"lb-btn lb-btn--ghost js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}{$arr}</a>\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-404.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (317,1,0,'lb-thanks','Редизайн: страница «Спасибо» после отправки формы',0,128,0,'{* Страница «Спасибо» после отправки формы (редизайн; шаблон «Success-Page-RU», 6: RO 40 /thanx-you, RU 269) — вместо overlay/thanks-wrap.\n   Тексты — прежние из шаблона (были [[++cultureKey:is=…]]), перенесены в лексикон без изменений: lbar.rd.thanks.studio / .by\n   («Studiou micropigmentare by Ksenia Kobilianskaia»), .title («Mulțumesc» — как и раньше не заголовок, а div), .text, .home (кнопка на главную).\n   Логотип-картинка images/inner/LBarlogo.png заменён печатью с галочкой (графика, aria-hidden): логотип уже в шапке. Заголовков на странице\n   нет, как и было. *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $arr = \'<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-msg lb-msg--thanks\" id=\"lb-msg\">\n    <div class=\"lb-msg__bg\" aria-hidden=\"true\"></div>\n    <div class=\"lb-msg__inner\">\n        <div class=\"lb-msg__seal\" aria-hidden=\"true\"><svg viewBox=\"0 0 220 220\">\n            <defs>\n                <linearGradient id=\"lbty-f\" gradientUnits=\"userSpaceOnUse\" x1=\"0\" y1=\"20\" x2=\"0\" y2=\"200\"><stop offset=\"0\" stop-color=\"#dcae93\"/><stop offset=\".58\" stop-color=\"#ab7152\"/><stop offset=\"1\" stop-color=\"#875840\"/></linearGradient>\n                <radialGradient id=\"lbty-g\" cx=\".5\" cy=\".42\" r=\".55\"><stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\".95\"/><stop offset=\".7\" stop-color=\"#f7e9e0\" stop-opacity=\".75\"/><stop offset=\"1\" stop-color=\"#efd9cb\" stop-opacity=\".2\"/></radialGradient>\n            </defs>\n            <circle cx=\"110\" cy=\"110\" r=\"84\" fill=\"url(#lbty-g)\"/>\n            <circle class=\"lb-msg__ring\" cx=\"110\" cy=\"110\" r=\"84\" fill=\"none\" stroke=\"url(#lbty-f)\" stroke-width=\"4\" pathLength=\"1\"/>\n            <circle class=\"lb-msg__ring\" cx=\"110\" cy=\"110\" r=\"70\" fill=\"none\" stroke=\"url(#lbty-f)\" stroke-width=\"1\" stroke-opacity=\".55\" pathLength=\"1\"/>\n            <circle class=\"lb-msg__dots\" cx=\"110\" cy=\"110\" r=\"99\" fill=\"none\" stroke=\"#c39077\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-dasharray=\".01 9.3\" stroke-opacity=\".7\"/>\n            <path class=\"lb-msg__check\" fill=\"none\" stroke=\"url(#lbty-f)\" stroke-width=\"7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" pathLength=\"1\" d=\"M76 112.5 98.5 135 145 86\"/>\n            <path class=\"lb-msg__spark\" fill=\"#b07455\" d=\"M188 22c.7 7.4 5.8 12.9 13.8 13.8-8 .9-13.1 6.4-13.8 13.8-.7-7.4-5.8-12.9-13.8-13.8 8-.9 13.1-6.4 13.8-13.8z\"/>\n            <path class=\"lb-msg__spark\" fill=\"#c99278\" d=\"M26 168c.5 4.6 3.6 8 8.6 8.6-5 .6-8.1 4-8.6 8.6-.5-4.6-3.6-8-8.6-8.6 5-.6 8.1-4 8.6-8.6z\"/>\n        </svg></div>\n        <div class=\"lb-msg__big\">{\'lbar.rd.thanks.title\' | lexicon}</div>\n        <svg class=\"lb-msg__flourish\" viewBox=\"0 0 440 50\" aria-hidden=\"true\"><path fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" d=\"M8 34c60-14 128-20 196-18 52 1 98 8 126 14M330 30c22 5 52 4 102-18\"/><path fill=\"currentColor\" d=\"M214 4c.6 6 4.6 10.4 11 11-6.4.6-10.4 5-11 11-.6-6-4.6-10.4-11-11 6.4-.6 10.4-5 11-11z\"/></svg>\n        <div class=\"lb-msg__text\">{\'lbar.rd.thanks.text\' | lexicon}</div>\n        <div class=\"lb-msg__btns\">\n            <a class=\"lb-btn lb-btn--solid\" href=\"[[++site_url]]\">{\'lbar.rd.thanks.home\' | lexicon}{$arr}</a>\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-thanks.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (320,1,0,'lb-ahero','Редизайн',0,128,0,'{* Страница «О нас» (шаблон «О нас», шаг 47): первый экран + бегущая строка. Структура и тексты — по макету пользователя\n   (LBAR Despre noi), оформление — в стиле сайта (шкала заголовков lb-h, контейнер lb-wrap, кнопки lb-btn, крошки lb-crumbs).\n   Тексты — лексикон lbar.rd.ab.* (источник — _dev/about/ab.py). H1 — из макета (согласовано): прежний H1 (pagetitle)\n   выводится H2 в карточке «О студии» (lb-areasons). Надзаголовков нет (как на всём сайте).\n   Слева: крошки (pdoCrumbs, как в баннере общих страниц), H1, вводный текст, три цифры, кнопки «Записаться» (#bl8-form) и\n   «Смотреть работы» (портфолио 100 / 198 / 1100). Справа — фото в арке (вырезка img/hero-master-v2*.webp, как на главной)\n   с подписью. Фон — только графика: тон, контур «2016», две арки справа. Бегущая строка — CSS-анимация (второй список —\n   копия для бесшовного цикла, скрыт от экранных чтецов). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $ck = $_modx->config.cultureKey}\n{set $pfs = [\'ro\' => 100, \'ru\' => 198, \'en\' => 1100]}\n{set $pf = $pfs[$ck] ?: 100}\n{set $arr = \'<svg class=\"lb-btn__arr\" viewBox=\"0 0 27 14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M1 7h24.5M19.5 1.2 25.5 7l-6 5.8\"/></svg>\'}\n<section class=\"lb-ahero\" id=\"lb-ahero\">\n    <div class=\"lb-ahero__bg\" aria-hidden=\"true\">\n        <span class=\"lb-ahero__year\">2016</span>\n        <span class=\"lb-ahero__arch\"></span>\n        <span class=\"lb-ahero__arch lb-ahero__arch--in\"></span>\n    </div>\n\n    <div class=\"lb-ahero__inner\">\n        <div class=\"lb-ahero__content\">\n            <nav class=\"lb-crumbs lb-crumbs--flow\" aria-label=\"{\'lbar.rd.aria.crumbs\' | lexicon}\">\n                {$_modx->runSnippet(\'!pdoCrumbs\', [\n                    \'showHome\' => 1,\n                    \'showAtHome\' => 0,\n                    \'tplWrapper\' => \'@INLINE <ol class=\"lb-crumbs__list\" itemscope itemtype=\"http://schema.org/BreadcrumbList\">[[+output]]</ol>\',\n                    \'tplHome\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link lb-crumbs__link--home\" href=\"[[+link]]\" itemprop=\"item\"><svg viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 9.2 10 3l7 6.2\"/><path d=\"M5 8v9h4v-5h2v5h4V8\"/></svg><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                    \'tpl\' => \'@INLINE <li class=\"lb-crumbs__item\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><a class=\"lb-crumbs__link\" href=\"[[+link]]\" itemprop=\"item\"><span itemprop=\"name\">[[+menutitle]]</span><meta itemprop=\"position\" content=\"[[+idx]]\" /></a></li>\',\n                    \'tplCurrent\' => \'@INLINE <li class=\"lb-crumbs__item lb-crumbs__item--current\" itemprop=\"itemListElement\" itemscope itemtype=\"http://schema.org/ListItem\"><span itemprop=\"name\">[[+menutitle]]</span><div itemprop=\"item\" content=\"[[++site_url]][[+link]]\"></div><meta itemprop=\"position\" content=\"[[+idx]]\" /></li>\',\n                ])}\n            </nav>\n            <h1 class=\"lb-ahero__title\"><span class=\"lb-ahero__t1\">{\'lbar.rd.ab.hero.h1a\' | lexicon}</span> <span class=\"lb-ahero__t2\">{\'lbar.rd.ab.hero.h1b\' | lexicon}</span></h1>\n            <p class=\"lb-ahero__lead\">{\'lbar.rd.ab.hero.lead\' | lexicon}</p>\n            <ul class=\"lb-ahero__stats\">\n                {foreach [1, 2, 3] as $i}\n                <li class=\"lb-ahero__stat\"><span class=\"lb-ahero__sn\">{(\'lbar.rd.ab.hero.s\' ~ $i ~ \'n\') | lexicon}</span><span class=\"lb-ahero__sl\">{(\'lbar.rd.ab.hero.s\' ~ $i ~ \'l\') | lexicon}</span></li>\n                {/foreach}\n            </ul>\n            <div class=\"lb-ahero__btns\">\n                <a class=\"lb-btn lb-btn--solid js-lb-book\" href=\"#bl8-form\">{\'lbar.buttons.banner.book\' | lexicon}{$arr}</a>\n                <a class=\"lb-btn lb-btn--ghost\" href=\"{$pf | url}\">{\'lbar.rd.ab.hero.works\' | lexicon}{$arr}</a>\n            </div>\n        </div>\n\n        <figure class=\"lb-ahero__media\">\n            <span class=\"lb-ahero__frame\" aria-hidden=\"true\"></span>\n            <span class=\"lb-ahero__photo\">\n                <img src=\"/assets/templates/redesign/img/hero-master-v2.webp\" srcset=\"/assets/templates/redesign/img/hero-master-v2.webp 570w, /assets/templates/redesign/img/hero-master-v2-2x.webp 1140w\" sizes=\"(max-width: 1024px) 90vw, 30vw\" width=\"570\" height=\"760\" alt=\"{\'lbar.rd.ab.name\' | lexicon}\" loading=\"eager\" fetchpriority=\"high\" decoding=\"async\">\n            </span>\n            <figcaption class=\"lb-ahero__card\"><span class=\"lb-ahero__name\">{\'lbar.rd.ab.name\' | lexicon}</span><span class=\"lb-ahero__role\">{\'lbar.rd.ab.hero.role\' | lexicon}</span></figcaption>\n            <svg class=\"lb-ahero__spark\" viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 0c.8 6.5 3.5 9.2 10 10-6.5.8-9.2 3.5-10 10-.8-6.5-3.5-9.2-10-10 6.5-.8 9.2-3.5 10-10z\"/></svg>\n        </figure>\n    </div>\n</section>\n\n<div class=\"lb-ticker\">\n    <div class=\"lb-ticker__track\">\n        {foreach [0, 1] as $copy}\n        <ul class=\"lb-ticker__list\"{if $copy} aria-hidden=\"true\"{/if}>\n            {foreach [1, 2, 3, 4, 5, 6] as $i}\n            <li class=\"lb-ticker__item{if $i % 2 == 0} lb-ticker__item--accent{/if}\">{(\'lbar.rd.ab.tick.\' ~ $i) | lexicon}</li>\n            {/foreach}\n        </ul>\n        {/foreach}\n    </div>\n</div>\n',0,NULL,1,'core/elements/redesign/chunks/lb-ahero.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (318,1,0,'lb.roId','Редизайн',0,128,0,'{* id ресурса, чьи отзывы (ветка EasyComm) и фото (ms2Gallery) выводятся на странице: у EN-страницы — RO-двойник по связям Babel\n   (сниппет BabelTranslation; переводы EN — без своих галерей и веток, общие с RO), у RO и RU — сам ресурс.\n   Вызов: {$_modx->getChunk(\'lb.roId\') | trim}. *}\n{set $id = $_modx->resource.id}\n{if $_modx->config.cultureKey == \'en\'}\n{set $ro = $_modx->runSnippet(\'BabelTranslation\', [\'resourceId\' => $id, \'contextKey\' => \'web\']) | trim}\n{if $ro}{set $id = $ro}{/if}\n{/if}\n{$id}\n',0,NULL,1,'core/elements/redesign/chunks/lb.roId.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (321,1,0,'lb-areasons','Редизайн',0,128,0,'{* Страница «О нас» (шаг 47): «Шесть причин выбрать нас» (строки: что / цифра или факт / пояснение — лексикон lbar.rd.ab.why.*)\n   и карточка «О студии»: H2 — pagetitle ресурса (прежний H1 страницы, согласовано; первая половина слов прямо, остальное курсивом —\n   только разметка), текст — прежний TV description-banner-inerial без правок (в нём и ссылки «Отзывы» / «Вакансии»), в две колонки.\n   Низ блока уходит в «Вопросы и ответы» лентой seam-faq (как «Отзывы» → FAQ на главной). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n{set $r = $_modx->resource}\n{set $words = $r.pagetitle | trim | split : \' \'}\n{set $n = $words | length}\n{set $k = ($n + 1 - ($n + 1) % 2) / 2}\n<section class=\"lb-areasons\" id=\"lb-areasons\">\n    <div class=\"lb-areasons__inner\">\n        <h2 class=\"lb-areasons__title\"><span class=\"lb-areasons__t1\">{\'lbar.rd.ab.why.h2a\' | lexicon}</span> <span class=\"lb-areasons__t2\">{\'lbar.rd.ab.why.h2b\' | lexicon}</span></h2>\n        <ul class=\"lb-areasons__list\">\n            {foreach [1, 2, 3, 4, 5, 6] as $i}\n            <li class=\"lb-areasons__row\">\n                <span class=\"lb-areasons__l\">{(\'lbar.rd.ab.why.\' ~ $i ~ \'l\') | lexicon}</span>\n                <span class=\"lb-areasons__v\">{(\'lbar.rd.ab.why.\' ~ $i ~ \'v\') | lexicon}</span>\n                <span class=\"lb-areasons__t\">{(\'lbar.rd.ab.why.\' ~ $i ~ \'t\') | lexicon}</span>\n            </li>\n            {/foreach}\n        </ul>\n\n        <article class=\"lb-astudio\">\n            <h2 class=\"lb-astudio__title\">{foreach $words as $j => $w}{if $j == $k}<span class=\"lb-astudio__t2\">{/if}{if $j} {/if}{$w}{/foreach}{if $n > $k}</span>{/if}</h2>\n            <div class=\"lb-astudio__text\">{$r[\'description-banner-inerial\']}</div>\n        </article>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-areasons.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (322,1,0,'lb-asteps','Редизайн',0,128,0,'{* Страница «О нас» (шаг 47): «Шесть шагов» — тёмный блок (тон как у «Мастера» на главной). Слева (десктоп) — крупный номер\n   текущего шага, «01 / 06» и полоса прогресса, прилипают при прокрутке; справа — шаги (H3 + текст). Текущий шаг —\n   redesign.js: data-step у секции (0–5) и is-active у пункта; без JS видны все шаги и номер 01.\n   На телефоне номер — перед заголовком каждого шага. Тексты — лексикон lbar.rd.ab.steps.* . *}\n{$_modx->lexicon->load(\'babel:translate\')}\n<section class=\"lb-asteps\" id=\"lb-asteps\" data-step=\"0\">\n    <div class=\"lb-asteps__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-asteps__inner\">\n        <div class=\"lb-asteps__head\">\n            <h2 class=\"lb-asteps__title\"><span class=\"lb-asteps__t1\">{\'lbar.rd.ab.steps.h2a\' | lexicon}</span> <span class=\"lb-asteps__t2\">{\'lbar.rd.ab.steps.h2b\' | lexicon}</span></h2>\n            <p class=\"lb-asteps__side\">{\'lbar.rd.ab.steps.side\' | lexicon}</p>\n        </div>\n\n        <div class=\"lb-asteps__body\">\n            <div class=\"lb-asteps__counter\" aria-hidden=\"true\">\n                <span class=\"lb-asteps__nums\">{foreach [1, 2, 3, 4, 5, 6] as $i}<span class=\"lb-asteps__n\">0{$i}</span>{/foreach}</span>\n                <span class=\"lb-asteps__of\">{foreach [1, 2, 3, 4, 5, 6] as $i}<span class=\"lb-asteps__ofn\">0{$i}</span>{/foreach} / 06</span>\n                <span class=\"lb-asteps__bar\"><span class=\"lb-asteps__fill\"></span></span>\n            </div>\n            <ol class=\"lb-asteps__list\">\n                {foreach [1, 2, 3, 4, 5, 6] as $i}\n                <li class=\"lb-asteps__item{if $i == 1} is-active{/if}\">\n                    <span class=\"lb-asteps__in\" aria-hidden=\"true\">0{$i}</span>\n                    <h3 class=\"lb-asteps__it\">{(\'lbar.rd.ab.steps.\' ~ $i ~ \'t\') | lexicon}</h3>\n                    <p class=\"lb-asteps__id\">{(\'lbar.rd.ab.steps.\' ~ $i ~ \'d\') | lexicon}</p>\n                </li>\n                {/foreach}\n            </ol>\n        </div>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-asteps.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (323,1,0,'lb-astory','Редизайн',0,128,0,'{* Страница «О нас» (шаг 47): «Обо мне» — H2, фото в арке (вырезка img/about-me-v2.webp), текст с цитатой, техники, подпись;\n   ниже — четыре цифры (10+ лет, 6 000+ процедур, 400+ учеников, призёр). Тексты — лексикон lbar.rd.ab.story.* / num.* .\n   Низ блока уходит в тёмный блок «Шесть шагов» волной (как «Консультация» → «Мастер» на главной, _apage.scss). *}\n{$_modx->lexicon->load(\'babel:translate\')}\n<section class=\"lb-astory\" id=\"lb-astory\">\n    <div class=\"lb-astory__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-astory__inner\">\n        <div class=\"lb-astory__aside\">\n            <h2 class=\"lb-astory__title\"><span class=\"lb-astory__t1\">{\'lbar.rd.ab.story.h2a\' | lexicon}</span> <span class=\"lb-astory__t2\">{\'lbar.rd.ab.story.h2b\' | lexicon}</span></h2>\n            <div class=\"lb-astory__media\">\n                <span class=\"lb-astory__frame\" aria-hidden=\"true\"></span>\n                <span class=\"lb-astory__photo\"><img src=\"/assets/templates/redesign/img/about-me-v2.webp\" width=\"920\" height=\"1227\" alt=\"{\'lbar.rd.ab.name\' | lexicon}\" loading=\"lazy\" decoding=\"async\"></span>\n            </div>\n        </div>\n\n        <div class=\"lb-astory__text\">\n            <p>{\'lbar.rd.ab.story.p1\' | lexicon}</p>\n            <p>{\'lbar.rd.ab.story.p2\' | lexicon}</p>\n            <blockquote class=\"lb-astory__quote\"><p>{\'lbar.rd.ab.story.quote\' | lexicon}</p></blockquote>\n            <p>{\'lbar.rd.ab.story.p3\' | lexicon}</p>\n            <p>{\'lbar.rd.ab.story.p4\' | lexicon}</p>\n            <ul class=\"lb-astory__chips\">\n                {foreach (\'lbar.rd.ab.story.chips\' | lexicon | split : \'|\') as $chip}\n                <li class=\"lb-astory__chip\">{$chip}</li>\n                {/foreach}\n            </ul>\n            <div class=\"lb-astory__sign\"><span class=\"lb-astory__sname\">{\'lbar.rd.ab.name\' | lexicon}</span><span class=\"lb-astory__srole\">{\'lbar.rd.ab.story.signrole\' | lexicon}</span></div>\n        </div>\n    </div>\n\n    <ul class=\"lb-astory__nums\">\n        {foreach [1, 2, 3, 4] as $i}\n        <li class=\"lb-astory__num{if $i == 4} lb-astory__num--word{/if}\">\n            <span class=\"lb-astory__nv\">{(\'lbar.rd.ab.num.\' ~ $i ~ \'v\') | lexicon}{if $i < 4}<span class=\"lb-astory__nu\">{(\'lbar.rd.ab.num.\' ~ $i ~ \'u\') | lexicon}</span>{/if}</span>\n            <span class=\"lb-astory__nt\">{(\'lbar.rd.ab.num.\' ~ $i ~ \'t\') | lexicon}</span>\n        </li>\n        {/foreach}\n    </ul>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-astory.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (324,1,0,'lb-avalues','Редизайн',0,128,0,'{* Страница «О нас» (шаг 47): «Мой принцип» (цитата с подписью и фото) и «Ценности» — H2, короткий текст, четыре карточки\n   (первая тёмная, как в макете). Верх блока — волна из тёмного «Шесть шагов» (как «Мастер» → «Галерея» на главной).\n   Тексты — лексикон lbar.rd.ab.man.* / val.* . *}\n{$_modx->lexicon->load(\'babel:translate\')}\n<section class=\"lb-avalues\" id=\"lb-avalues\">\n    <div class=\"lb-avalues__bg\" aria-hidden=\"true\"></div>\n\n    <div class=\"lb-avalues__inner\">\n        <figure class=\"lb-avalues__man\">\n            <blockquote class=\"lb-avalues__quote\"><p>{\'lbar.rd.ab.man.text\' | lexicon} <span class=\"lb-avalues__tail\">{\'lbar.rd.ab.man.tail\' | lexicon}</span></p></blockquote>\n            <figcaption class=\"lb-avalues__author\">\n                <img class=\"lb-avalues__ava\" src=\"/assets/templates/redesign/img/about-avatar.webp\" width=\"160\" height=\"160\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n                <span class=\"lb-avalues__who\"><span class=\"lb-avalues__name\">{\'lbar.rd.ab.name\' | lexicon}</span><span class=\"lb-avalues__role\">{\'lbar.rd.ab.man.role\' | lexicon}</span></span>\n            </figcaption>\n        </figure>\n\n        <div class=\"lb-avalues__head\">\n            <h2 class=\"lb-avalues__title\"><span class=\"lb-avalues__t1\">{\'lbar.rd.ab.val.h2a\' | lexicon}</span> <span class=\"lb-avalues__t2\">{\'lbar.rd.ab.val.h2b\' | lexicon}</span></h2>\n            <p class=\"lb-avalues__side\">{\'lbar.rd.ab.val.side\' | lexicon}</p>\n        </div>\n        <ul class=\"lb-avalues__list\">\n            {foreach [1, 2, 3, 4] as $i}\n            <li class=\"lb-avalues__card{if $i == 1} lb-avalues__card--dark{/if}\">\n                <span class=\"lb-avalues__n\" aria-hidden=\"true\">0{$i}</span>\n                <span class=\"lb-avalues__t\">{(\'lbar.rd.ab.val.\' ~ $i ~ \'t\') | lexicon}</span>\n                <span class=\"lb-avalues__d\">{(\'lbar.rd.ab.val.\' ~ $i ~ \'d\') | lexicon}</span>\n            </li>\n            {/foreach}\n        </ul>\n    </div>\n</section>\n',0,NULL,1,'core/elements/redesign/chunks/lb-avalues.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (325,1,0,'lb-schema-series','Редизайн',0,128,0,'{* Микроразметка CreativeWorkSeries страниц услуг (шаг 50) — вместо старого script-creativeworkseries-scheme (он не меняется):\n   число оценок (ratingCount) — параметр &reviews из шаблона (135), а не ecMessagesCount; оценка — ecThreadRatingMicro, если у страницы\n   своих оценок нет (EN-версии) — 5 (как в lb-script). *}\n{set $rate = $_modx->runSnippet(\'ecThreadRatingMicro\') | trim}\n{if !$rate || $rate == \'0\'}{set $rate = 5}{/if}\n<script type=\"application/ld+json\">\n{\n    \"@context\": \"https://schema.org/\",\n    \"@type\": \"CreativeWorkSeries\",\n    \"name\": \"[[*pagetitle]]\",\n    \"aggregateRating\": {\n        \"@type\": \"AggregateRating\",\n        \"ratingValue\": \"{$rate}\",\n        \"bestRating\": \"5\",\n        \"ratingCount\": \"{$reviews ?: 135}\"\n    }\n}\n</script>\n',0,NULL,1,'core/elements/redesign/chunks/lb-schema-series.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (326,1,0,'lb-script','Редизайн',0,128,0,'{* Скрипты и микроразметка страниц услуг (шаг 50) — копия старого чанка script (он сам не меняется: стоит на остальных шаблонах).\n   Отличия: число отзывов в aggregateRating (ProfessionalService / LocalBusiness) — параметр &reviews из шаблона («Категория» 8 и\n   «Категория NEW» 19 передают 135), а не ecMessagesCount (отзывы easyComm этой страницы); оценка — ecThreadRatingMicro, а если у страницы\n   своих оценок нет (EN-версии) — 5, поэтому aggregateRating есть на каждой странице услуги; убран лишний «]]» после JSON WebSite\n   (в старом чанке из-за него JSON невалиден). *}\n{set $rate = $_modx->runSnippet(\'ecThreadRatingMicro\') | trim}\n{if !$rate || $rate == \'0\'}{set $rate = 5}{/if}\n{disableSource}\n    <link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n<script src=\"/assets/templates/js/jquery-3.2.0.min.js\"></script>\n<script src=\"/assets/templates/js/jquery-migrate-3.0.0.min.js\"></script>\n<script>var $ = jQuery;</script>\n<script src=\"/assets/templates/js/main.js\"></script>\n<script src=\"/assets/templates/js/custom.js\"></script>\n<script src=\"/assets/soc-share/soc-share.js\"></script>\n<!--<script async src=\"https://maps.googleapis.com/maps/api/js?key=AIzaSyB3aTlJzCMv6opFNcZtoI-gzymZOc9nSNA&language=uk&region=UA&callback=initMap\"></script>-->\n[[$inttelinput]]\n<script>\n$(document).on(\'af_complete\', function(event, response) {\n    var form = response.form;\n    if (response.success) { //Если форма заполнена и нет ошибок\n        if (form.attr(\'id\') == \'form-bl4\') {\n            window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n        }\n        if (form.attr(\'id\') == \'form-bl8\') {\n            window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n        }\n        if (form.attr(\'id\') == \'form-study-banner\') {\n            window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n        }\n        if (form.attr(\'id\') == \'form-study-bl2\') {\n            window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n        }\n        if (form.attr(\'id\') == \'form-study-bl18\') {\n            window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n        }\n    }\n    // Отменяем вывод стандартного сообщения\n    response.message=\'\';\n});\n{/disableSource}\n</script>\n\n<script type=\"application/ld+json\">\n	{\n        \"@context\": \"https://schema.org\",\n        \"@type\": \"ProfessionalService\",\n        \"image\": \"https://lbar.ro/images/design/logo-schema.jpg\",\n        \"@id\": \"[[!++site_url]]\",\n        \"name\": \"[[++site_name]]\",\n        \"logo\": \"https://lbar.ro/images/design/logo.png\",\n        \"description\": \"Micropigmentare Bucuresti, tatuaj în salonul Lbar\",\n        \"email\": \"[[++e-mail]]\",\n        \"priceRange\": \"[[*seo-price-range:empty=`0`]]\",\n        \"address\": {\n                \"@type\": \"PostalAddress\",\n                \"streetAddress\": \"București, Sector 1, Strada Polonă 92\",\n                \"addressLocality\": \"București\",\n                \"addressRegion\": \"Bucuresti\",\n                \"postalCode\": \"010496\",\n                \"addressCountry\": \"RO\"\n				},\n        \"geo\": {\n			\"@type\": \"GeoCoordinates\",\n			\"latitude\": 44.4523683,\n			\"longitude\": 26.1017169\n		},\n		\"url\": \"[[!++site_url]]\",\n		\"telephone\": \"[[++phone-1]]\",\n		\"aggregateRating\": {\n          \"@type\": \"AggregateRating\",\n          \"ratingValue\": {$rate},\n          \"reviewCount\": {$reviews ?: 135}\n        },\n		\"openingHoursSpecification\": [\n			{\n			\"@type\": \"OpeningHoursSpecification\",\n			\"dayOfWeek\": [\n				\"Monday\",\n				\"Tuesday\",\n				\"Wednesday\",\n				\"Thursday\",\n				\"Friday\",\n				\"Saturday\",\n				\"Sunday\"\n				],\n				\"opens\": \"09:00\",\n				\"closes\": \"20:00\"\n			}\n		]\n	}\n</script>\n<script type=\"application/ld+json\">\n	{\n        \"@context\": \"https://schema.org\",\n        \"@type\": \"LocalBusiness\",\n        \"image\": \"https://lbar.ro/images/design/logo-schema.jpg\",\n        \"@id\": \"[[!++site_url]]#localbusiness\",\n        \"name\": \"[[++site_name]]\",\n        \"logo\": \"https://lbar.ro/images/design/logo.png\",\n        \"description\": \"Micropigmentare Bucuresti, tatuaj în salonul Lbar\",\n        \"email\": \"[[++e-mail]]\",\n        \"priceRange\": \"[[*seo-price-range:empty=`0`]]\",\n        \"address\": {\n                \"@type\": \"PostalAddress\",\n                \"streetAddress\": \"București, Sector 1, Strada Polonă 92\",\n                \"addressLocality\": \"București\",\n                \"addressRegion\": \"Bucuresti\",\n                \"postalCode\": \"010496\",\n                \"addressCountry\": \"RO\"\n				},\n        \"geo\": {\n			\"@type\": \"GeoCoordinates\",\n			\"latitude\": 44.4523683,\n			\"longitude\": 26.1017169\n		},\n		\"url\": \"[[!++site_url]]\",\n		\"telephone\": \"[[++phone-1]]\",\n		\"aggregateRating\": {\n          \"@type\": \"AggregateRating\",\n          \"ratingValue\": {$rate},\n          \"reviewCount\": {$reviews ?: 135}\n        },\n		\"openingHoursSpecification\": [\n			{\n			\"@type\": \"OpeningHoursSpecification\",\n			\"dayOfWeek\": [\n				\"Monday\",\n				\"Tuesday\",\n				\"Wednesday\",\n				\"Thursday\",\n				\"Friday\",\n				\"Saturday\",\n				\"Sunday\"\n				],\n				\"opens\": \"09:00\",\n				\"closes\": \"20:00\"\n			}\n		]\n	}\n</script>\n\n<script type=\"application/ld+json\">\n   {\n      \"@context\": \"http://schema.org\",\n      \"@type\": \"WebSite\",\n      \"name\": \"[[++site_name]]\",\n      \"url\": \"[[!++site_url]]\"\n      }\n</script>\n',0,NULL,1,'core/elements/redesign/chunks/lb-script.tpl');
REPLACE INTO `Impulse_Digital_X_site_htmlsnippets` VALUES (330,1,0,'lb-tzexamples','Редизайн',0,128,0,'{* Удаление тату (шаблон «Категория NEW», шаг 62): «Цена на примерах» — под таблицей цен, внутри старого блока bl5-service-prices.\n   Данные — TV ресурса: tz_price_examples-title (заголовок H3) и MIGX tz_price_examples (фото, что удаляем, цена, примечание; в админке —\n   вкладка «Блок 5 - Цены»). Пока фото не загружено — графическая заглушка. Фото — по клику крупно (fancybox, как галерея страницы).\n   Стили — scss/_tzex.scss; подсказка «листайте» под лентой гаснет после прокрутки (redesign.js). Вызов — в bl5-service-prices (TV tz_price_examples :notempty → этот чанк).\n   Внимание: MODX-теги в этом комментарии не писать — MODX разбирает их раньше Fenom (вызов самого себя → рекурсия, шаг 62). *}\n{set $r = $_modx->resource}\n{set $list = ($r[\'tz_price_examples\'] ?: \'[]\') | fromJSON}\n{set $title = $r[\'tz_price_examples-title\'] | trim}\n{if $list}\n<div class=\"lb-tzex\">\n    {if $title}<h3 class=\"lb-tzex__title\">{$title}</h3>{/if}\n    <ul class=\"lb-tzex__list\">\n        {foreach $list as $it}\n        {set $src = $it.image | trim}\n        {if $src && !($src | ematch : \'~^(/|https?:)~\')}{set $src = \'/\' ~ $src}{/if}\n        {set $name = $it.title | trim}\n        <li class=\"lb-tzex__item\">\n            {if $src}\n            <a class=\"lb-tzex__photo\" href=\"{$src}\" data-fancybox=\"lb-tzex\" data-caption=\"{($name ~ \' — \' ~ ($it.price | trim)) | escape}\">\n                <img src=\"{$src}\" alt=\"{$name | escape}\" width=\"300\" height=\"300\" loading=\"lazy\" decoding=\"async\">\n            </a>\n            {else}\n            <div class=\"lb-tzex__photo lb-tzex__photo--empty\" aria-hidden=\"true\">\n                <svg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"7\" y=\"9\" width=\"34\" height=\"30\" rx=\"5\"/><circle cx=\"18\" cy=\"20\" r=\"3.5\"/><path d=\"m9 35 10-10 7 7 5-5 8 8\"/></svg>\n            </div>\n            {/if}\n            <div class=\"lb-tzex__body\">\n                <p class=\"lb-tzex__name\">{$name | replace : \' cm\' : \'&nbsp;cm\'}</p>{* «5 cm²» не рвётся по строкам *}\n                <p class=\"lb-tzex__price\">{$it.price | trim}</p>\n                {if $it.note | trim}<p class=\"lb-tzex__note\">{$it.note | trim}</p>{/if}\n            </div>\n        </li>\n        {/foreach}\n    </ul>\n    {* подсказка «листайте» — видна только на телефоне / планшете, где лента прокручивается (шаг 63) *}\n    <div class=\"lb-tzex__hint\" aria-hidden=\"true\">\n        <svg class=\"lb-tzex__hint-arr\" viewBox=\"0 0 68 12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 6h65M60 1l6 5-6 5\"/></svg>\n        <svg class=\"lb-tzex__hint-hand\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 13V4.5a1.75 1.75 0 0 1 3.5 0V11\"/><path d=\"M13.5 10.5a1.75 1.75 0 0 1 3.5 0V12\"/><path d=\"M17 11.5a1.75 1.75 0 0 1 3.5 0v3.5a7 7 0 0 1-7 7h-1.6a6.5 6.5 0 0 1-4.9-2.2l-3.4-3.9a1.8 1.8 0 0 1 2.6-2.5L10 15.2\"/></svg>\n    </div>\n</div>\n{/if}\n',0,NULL,1,'core/elements/redesign/chunks/lb-tzexamples.tpl');
-- шаблоны «Главная» (1), 404 (2), «Внутренняя» (3), блог (4, 5), «Спасибо» (6), «Категория» (8), «Контакты» (9), «Портфолио» (10), «Внутренняя - Галерея» (13), «Цены» (14), «Обучение» (15), «Отзывы» (16), «Категория NEW» (19), «Внутренняя - Обучение» (21)
