REPLACE INTO `Impulse_Digital_X_site_templates` VALUES (15,0,0,'Обучение','Template',0,15,'',0,'<!doctype html>\n<html lang=\"[[++cultureKey]]\">\n<head>\n    [[$head-study]]\n    [[$lb-head]]\n     {disableSource}\n    {ignore}[[++google-tag-head]]{/ignore}\n    {/disableSource}\n</head>\n<body class=\"wrapper lb-oldpage lb-legacy main-[[++cultureKey]]\">\n    [[++google-tag-body]]\n    [[$lb-header]]\n    [[$banner-study]]\n    [[$bl1-study-vugoda]]\n    [[*title-bl2-study:notempty=`[[$bl2-study-trener]]`]]\n    [[*title-bl3-study:notempty=`[[$bl3-study-school]]`]]\n    [[$bl4-study-video-slider]]\n    [[$bl5-study-program]]\n    [[*title-bl6-free:notempty=`[[bl6-study-free-master-class]]`]]\n    [[$bl7-study-portfolio]]\n    [[*title-bl8-price:notempty=`[[$bl8-study-price]]`]]\n    [[*title-bl9-nabor:notempty=`[[$bl9-study-nabor]]`]]\n    [[*title-bl10-info:notempty=`[[$bl10-study-info]]`]]\n    [[*title-bl11-calculator:notempty=`[[$bl11-study-calculator]]`]]\n    [[$bl12-study-form]]\n    [[*title-bl13-reviews:notempty=`[[$bl13-study-reviews]]`]]\n    [[$bl15-study-questions]]\n    [[$bl16-study-courses]]\n    [[$bl17-study-advantages]]\n    [[$bl18-study-succsess]]\n    [[$bl-contact]]\n    [[$lb-footer]]\n    <script src=\"/assets/templates/js/jquery-3.2.0.min.js\"></script>\n    <script src=\"/assets/templates/js/jquery-migrate-3.0.0.min.js\"></script>\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/owl.carousel.min.css\">\n    <link rel=\"stylesheet\" href=\"/assets/templates/css/owl.theme.default.min.css\">\n    <script src=\"/assets/templates/js/owl.carousel.min.js\"></script>\n    <script src=\"/assets/templates/js/lightbox.js\"></script>\n    <script src=\"/assets/templates/js/script.js\" defer></script>\n    <script defer src=\"https://maps.googleapis.com/maps/api/js?key=AIzaSyB3aTlJzCMv6opFNcZtoI-gzymZOc9nSNA&language=uk&region=UA&callback=initMap\"></script>\n    [[$inttelinput]]\n    <script>\n    $(\'.slimmenu .level1.active\').removeClass(\'active\');\n    $(\'.slimmenu .level1\').each((i, el) => {\n        if($(el).find(\'a\').prop(\'href\') == location.href) {\n            $(el).addClass(\'active\');\n        }\n    })\n    $(document).on(\'af_complete\', function(event, response) {\n        var form = response.form;\n        if (response.success) { //Если форма заполнена и нет ошибок\n            if (form.attr(\'id\') == \'form-study-banner\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl2\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl6\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl12\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl14\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl11\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl18\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n            if (form.attr(\'id\') == \'form-study-bl8\') {\n                window.location.href = \"[[++cultureKey:is=`ro`:then=`[[~40]]`:else=`[[~269]]`]]\"\n            }\n        }\n        // Отменяем вывод стандартного сообщения\n        response.message=\'\';\n    });\n    </script>\n<script type=\"application/ld+json\">\n	{\n        \"@context\": \"https://schema.org\",\n        \"@type\": \"ProfessionalService\",\n        \"image\": \"[[!++site_url]]images/design/logo-schema.jpg\",\n        \"@id\": \"[[!++site_url]]\",\n        \"name\": \"[[++site_name]]\",\n        \"logo\": \"[[!++site_url]]images/design/logo.png\",\n        \"description\": \"Micropigmentare Bucuresti, tatuaj în salonul Lbar\",\n        \"email\": \"[[++e-mail]]\",\n        \"priceRange\": \"[[*seo-price-range:empty=`0`]]\",\n        \"address\": {\n                \"@type\": \"PostalAddress\",\n                \"streetAddress\": \"București, Sector 1, Strada Polonă 92\",\n                \"addressLocality\": \"București\",\n                \"addressRegion\": \"Bucuresti\",\n                \"postalCode\": \"010496\",\n                \"addressCountry\": \"RO\"\n				},\n        \"geo\": {\n			\"@type\": \"GeoCoordinates\",\n			\"latitude\": 44.4523683,\n			\"longitude\": 26.1017169\n		},\n		\"url\": \"[[!++site_url]]\",\n		\"telephone\": \"[[++phone-1]]\",\n		\"aggregateRating\": {\n          \"@type\": \"AggregateRating\",\n          \"ratingValue\": 5,\n          \"reviewCount\": 13\n        },\n		\"openingHoursSpecification\": [\n			{\n			\"@type\": \"OpeningHoursSpecification\",\n			\"dayOfWeek\": [\n				\"Monday\",\n				\"Tuesday\",\n				\"Wednesday\",\n				\"Thursday\",\n				\"Friday\",\n				\"Saturday\",\n				\"Sunday\"\n				],\n				\"opens\": \"09:00\",\n				\"closes\": \"20:00\"\n			}\n		]\n	}\n</script>\n<script type=\"application/ld+json\">\n   {\n      \"@context\": \"http://schema.org\",\n      \"@type\": \"WebSite\",\n      \"name\": \"[[++site_name]]\",\n      \"url\": \"[[!++site_url]]\"\n      }\n</script>\n[[ecThreadRatingMicro:isnot=`0`:then=`[[$script-creativeworkseries-scheme]]`:else=``]]\n[[$lb-scripts]]\n</body>\n</html>',0,'a:0:{}',0,'');
